import { parseConfigLocaleEntries } from '../../scripts/shared.ts';

const CONFIG_FENCE_OPEN_RE = /^\s*```\s*ol:Config\s*$/;
const FENCE_CLOSE_RE = /^\s*```\s*$/;
const LOCALES_ENTRY_RE = /^\s*-\s*Locales\s*:\s*(.*)$/;

/**
 * The locales a document declares — the `Locales` field of its `ol:Config`
 * fence, in the order written.
 *
 * This is the seam that keeps a language plugin's font off documents that are
 * not in its language: a plugin claims locales, the document declares them,
 * and the preview matches the two ({@link documentDeclaresLocale}) instead of
 * restyling every document the moment the plugin is composed.
 *
 * Reads the first `Locales` entry only — a second one is a duplicate-field
 * error the validator already reports, and the first is the one it keeps.
 */
function getDocumentLocales(value: string): string[] {
  const text = String(value ?? '');

  if (!text.includes('Locales')) {
    return [];
  }

  let insideConfigFence = false;

  for (const line of text.split(/\r\n?|\n/u)) {
    if (!insideConfigFence) {
      insideConfigFence = CONFIG_FENCE_OPEN_RE.test(line);
      continue;
    }

    if (FENCE_CLOSE_RE.test(line)) {
      return [];
    }

    const localesMatch = line.match(LOCALES_ENTRY_RE);
    if (!localesMatch) {
      continue;
    }

    return Array.from(
      new Set(
        parseConfigLocaleEntries(localesMatch[1])
          .map((entry: { text: string }) => entry.text)
          .filter(Boolean),
      ),
    );
  }

  return [];
}

/**
 * Whether two locale tags mean the same language for styling purposes:
 * equal ignoring case, or one a subtag-boundary prefix of the other — so a
 * document that declares `km` still matches a plugin keyed `km-KH`, and a
 * plugin keyed `km` still matches a `km-KH` document.
 */
function localesMatch(documentLocale: string, claimedLocale: string): boolean {
  const declared = String(documentLocale ?? '')
    .trim()
    .toLowerCase();
  const claimed = String(claimedLocale ?? '')
    .trim()
    .toLowerCase();

  if (!declared || !claimed) {
    return false;
  }

  return (
    declared === claimed ||
    declared.startsWith(`${claimed}-`) ||
    claimed.startsWith(`${declared}-`)
  );
}

/** True when the document declares any of the locales a plugin claims. */
function documentDeclaresLocale(
  documentLocales: readonly string[],
  claimedLocales: readonly string[],
): boolean {
  return documentLocales.some((documentLocale) =>
    claimedLocales.some((claimedLocale) =>
      localesMatch(documentLocale, claimedLocale),
    ),
  );
}

export { documentDeclaresLocale, getDocumentLocales, localesMatch };
