import { hideChordDiagramPopup } from '../../chord-popup.ts';
import { refs, state } from '../../../../editor/scripts/shared.ts';

function applyOpenLyricPreviewControllerInteractionMethods(
  PreviewControllerClass,
) {
  Object.assign(PreviewControllerClass.prototype, {
    handleOpenLyricPreviewClick(this: any, eventTarget, event) {
      const keyStepButton = eventTarget?.closest(
        '.ol-song-view__structure-key-step',
      );

      if (keyStepButton && refs.openLyricPreview?.contains(keyStepButton)) {
        const structureKeyId = keyStepButton.getAttribute(
          'data-structure-key-id',
        );
        const nextKeyValue = keyStepButton.getAttribute(
          'data-structure-key-value',
        );

        if (!structureKeyId || !nextKeyValue) {
          return true;
        }

        event.preventDefault();

        state.openLyricStructureKeys = {
          ...(state.openLyricStructureKeys || {}),
          [structureKeyId]: nextKeyValue,
        };

        hideChordDiagramPopup();
        this.renderOpenLyric(this.getCurrentValue());
        return true;
      }

      const simplifyToggleButton = eventTarget?.closest(
        '[data-preview-action="toggle-open-lyric-simplify"]',
      );

      if (
        simplifyToggleButton &&
        refs.openLyricPreview?.contains(simplifyToggleButton)
      ) {
        event.preventDefault();

        state.openLyricSimplifyChords = !state.openLyricSimplifyChords;

        hideChordDiagramPopup();
        this.renderOpenLyric(this.getCurrentValue());
        return true;
      }

      const hideBarToggleButton = eventTarget?.closest(
        '[data-preview-action="toggle-open-lyric-hide-leading-bars"]',
      );

      if (
        hideBarToggleButton &&
        refs.openLyricPreview?.contains(hideBarToggleButton)
      ) {
        event.preventDefault();

        state.openLyricHideLeadingBars = !state.openLyricHideLeadingBars;

        hideChordDiagramPopup();
        this.renderOpenLyric(this.getCurrentValue());
        return true;
      }

      const hideKeysToggleButton = eventTarget?.closest(
        '[data-preview-action="toggle-open-lyric-hide-keys"]',
      );

      if (
        hideKeysToggleButton &&
        refs.openLyricPreview?.contains(hideKeysToggleButton)
      ) {
        event.preventDefault();

        state.openLyricHideKeys = !state.openLyricHideKeys;

        hideChordDiagramPopup();
        this.renderOpenLyric(this.getCurrentValue());
        return true;
      }

      return false;
    },

    handleOpenLyricPreviewChange(this: any, eventTarget, _event) {
      const keySelect = eventTarget?.closest(
        '.ol-song-view__structure-key-select',
      );

      if (!keySelect || !refs.openLyricPreview?.contains(keySelect)) {
        return false;
      }

      const structureKeyId = keySelect.getAttribute('data-structure-key-id');
      if (!structureKeyId) {
        return true;
      }

      state.openLyricStructureKeys = {
        ...(state.openLyricStructureKeys || {}),
        [structureKeyId]: keySelect.value,
      };

      hideChordDiagramPopup();
      this.renderOpenLyric(this.getCurrentValue());
      return true;
    },
  });
}

export { applyOpenLyricPreviewControllerInteractionMethods };
