import { parseOpenLyricFences } from '../../domain/fence-locations.ts';
import {
  getKeyDiatonicTriads,
  parseMainKey,
} from '../../domain/music-theory.ts';
import {
  CHORD_SYMBOL_SOURCE,
  getCurrentValue,
  hasChordProgressionText,
} from '../../../../editor/scripts/shared.ts';

/**
 * The chord picker inside the in-preview section editor.
 *
 * A reader editing a section's lyrics in the markdown preview should not have
 * to know that a chord is written `[C#m]`. The "Insert chord" button under the
 * section textarea opens a panel of chords to tap — the ones the song already
 * uses, the chords of the song's key, and a root + quality + bass builder for
 * anything else — and a tap writes the chord *into the textarea* at the caret.
 *
 * Nothing here touches the document. The textarea is the section editor's
 * draft; the reader's Save is still the one write-back
 * (`section-editing.ts` → `replaceDocumentLineRange`), so a chord inserted and
 * saved is one undo step together with the rest of the edit, and Cancel
 * throws it away like any other typing.
 *
 * Notation is decided by the section (`OLFenceDefinition
 * .getPreviewChordInsertStyle`, carried on the pencil as
 * `data-preview-chord-style`): lyric bodies get `[G]` before the syllable, a
 * progression body gets a bare, space-separated `G`, and a mixed body decides
 * per line. The caret sitting on an existing chord swaps that chord rather
 * than stacking a second one on the same syllable.
 */

type ChordInsertStyle = 'annotation' | 'progression' | 'mixed';

type ChordInsertion = {
  text: string;
  start: number;
  end: number;
  insertText: string;
  caret: number;
  replaced: string;
};

const CHORD_INSERT_STYLES = new Set(['annotation', 'progression', 'mixed']);

const SONG_CHORD_LIMIT = 16;

const BARE_CHORD_RE = new RegExp(`^${CHORD_SYMBOL_SOURCE}$`);

const CHORD_ANNOTATION_GLOBAL_RE = new RegExp(
  String.raw`\[(${CHORD_SYMBOL_SOURCE})\]`,
  'g',
);

// Every bracketed span on a line, valid or not — the caret sitting on a
// mistyped `[Cmj7]` should replace it too, since that fixes it.
const BRACKETED_SPAN_RE = /\[[^[\]\n]*\]/g;

const PROGRESSION_SEPARATOR_RE =
  /(\{[^{}\r\n]+\}|\|\|:|\|:|:\|\||:\||\||\([1-9]\d*x\))/g;

const CONFIG_KEY_LINE_RE = /^\s*-\s*Key\s*:\s*(.*?)\s*$/i;

const ROOTS_MIXED = [
  'C',
  'C#',
  'D',
  'Eb',
  'E',
  'F',
  'F#',
  'G',
  'Ab',
  'A',
  'Bb',
  'B',
];
const ROOTS_SHARP = [
  'C',
  'C#',
  'D',
  'D#',
  'E',
  'F',
  'F#',
  'G',
  'G#',
  'A',
  'A#',
  'B',
];
const ROOTS_FLAT = [
  'C',
  'Db',
  'D',
  'Eb',
  'E',
  'F',
  'Gb',
  'G',
  'Ab',
  'A',
  'Bb',
  'B',
];

/**
 * The builder's qualities. Each suffix is one decoration group the chord
 * grammar accepts on its own, so root + quality + optional bass is always a
 * valid chord symbol.
 */
const CHORD_QUALITIES = [
  { suffix: '', label: 'Major', description: 'Major' },
  { suffix: 'm', label: 'm', description: 'Minor' },
  { suffix: '7', label: '7', description: 'Seventh' },
  { suffix: 'm7', label: 'm7', description: 'Minor seventh' },
  { suffix: 'maj7', label: 'maj7', description: 'Major seventh' },
  { suffix: 'sus2', label: 'sus2', description: 'Suspended second' },
  { suffix: 'sus4', label: 'sus4', description: 'Suspended fourth' },
  { suffix: 'add9', label: 'add9', description: 'Added ninth' },
  { suffix: '6', label: '6', description: 'Sixth' },
  { suffix: 'dim', label: 'dim', description: 'Diminished' },
  { suffix: 'aug', label: 'aug', description: 'Augmented' },
];

function normalizeChordInsertStyle(value): ChordInsertStyle {
  const style = String(value ?? '').trim();
  return CHORD_INSERT_STYLES.has(style)
    ? (style as ChordInsertStyle)
    : 'annotation';
}

function isValidChordSymbol(value) {
  return BARE_CHORD_RE.test(String(value ?? ''));
}

/** Root + quality + optional slash bass, or `''` when that is not a chord. */
function buildChordSymbol(root, quality = '', bass = '') {
  const rootText = String(root ?? '').trim();

  if (!rootText) {
    return '';
  }

  const bassText = String(bass ?? '').trim();
  const chord = `${rootText}${String(quality ?? '').trim()}${
    bassText && bassText !== rootText ? `/${bassText}` : ''
  }`;

  return isValidChordSymbol(chord) ? chord : '';
}

/** Does this line read as a chord progression rather than a sung line? */
function isProgressionLine(line) {
  const trimmedLine = String(line ?? '').trim();
  return (
    Boolean(trimmedLine) &&
    (hasChordProgressionText(trimmedLine) || /^\{[cp]:/.test(trimmedLine))
  );
}

function listBareChordTokens(line) {
  return String(line ?? '')
    .replace(PROGRESSION_SEPARATOR_RE, ' ')
    .split(/[\s\u200B]+/u)
    .filter((token) => isValidChordSymbol(token));
}

function collectLineChords(line, style: ChordInsertStyle, into: string[]) {
  for (const match of String(line ?? '').matchAll(CHORD_ANNOTATION_GLOBAL_RE)) {
    into.push(match[1]);
  }

  if (style === 'progression' || isProgressionLine(line)) {
    into.push(...listBareChordTokens(line));
  }
}

/**
 * Every chord the song already uses, in first-appearance order, deduplicated.
 *
 * `draftText` is the open section editor's textarea — not saved yet, but a
 * chord the reader has just inserted there is one they will want again on the
 * next line.
 */
function collectSongChords(markdown, draftText = '', limit = SONG_CHORD_LIMIT) {
  const chords: string[] = [];

  for (const fence of parseOpenLyricFences(markdown)) {
    if (fence.parsedHeader?.header === 'Config') {
      continue;
    }

    const style = normalizeChordInsertStyle(
      fence.parsedHeader?.definition?.getPreviewChordInsertStyle?.(),
    );

    for (const line of String(fence.body ?? '').split('\n')) {
      collectLineChords(line, style, chords);
    }
  }

  for (const line of String(draftText ?? '').split('\n')) {
    collectLineChords(line, 'annotation', chords);
  }

  return Array.from(new Set(chords)).slice(0, Math.max(0, limit));
}

/** The `Key` value of the document's `Config`, as written (`''` if none). */
function readConfigKeyText(markdown) {
  const configFence = parseOpenLyricFences(markdown).find(
    (fence) => fence.parsedHeader?.header === 'Config',
  );

  if (!configFence) {
    return '';
  }

  for (const line of String(configFence.body ?? '').split('\n')) {
    const match = line.match(CONFIG_KEY_LINE_RE);

    if (match) {
      return match[1];
    }
  }

  return '';
}

/**
 * The chords of the song's key, filtered to what the chord grammar accepts.
 * `null` when the `Key` is missing or unreadable.
 */
function getKeyChordSuggestions(keyText) {
  const key = parseMainKey(keyText);

  if (!key) {
    return null;
  }

  return {
    keyLabel: key.raw,
    chords: getKeyDiatonicTriads(key.raw).filter((chord) =>
      isValidChordSymbol(chord),
    ),
  };
}

/** The twelve roots, spelled the way the song's key spells accidentals. */
function getRootSpellings(keyText) {
  const key = parseMainKey(keyText);

  if (key?.alteration > 0) {
    return ROOTS_SHARP;
  }

  if (key?.alteration < 0) {
    return ROOTS_FLAT;
  }

  return ROOTS_MIXED;
}

/**
 * Where a chord goes in `text` for a caret at `selectionStart`, and what the
 * text becomes. Pure, so the notation rule is testable on its own.
 *
 * The chord lands at the caret; a selection is not overwritten (it is lyric
 * text the reader meant to keep). When the caret touches an existing chord —
 * inside `[E]`, or right before/after it — that chord is replaced instead,
 * since two chords on one syllable is never what was meant.
 */
function computeChordInsertion(
  text,
  selectionStart,
  chord,
  style: ChordInsertStyle = 'annotation',
): ChordInsertion | null {
  const sourceText = String(text ?? '');
  const chordText = String(chord ?? '').trim();

  if (!isValidChordSymbol(chordText)) {
    return null;
  }

  const caret = Math.min(
    Math.max(Math.trunc(Number(selectionStart) || 0), 0),
    sourceText.length,
  );
  const lineStart = sourceText.lastIndexOf('\n', caret - 1) + 1;
  const nextNewline = sourceText.indexOf('\n', caret);
  const lineEnd = nextNewline === -1 ? sourceText.length : nextNewline;
  const line = sourceText.slice(lineStart, lineEnd);
  const column = caret - lineStart;
  const bare =
    style === 'progression' || (style === 'mixed' && isProgressionLine(line));

  const splice = (start, end, insertText, caretOffset, replaced = '') => ({
    text: `${sourceText.slice(0, start)}${insertText}${sourceText.slice(end)}`,
    start,
    end,
    insertText,
    caret: start + caretOffset,
    replaced,
  });

  if (!bare) {
    for (const match of line.matchAll(BRACKETED_SPAN_RE)) {
      const spanStart = match.index ?? 0;
      const spanEnd = spanStart + match[0].length;

      if (column >= spanStart && column <= spanEnd) {
        const insertText = `[${chordText}]`;
        return splice(
          lineStart + spanStart,
          lineStart + spanEnd,
          insertText,
          insertText.length,
          match[0],
        );
      }
    }

    const insertText = `[${chordText}]`;
    return splice(caret, caret, insertText, insertText.length);
  }

  for (const match of line.matchAll(/\S+/g)) {
    const tokenStart = match.index ?? 0;
    const tokenEnd = tokenStart + match[0].length;

    // Inside a chord or right before it swaps it; right *after* it is where
    // the next chord of the progression goes, so that one appends.
    if (
      column >= tokenStart &&
      column < tokenEnd &&
      isValidChordSymbol(match[0])
    ) {
      return splice(
        lineStart + tokenStart,
        lineStart + tokenEnd,
        chordText,
        chordText.length,
        match[0],
      );
    }
  }

  const before = column > 0 && !/\s/.test(line[column - 1]) ? ' ' : '';
  const after = column < line.length && !/\s/.test(line[column]) ? ' ' : '';
  const insertText = `${before}${chordText}${after}`;

  return splice(caret, caret, insertText, insertText.length);
}

function createElement(tagName, className, attributes = {}) {
  const element = document.createElement(tagName);
  element.className = className;

  for (const [name, value] of Object.entries(attributes)) {
    element.setAttribute(name, String(value));
  }

  return element;
}

function createChordGroup(heading, idSuffix) {
  const group = createElement('div', 'ol-preview-chord-picker__group', {
    role: 'group',
  });
  const headingElement = createElement(
    'p',
    'ol-preview-chord-picker__heading',
    { id: `ol-preview-chord-picker-heading-${idSuffix}` },
  );
  const options = createElement('div', 'ol-preview-chord-picker__options');

  headingElement.textContent = heading;
  group.setAttribute('aria-labelledby', headingElement.id);
  group.append(headingElement, options);

  return { group, options };
}

function createChordChip(chord) {
  const chip = createElement(
    'button',
    'ol-preview-chord-picker__chip ol-preview-chord-picker__chip--chord',
    {
      type: 'button',
      'data-preview-action': 'section-chord-insert',
      'data-chord': chord,
      'aria-label': `Insert ${chord}`,
    },
  );
  chip.textContent = chord;
  return chip;
}

function applyPreviewControllerSectionChordMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    /**
     * The "Insert chord" toggle plus its (initially hidden) panel, built once
     * per section editor. The panel's contents are filled on open, from the
     * document as it is then.
     */
    buildPreviewSectionChordTools(this: any, { chordStyle, sectionLabel }) {
      const idSuffix = Math.random().toString(36).slice(2, 10);
      const tools = createElement('div', 'ol-preview-chord-tools');
      const toggle = createElement('button', 'ol-preview-chord-tools__toggle', {
        type: 'button',
        'data-preview-action': 'section-chord-toggle',
        'aria-expanded': 'false',
        'aria-controls': `ol-preview-chord-picker-${idSuffix}`,
      });
      const panel = createElement('div', 'ol-preview-chord-picker', {
        id: `ol-preview-chord-picker-${idSuffix}`,
        role: 'group',
        'aria-label': `Insert a chord into ${sectionLabel || 'this section'}`,
      });
      const status = createElement('p', 'ol-preview-chord-picker__status', {
        role: 'status',
        'aria-live': 'polite',
      });

      toggle.innerHTML =
        '<span class="ol-preview-chord-tools__toggle-icon" aria-hidden="true">♪</span><span>Insert chord</span>';
      panel.hidden = true;
      tools.append(toggle, panel);

      return {
        tools,
        chordPicker: {
          toggle,
          panel,
          status,
          idSuffix,
          chordStyle: normalizeChordInsertStyle(chordStyle),
          root: '',
          quality: '',
          bass: '',
          buildInsertButton: null,
        },
      };
    },

    getPreviewSectionChordPicker(this: any) {
      const chordPicker = this.previewSectionEditor?.chordPicker;
      return chordPicker?.panel?.isConnected ? chordPicker : null;
    },

    isPreviewSectionChordPickerOpen(this: any) {
      const chordPicker = this.getPreviewSectionChordPicker();
      return Boolean(chordPicker && !chordPicker.panel.hidden);
    },

    renderPreviewSectionChordPicker(this: any, chordPicker) {
      const markdown = String(getCurrentValue() ?? '');
      const draftText = String(
        this.previewSectionEditor?.textarea?.value ?? '',
      );
      const keyText = readConfigKeyText(markdown);
      const songChords = collectSongChords(markdown, draftText);
      const keyChords = getKeyChordSuggestions(keyText);
      const roots = getRootSpellings(keyText);
      const { panel, status, idSuffix } = chordPicker;

      panel.replaceChildren();
      status.textContent =
        chordPicker.chordStyle === 'progression'
          ? 'Tap a chord to add it where the cursor is.'
          : 'Put the cursor just before the word the chord is played on, then tap a chord.';

      if (songChords.length) {
        const { group, options } = createChordGroup(
          'In this song',
          `song-${idSuffix}`,
        );
        options.append(...songChords.map((chord) => createChordChip(chord)));
        panel.append(group);
      }

      if (keyChords?.chords.length) {
        const { group, options } = createChordGroup(
          `Key of ${keyChords.keyLabel}`,
          `key-${idSuffix}`,
        );
        options.append(
          ...keyChords.chords.map((chord) => createChordChip(chord)),
        );
        panel.append(group);
      }

      const builder = createElement('div', 'ol-preview-chord-picker__builder', {
        role: 'group',
        'aria-labelledby': `ol-preview-chord-picker-heading-build-${idSuffix}`,
      });
      const builderHeading = createElement(
        'p',
        'ol-preview-chord-picker__heading',
        { id: `ol-preview-chord-picker-heading-build-${idSuffix}` },
      );
      builderHeading.textContent = 'Build a chord';

      const rootRow = createElement('div', 'ol-preview-chord-picker__options', {
        role: 'group',
        'aria-label': 'Root note',
      });
      rootRow.append(
        ...roots.map((root) => {
          const button = createElement(
            'button',
            'ol-preview-chord-picker__chip',
            {
              type: 'button',
              'data-preview-action': 'section-chord-root',
              'data-chord-root': root,
              'aria-pressed': String(root === chordPicker.root),
            },
          );
          button.textContent = root;
          return button;
        }),
      );

      const qualityRow = createElement(
        'div',
        'ol-preview-chord-picker__options',
        { role: 'group', 'aria-label': 'Chord type' },
      );
      qualityRow.append(
        ...CHORD_QUALITIES.map(({ suffix, label, description }) => {
          const button = createElement(
            'button',
            'ol-preview-chord-picker__chip',
            {
              type: 'button',
              'data-preview-action': 'section-chord-quality',
              'data-chord-quality': suffix,
              'aria-pressed': String(suffix === chordPicker.quality),
              title: description,
            },
          );
          button.textContent = label;
          return button;
        }),
      );

      const bassLabel = createElement('label', 'ol-preview-chord-picker__bass');
      const bassText = createElement(
        'span',
        'ol-preview-chord-picker__bass-label',
      );
      const bassSelect = createElement(
        'select',
        'ol-preview-chord-picker__bass-select',
        { 'data-preview-action': 'section-chord-bass' },
      );
      bassText.textContent = 'Bass note';
      const noBass = document.createElement('option');
      noBass.value = '';
      noBass.textContent = 'Same as root';
      bassSelect.append(
        noBass,
        ...roots.map((root) => {
          const option = document.createElement('option');
          option.value = root;
          option.textContent = `/${root}`;
          return option;
        }),
      );
      bassSelect.value = roots.includes(chordPicker.bass)
        ? chordPicker.bass
        : '';
      bassLabel.append(bassText, bassSelect);

      const buildInsertButton = createElement(
        'button',
        'ol-preview-chord-picker__insert',
        {
          type: 'button',
          'data-preview-action': 'section-chord-insert-built',
        },
      );

      chordPicker.buildInsertButton = buildInsertButton;
      this.syncPreviewSectionChordBuilder(chordPicker);

      const builderFooter = createElement(
        'div',
        'ol-preview-chord-picker__builder-footer',
      );
      builderFooter.append(bassLabel, buildInsertButton);
      builder.append(builderHeading, rootRow, qualityRow, builderFooter);
      panel.append(builder, status);
    },

    /** Reflect the builder's picks on its toggles and its Insert button. */
    syncPreviewSectionChordBuilder(this: any, chordPicker) {
      const { panel, buildInsertButton } = chordPicker;
      const chord = buildChordSymbol(
        chordPicker.root,
        chordPicker.quality,
        chordPicker.bass,
      );

      panel
        .querySelectorAll('[data-preview-action="section-chord-root"]')
        .forEach((button) => {
          button.setAttribute(
            'aria-pressed',
            String(button.getAttribute('data-chord-root') === chordPicker.root),
          );
        });
      panel
        .querySelectorAll('[data-preview-action="section-chord-quality"]')
        .forEach((button) => {
          button.setAttribute(
            'aria-pressed',
            String(
              button.getAttribute('data-chord-quality') === chordPicker.quality,
            ),
          );
        });

      if (buildInsertButton instanceof HTMLButtonElement) {
        buildInsertButton.disabled = !chord;
        buildInsertButton.textContent = chord
          ? `Insert ${chord}`
          : 'Pick a root note';
        buildInsertButton.setAttribute('data-chord', chord);
      }
    },

    openPreviewSectionChordPicker(this: any) {
      const chordPicker = this.getPreviewSectionChordPicker();

      if (!chordPicker) {
        return false;
      }

      this.renderPreviewSectionChordPicker(chordPicker);
      chordPicker.panel.hidden = false;
      chordPicker.toggle.setAttribute('aria-expanded', 'true');
      // No focus move into the panel: the textarea keeps its caret, which is
      // where the chord goes, and on touch iOS focusing a button right after
      // it opens would swallow the next tap.
      return true;
    },

    closePreviewSectionChordPicker(this: any, { focusToggle = false } = {}) {
      const chordPicker = this.getPreviewSectionChordPicker();

      if (!chordPicker || chordPicker.panel.hidden) {
        return false;
      }

      chordPicker.panel.hidden = true;
      chordPicker.toggle.setAttribute('aria-expanded', 'false');

      if (focusToggle) {
        this.focusElement(chordPicker.toggle, {
          preventScroll: true,
          skipTouchIosForButtons: true,
        });
      }

      return true;
    },

    togglePreviewSectionChordPicker(this: any) {
      return this.isPreviewSectionChordPickerOpen()
        ? this.closePreviewSectionChordPicker()
        : this.openPreviewSectionChordPicker();
    },

    /**
     * Put `chord` into the section textarea at its caret. The textarea is a
     * draft — the document changes only when the reader saves.
     */
    insertPreviewSectionChord(this: any, chord) {
      const sectionEditor = this.previewSectionEditor;
      const textarea = sectionEditor?.textarea;

      if (!(textarea instanceof HTMLTextAreaElement) || !textarea.isConnected) {
        return false;
      }

      const insertion = computeChordInsertion(
        textarea.value,
        textarea.selectionStart,
        chord,
        sectionEditor.chordPicker?.chordStyle,
      );

      if (!insertion) {
        return false;
      }

      // The caret is the chord's destination, and a text field is the one
      // sanctioned auto-focus target on touch iOS.
      this.focusElement(textarea, { preventScroll: true });
      textarea.setSelectionRange(insertion.start, insertion.end);

      // `insertText` keeps the insertion on the textarea's own undo stack, so
      // Ctrl/Cmd+Z inside the editor takes back just the chord. Where it is
      // unavailable (or edits something else), the value is set directly.
      let insertedNatively = false;

      try {
        insertedNatively = Boolean(
          document.execCommand?.('insertText', false, insertion.insertText),
        );
      } catch {
        insertedNatively = false;
      }

      if (!insertedNatively || textarea.value !== insertion.text) {
        textarea.value = insertion.text;
      }

      textarea.setSelectionRange(insertion.caret, insertion.caret);

      const chordText = String(chord).trim();
      const status = sectionEditor.chordPicker?.status;

      if (status instanceof HTMLElement) {
        status.textContent = insertion.replaced
          ? `Changed ${insertion.replaced} to ${chordText}.`
          : `Added ${chordText}.`;
      }

      return true;
    },

    /** The delegated click listener's entry point for picker controls. */
    handlePreviewSectionChordAction(this: any, control) {
      if (!(control instanceof HTMLElement)) {
        return false;
      }

      const action = control.getAttribute('data-preview-action');

      if (action === 'section-chord-toggle') {
        return this.togglePreviewSectionChordPicker();
      }

      const chordPicker = this.getPreviewSectionChordPicker();

      if (!chordPicker || !chordPicker.panel.contains(control)) {
        return false;
      }

      if (action === 'section-chord-insert') {
        return this.insertPreviewSectionChord(
          control.getAttribute('data-chord'),
        );
      }

      if (action === 'section-chord-insert-built') {
        return this.insertPreviewSectionChord(
          buildChordSymbol(
            chordPicker.root,
            chordPicker.quality,
            chordPicker.bass,
          ),
        );
      }

      if (action === 'section-chord-root') {
        chordPicker.root = control.getAttribute('data-chord-root') || '';
        this.syncPreviewSectionChordBuilder(chordPicker);
        return true;
      }

      if (action === 'section-chord-quality') {
        chordPicker.quality = control.getAttribute('data-chord-quality') || '';
        this.syncPreviewSectionChordBuilder(chordPicker);
        return true;
      }

      return false;
    },

    setPreviewSectionChordBass(this: any, control) {
      const chordPicker = this.getPreviewSectionChordPicker();

      if (
        !chordPicker ||
        !(control instanceof HTMLSelectElement) ||
        !chordPicker.panel.contains(control)
      ) {
        return false;
      }

      chordPicker.bass = control.value;
      this.syncPreviewSectionChordBuilder(chordPicker);
      return true;
    },
  });
}

export {
  CHORD_QUALITIES,
  applyPreviewControllerSectionChordMethods,
  buildChordSymbol,
  collectSongChords,
  computeChordInsertion,
  getKeyChordSuggestions,
  getRootSpellings,
  readConfigKeyText,
};
