import { EditorStandaloneChrome } from './internal/EditorStandaloneChrome.ts';
import {
  ensureFontFacesInjected,
  ensureFontFacesLoaded,
} from './internal/font-styles.ts';
import {
  measureFontSizePx,
  normalizeFontSize,
  resolveFontSizePx,
} from './internal/font-size.ts';
import { GOOGLE_SANS_FONT_FAMILY } from '../styles/google-sans-font.ts';
import { ensureEditorShellStylesInjected } from './internal/shell-styles.ts';
import { OpenLyricComponent } from './internal/OpenLyricComponent.ts';
import {
  defaultLoadMonacoResources,
  getEditorThemeName,
  loadOpenLyricMonaco,
  type LoadMonacoResources,
} from './internal/monaco-boot.ts';
import type {
  OpenLyricComponentOptions,
  OpenLyricEditorLike,
  OpenLyricSavePayload,
  OpenLyricSurface,
  OpenLyricTheme,
} from './internal/types.ts';
import {
  OL_FENCE_HEADER_CONTENT_COLUMN,
  listOpenLyricFences,
  toOpenLyricFenceTargetId,
  type OpenLyricFenceLocation,
} from '../../plugins/OpenLyric/domain/fence-locations.ts';
import {
  buildVerticalLineBackground,
  buildVerticalLineWidthCss,
  measureCharacterWidthPx,
  measureTextStartOffsetPx,
  nextVerticalLinesScopeId,
  normalizeVerticalLines,
  toMonacoRulers,
  VERTICAL_LINES_SCOPE_ATTRIBUTE,
  type EditorVerticalLine,
  type ResolvedEditorVerticalLine,
} from './internal/vertical-lines.ts';
import { installEditorPanelMarkup } from '../html/install-editor-panel-markup.ts';
import { installEditorSelectionStats } from '../scripts/selection-stats.ts';
import {
  LANGUAGE_ID,
  MONACO_WORD_SEPARATORS,
  refreshElementRefs,
} from '../scripts/shared.ts';

/** Which surface a mounted `Editor` is currently editing through. */
export type EditorSurfaceKind = 'monaco' | 'textarea' | 'none';

/**
 * What the editor surfaces render text with, behind the host override (see
 * {@link Editor.resolvedFontFamily}).
 *
 * It leads with the app-shipped Latin family the components declare and load
 * themselves (`styles/google-sans-font.ts`) — the same face the app shell's
 * Monaco asks for, so a standalone embed and the full page render the code
 * being edited identically. Behind it sits the Simple Editor font of the panel
 * stylesheet (`.editor-panel__simple-input` in
 * `styles/_editor-panel-chrome.scss`) extended with Monaco's own per-platform
 * defaults, so both surfaces of one panel render text the same way; families
 * the system lacks are simply skipped, and any script no face here covers
 * falls through to the browser's own default for it.
 */
const EDITOR_FONT_BASE_STACK =
  `${GOOGLE_SANS_FONT_FAMILY}, 'Cascadia Mono', 'Fira Code', Consolas, ` +
  "'Courier New', Menlo, Monaco, 'Droid Sans Mono', monospace";

/**
 * Monaco's own default, for the case where the instance cannot be asked (a
 * host-supplied runtime that exposes neither option reader).
 */
const MONACO_DEFAULT_FONT_SIZE_PX = 14;

/**
 * The font size a Monaco instance is currently configured with, through
 * whichever of its two option readers the runtime exposes. Returns 0 when
 * neither answers, which callers read as "ask the constant instead".
 */
function readMonacoFontSizePx(monaco: any, editorInstance: any): number {
  const optionId = monaco?.editor?.EditorOption?.fontSize;
  const fromOption =
    optionId === undefined ? undefined : editorInstance?.getOption?.(optionId);
  const size = Number(
    fromOption ?? editorInstance?.getRawOptions?.()?.fontSize,
  );

  return Number.isFinite(size) && size > 0 ? size : 0;
}

/** Quote a face name that is not a bare CSS identifier sequence. */
function toCssFontFamily(name: string): string {
  if (/^[A-Za-z-][A-Za-z0-9 -]*$/.test(name)) {
    return name;
  }
  return `'${name.replace(/(['\\])/g, '\\$1')}'`;
}

export type {
  EditorVerticalLine,
  ResolvedEditorVerticalLine,
} from './internal/vertical-lines.ts';

export interface EditorOptions extends OpenLyricComponentOptions {
  /** Initial editor content. */
  value?: string;
  /** Override the Monaco runtime loader (defaults to the lazy chunk). */
  loadMonacoResources?: LoadMonacoResources;
  /** Model language id (defaults to the Open Lyric language). */
  language?: string;
  readOnly?: boolean;
  /**
   * Font family the editor surfaces render with. Empty (the default) means
   * "whatever the attached plugins contribute, else the base stack" — see
   * {@link Editor.resolvedFontFamily}.
   */
  fontFamily?: string;
  /**
   * Font size the editor surfaces render text at — any CSS length, or a bare
   * number read as pixels. Empty (the default) leaves Monaco's own size and
   * the panel stylesheet's in charge. See {@link Editor.fontSize}.
   */
  fontSize?: string | number;
  /**
   * Build the standalone editor chrome — the toolbar (Simple Editor switch,
   * undo/redo/clear/copy) and the `⋮` tools menu (Format, Keyboard, clipboard
   * actions, word wrap, invisible characters, auto-suggest, spellcheck, custom
   * dictionary, and the Word Count + Font Size settings row) — around the
   * surface. Defaults to `true`; pass `false` for a
   * bare surface whose chrome the host provides. Never built in shared-surface
   * (facade) mode, where the host application owns the chrome.
   */
  chrome?: boolean;
  /**
   * Show the live selection readout ("All: 128 words / 687 chars") in the
   * corner of the editor panel. Defaults to `false`; see
   * {@link Editor.isSelectionStateEnabled}, which toggles it at any time.
   */
  selectionState?: boolean;
  /**
   * Own the Ctrl/Cmd+S keystroke on the mounted surface: swallow the browser's
   * "Save page" dialog and emit the `save` event instead. Defaults to `true` —
   * an editor that lets Ctrl+S offer to download the page is never what a host
   * wants, and the event is inert until something listens for it. Pass `false`
   * to leave the keystroke untouched. See
   * {@link Editor.isSaveShortcutEnabled}, which toggles it at any time.
   */
  saveShortcut?: boolean;
  /**
   * Vertical rules down the editing surface, at a column each — the guides a
   * host draws a line length at. See {@link Editor.setVerticalLines}, which
   * replaces them at any time; empty (the default) draws none.
   */
  verticalLines?: Array<EditorVerticalLine | number>;
}

/**
 * Wrap-phase bridge to an editor surface owned by something else (the
 * application shell). All members are live accessors, so surface swaps on
 * the host side (Monaco ⇄ simple textarea) stay transparent.
 */
export interface EditorSharedSurfaceBridge {
  getValue(): string;
  setValue(next: string): void;
  focusRange(line: number, column: number): void;
  focus?(): void;
  getMonaco?(): unknown;
  getMonacoEditor?(): unknown;
}

interface DisposableLike {
  dispose?: () => void;
}

/** Where inside a fence {@link Editor.focusFence} leaves the caret. */
export type EditorFenceFocusTarget = 'header' | 'body';

export interface EditorFenceFocusOptions {
  /**
   * Which match to use when more than one fence answers — a document that
   * declares the same part twice. Validation flags that, but the caret still
   * has to be able to reach the second one. 1-based; defaults to the first.
   */
  occurrence?: number;
  /**
   * `'header'` (the default) lands on the part name in the ```` ```ol: ````
   * opening line — where double-clicking a preview section title lands.
   * `'body'` lands at the start of the first body line, falling back to the
   * header line for a fence with no body.
   */
  target?: EditorFenceFocusTarget;
}

/** Part names compare trimmed, whitespace-collapsed and case-folded. */
function normalizePartNameKey(value: unknown): string {
  return String(value ?? '')
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

/**
 * `Editor` — the standalone code editor (`gep`).
 *
 * Lazily boots Monaco with the Open Lyric language + theme into its own
 * container, with a plain-textarea fallback when Monaco cannot load. It
 * implements {@link OpenLyricEditorLike}, so it is exactly what the previews
 * bridge to: `editor` change events drive the preview, and a preview
 * double-click calls `focusRange` here to move the caret.
 *
 * Self-contained: it reuses the shared Monaco runtime chunk but wires nothing
 * into the global app (`state`/`refs`), and it ships the Latin `@font-face`
 * declarations the surface renders with (`internal/editor-font-styles.ts`), so
 * neither a page entry nor an embed imports a font stylesheet. Advanced editor
 * features (spellcheck, keyboard, transcript) arrive via the generic plugin
 * system.
 *
 * Wrap phase: {@link attachSharedSurface} turns an instance into a live
 * facade over an editor surface the application owns — value reads/writes,
 * `focusRange`, the Monaco getters, and `change` events all work against the
 * real surface, but the component mounts nothing of its own and its plugins
 * stay dormant (the application provides those features through its shell).
 */
export class Editor extends OpenLyricComponent implements OpenLyricEditorLike {
  readonly surface: OpenLyricSurface = 'editor';

  /**
   * Install the page-shell editor panel markup (`#editorPanel`) into the
   * page's `<template id="editorPanelMount">` placeholder — the editor
   * surface owns its shell panel. The page entries (`main-open-lyric.ts`,
   * `main-editor.ts`) call this before composing and booting the app; the
   * app's captured element refs refresh afterwards.
   * Idempotent, and a no-op on pages without the mount. On pages that also
   * compose the lyric preview, call this before
   * `OpenLyric.installShellMarkup()` — the OpenLyric shell mounts one of
   * its actions inside this panel.
   *
   * Also links the Latin `@font-face` sheet the editor surface renders with
   * (`internal/editor-font-styles.ts`), as early in page life as the entry
   * calls this — a page entry needs no font import of its own.
   */
  static installShellMarkup(): void {
    ensureFontFacesInjected();
    installEditorPanelMarkup();
    refreshElementRefs();
  }

  /**
   * Link the app-page stylesheets the editor panel's shell chrome needs —
   * the theme tokens, the panel chrome in `shell.scss`, and the
   * narrow-viewport overrides — into `document.head`, the CSS counterpart of
   * {@link installShellMarkup}. The page entries call one `installShellStyle()`
   * per composed surface class; the sheets are shared, idempotent, and always
   * land in canonical cascade order (see `internal/shell-styles.ts`), so the
   * pages ship no `<link rel="stylesheet">` of their own.
   *
   * Deliberately NOT called from {@link installShellMarkup}: a bare embed page
   * (e.g. `ol-lyric-editor.html`) runs the markup install for its font faces
   * alone, and the app-shell sheets would restyle that host's page. The Latin
   * `@font-face` sheet is included here too, so calling this static is enough
   * on a page that installs no markup.
   */
  static installShellStyle(): void {
    ensureFontFacesInjected();
    ensureEditorShellStylesInjected();
  }

  private valueText = '';
  private readonly language: string;
  private readonly readOnly: boolean;
  private readonly loadMonacoResources: LoadMonacoResources;
  private readonly chromeEnabled: boolean;
  private fontFamilyValue = '';
  /** True once a stack was pushed onto the surfaces (see applyFontFamily). */
  private fontFamilyApplied = false;
  private fontSizeValue = '';
  /** True once a size was pushed onto the surfaces (see applyFontSize). */
  private fontSizeApplied = false;
  /** Monaco's own font size, captured before we ever override it. */
  private monacoDefaultFontSizePx = 0;
  private verticalLineList: ResolvedEditorVerticalLine[] = [];
  /** True once rules were pushed onto the surfaces (see applyVerticalLines). */
  private verticalLinesApplied = false;
  /** The width-override sheet, built only for a rule thicker than Monaco's. */
  private verticalLinesStyleEl: HTMLStyleElement | null = null;
  /** Ties that sheet to this instance's surface, and to no other on the page. */
  private readonly verticalLinesScopeId = nextVerticalLinesScopeId();

  private monaco: any = null;
  private editorInstance: any = null;
  private model: any = null;
  private rootEl: HTMLElement | null = null;
  private surfaceEl: HTMLElement | null = null;
  private textareaEl: HTMLTextAreaElement | null = null;
  private simpleTextareaEl: HTMLTextAreaElement | null = null;
  private simpleModeEnabled = false;
  private chrome: EditorStandaloneChrome | null = null;
  private sharedSurfaceBridge: EditorSharedSurfaceBridge | null = null;
  private selectionStateEnabled = false;
  private selectionStateTeardown: (() => void) | null = null;
  private saveShortcutEnabled = true;
  private saveShortcutTeardown: (() => void) | null = null;
  private readonly disposables: DisposableLike[] = [];
  private lastEmittedValue = '';
  /** The text {@link isDirty} compares against — see {@link markSaved}. */
  private savedValueText = '';
  private dirtyFlag = false;

  constructor(options: EditorOptions = {}) {
    super(options);
    if (typeof options.value === 'string') {
      this.valueText = options.value;
    }
    // Whatever the editor opens with is, by definition, the saved document.
    this.savedValueText = this.valueText;
    this.language = options.language || LANGUAGE_ID;
    this.readOnly = Boolean(options.readOnly);
    this.chromeEnabled = options.chrome !== false;
    this.selectionStateEnabled = Boolean(options.selectionState);
    this.saveShortcutEnabled = options.saveShortcut !== false;
    this.loadMonacoResources =
      options.loadMonacoResources || defaultLoadMonacoResources;
    if (typeof options.fontFamily === 'string') {
      this.fontFamilyValue = options.fontFamily.trim();
    }
    if (options.fontSize !== undefined) {
      this.fontSizeValue = normalizeFontSize(options.fontSize);
    }
    this.verticalLineList = normalizeVerticalLines(options.verticalLines);
  }

  /* -------------------------------- value -------------------------------- */

  get value(): string {
    return this.getValue();
  }

  /**
   * Assigning replaces the document *and* the {@link isDirty} baseline: a
   * host writing here is loading a document, not editing one, exactly as the
   * app shell's `applyDocumentContent()` marks a restored document clean (it
   * keeps the flag only for the ones it fabricates — example, blank, import).
   * Use {@link revertToSaved} to go back to the baseline instead of replacing
   * it.
   */
  set value(next: string) {
    this.assertNotDestroyed();
    this.setValueInternal(String(next ?? ''));
    this.markSaved();
  }

  getValue(): string {
    if (this.sharedSurfaceBridge) {
      return String(this.sharedSurfaceBridge.getValue() ?? '');
    }
    if (this.simpleModeEnabled && this.simpleTextareaEl) {
      return this.simpleTextareaEl.value;
    }
    if (this.model) {
      return this.model.getValue();
    }
    if (this.textareaEl) {
      return this.textareaEl.value;
    }
    return this.valueText;
  }

  /** True when Monaco failed to load and the textarea fallback is active. */
  get isFallback(): boolean {
    return this.textareaEl != null;
  }

  /** Which surface edits currently go through. */
  get surfaceKind(): EditorSurfaceKind {
    if (this.simpleModeEnabled) {
      return this.simpleTextareaEl ? 'textarea' : 'none';
    }
    if (this.editorInstance && this.model) {
      return 'monaco';
    }
    return this.textareaEl ? 'textarea' : 'none';
  }

  /** True while the plain-textarea "Simple Editor" surface is showing. */
  get isSimpleMode(): boolean {
    return this.simpleModeEnabled;
  }

  /** The textarea edits currently go through (simple mode or fallback). */
  get activeTextarea(): HTMLTextAreaElement | null {
    if (this.simpleModeEnabled) {
      return this.simpleTextareaEl;
    }
    return this.textareaEl;
  }

  /** True when the standalone toolbar + tools menu are mounted. */
  get hasChrome(): boolean {
    return this.chrome != null;
  }

  /**
   * The live selection readout in the corner of the editor panel — "All: 128
   * words / 687 chars" for the whole document, "Selected: …" once there is a
   * selection. Off by default; assigning toggles it immediately, and the
   * setting survives unmount/mount (the readout is rebuilt with the panel).
   *
   * It follows whichever surface this instance drives: its own Monaco or
   * Simple Editor textarea when mounted, and the application's editor panel
   * when the instance is a shared-surface facade (the app pages), where the
   * host owns the surfaces and swaps between them.
   */
  get isSelectionStateEnabled(): boolean {
    return this.selectionStateEnabled;
  }

  set isSelectionStateEnabled(next: boolean) {
    this.assertNotDestroyed();
    const enabled = Boolean(next);
    if (enabled === this.selectionStateEnabled) {
      return;
    }
    this.selectionStateEnabled = enabled;
    this.syncSelectionState();
  }

  /**
   * Whether Ctrl/Cmd+S over the mounted surface emits `save` instead of
   * reaching the browser's "Save page" dialog. On by default; assigning
   * toggles it immediately, and the setting survives unmount/mount.
   *
   * Only ever wired on an owned mount. A shared-surface facade installs
   * nothing — the host application owns key handling on its own panel — but
   * {@link requestSave} still works there.
   */
  get isSaveShortcutEnabled(): boolean {
    return this.saveShortcutEnabled;
  }

  set isSaveShortcutEnabled(next: boolean) {
    this.assertNotDestroyed();
    const enabled = Boolean(next);
    if (enabled === this.saveShortcutEnabled) {
      return;
    }
    this.saveShortcutEnabled = enabled;
    this.syncSaveShortcut();
  }

  /**
   * Ask the host to persist the document — the programmatic form of the
   * Ctrl/Cmd+S shortcut, for a host that drives saving from its own chrome.
   * Emits `save` with the current value; the component persists nothing
   * itself, but it does {@link markSaved} — see there for why issuing the
   * command, not the host's acknowledgement, is what clears the flag.
   */
  requestSave(): void {
    this.assertNotDestroyed();
    this.emitSave('api');
  }

  /**
   * Whether the document differs from the last saved text — what the chrome's
   * Reset/Save pair is enabled by and what paints the panel's red top edge.
   *
   * Per instance: unlike the app shell's page-global `state.dirty`, two
   * standalone editors on one page track their own. It is a comparison, not a
   * latch, so editing and then undoing back to the saved text reads clean —
   * exactly the case where {@link revertToSaved} would do nothing.
   */
  get isDirty(): boolean {
    return this.dirtyFlag;
  }

  /**
   * Declare the current text saved: it becomes the {@link revertToSaved}
   * baseline and {@link isDirty} goes false.
   *
   * Called for you when a `save` is emitted (Ctrl/Cmd+S, {@link requestSave},
   * the chrome's Save) and when a host assigns {@link value}. As in the app
   * shell, the flag means "the user asked to save this document", not "the
   * host acknowledged" — a host that persists asynchronously and wants the
   * stricter reading can hold the mark until its write resolves by
   * re-assigning `value`.
   */
  markSaved(): void {
    this.assertNotDestroyed();
    this.savedValueText = this.getValue();
    this.setDirtyState(false);
  }

  /**
   * Reset — put the document back to the last saved text, dropping the edits
   * since. The counterpart of the save command, and a no-op when
   * {@link isDirty} is false.
   *
   * @returns whether anything was reverted.
   */
  revertToSaved(): boolean {
    this.assertNotDestroyed();
    if (!this.dirtyFlag) {
      return false;
    }
    this.setValueInternal(this.savedValueText);
    // The mounted paths recompute this through `emitValueChange`; an unmounted
    // component has no surface to emit from, so settle it here either way.
    this.setDirtyState(this.getValue() !== this.savedValueText);
    return true;
  }

  /** The attached plugin instances, in attach order. */
  get plugins() {
    return this.pluginHost.plugins;
  }

  /**
   * Host override for the face the surfaces render with. Empty (the default)
   * means "the stylesheet's own font" — see {@link resolvedFontFamily}.
   * Assigning re-applies immediately.
   */
  get fontFamily(): string {
    return this.fontFamilyValue;
  }

  set fontFamily(next: string) {
    const value = String(next ?? '').trim();
    if (value === this.fontFamilyValue) {
      return;
    }
    this.fontFamilyValue = value;
    this.applyFontFamily();
    // A new face is a new character width, and the textarea rules are drawn at
    // multiples of it.
    this.applyVerticalLines();
  }

  /**
   * Font size the editor surfaces render text at — Monaco and the textareas
   * together, so both surfaces of one panel stay legible at the same scale.
   *
   * Any CSS length works (`18px`, `1.2rem`, `120%`); a bare number is read as
   * pixels, the same convention the previews use, so `editor.fontSize = 18`
   * and `editor.fontSize = '18px'` mean the same thing and the getter always
   * reports the normalized string. Assigning re-applies immediately.
   *
   * Empty (the default) is "no override": Monaco keeps its own size and the
   * textareas keep the panel stylesheet's, and clearing back to `''` after a
   * size was set really does restore them rather than freezing the last value.
   */
  get fontSize(): string {
    return this.fontSizeValue;
  }

  set fontSize(next: string | number) {
    const value = normalizeFontSize(next);
    if (value === this.fontSizeValue) {
      return;
    }
    this.fontSizeValue = value;
    this.applyFontSize();
    // Same reason as the family: the rules are drawn at multiples of the
    // character width, which has just changed.
    this.applyVerticalLines();
  }

  /**
   * The size the surfaces actually render at, in pixels — the {@link fontSize}
   * override resolved against the live page, or, with no override, whatever
   * Monaco and the panel stylesheet chose. 0 before there is any surface to
   * measure.
   *
   * This is what a host's size control seeds itself from, so it starts on the
   * real value instead of an assumed one.
   */
  get resolvedFontSizePx(): number {
    if (this.fontSizeValue) {
      const resolved = resolveFontSizePx(this.fontSizeValue, this.surfaceEl);
      if (resolved) {
        return resolved;
      }
      // Not mounted yet: a plain `18px` still answers, other units cannot.
      // Match the px suffix explicitly — `parseFloat` would otherwise report
      // `1.2rem` as 1.2px and `120%` as 120px.
      const parsed = /^\s*(\d+(?:\.\d+)?)px\s*$/.exec(this.fontSizeValue);
      const px = parsed ? Number.parseFloat(parsed[1]) : 0;
      return px > 0 ? px : 0;
    }

    if (this.editorInstance) {
      return (
        readMonacoFontSizePx(this.monaco, this.editorInstance) ||
        this.monacoDefaultFontSizePx
      );
    }

    return measureFontSizePx(this.activeTextarea ?? this.surfaceEl);
  }

  /**
   * The stack the surfaces actually render with: the {@link fontFamily}
   * override the host set, ahead of {@link EDITOR_FONT_BASE_STACK} so text the
   * override's face lacks still lands on the panel's usual monospace look.
   *
   * **Plugin-contributed faces are deliberately NOT part of this.** A language
   * plugin's `language.fontFaces` styles the *previews* (and the app pages'
   * font pickers) only — the editing surfaces keep their own font whatever is
   * composed, so attaching a language plugin never restyles the code the user
   * is typing. A host that does want that plugin's face in the editor asks for
   * it explicitly by assigning {@link fontFamily}.
   *
   * Empty without an override: nothing is pushed onto the surfaces then,
   * leaving the panel stylesheet and Monaco's own defaults in charge.
   */
  get resolvedFontFamily(): string {
    const override = this.fontFamilyValue.trim();
    if (!override) {
      return '';
    }
    return `${toCssFontFamily(override)}, ${EDITOR_FONT_BASE_STACK}`;
  }

  /**
   * The vertical rules currently drawn, normalized and ordered by column —
   * what {@link setVerticalLines} last accepted. A copy, so a host cannot edit
   * the live list behind the component's back.
   */
  get verticalLines(): ResolvedEditorVerticalLine[] {
    return this.verticalLineList.map((line) => ({ ...line }));
  }

  /**
   * Draw vertical rules down the editing surface, one per entry, at a column
   * counted in characters:
   *
   * ```ts
   * editor.setVerticalLines([{ characters: 80, width: 1, color: '#000000FF' }]);
   * ```
   *
   * `width` (pixels, default 1) and `color` (any CSS color; default is the
   * surface's own faint ruler color) are optional, and a bare number is
   * shorthand for a rule at that column. Replaces the whole set, so an empty
   * array — or no argument — clears them. Applies immediately, and the setting
   * survives unmount/mount as the typography settings do.
   *
   * Both surfaces draw them, so flipping to the Simple Editor keeps the guides:
   * Monaco through its own `rulers`, the textareas through a background layer
   * per rule. A column is the width of one `x` in the surface's font, which is
   * how Monaco itself counts — exact on a monospace face, an approximation on
   * any other, and the same approximation on both surfaces.
   *
   * In shared-surface (facade) mode the rules are pushed onto the host
   * application's Monaco, which is the surface this instance is speaking for —
   * so call this once that surface exists (after the dashboard's `mount()`
   * resolves, say). A facade is never `mounted` in the component's own sense,
   * which is why there is no later hook that would re-assert them for you.
   */
  setVerticalLines(lines?: ReadonlyArray<EditorVerticalLine | number>): void {
    this.assertNotDestroyed();
    this.verticalLineList = normalizeVerticalLines(lines ?? []);
    this.applyVerticalLines();
  }

  /** True while this instance is a facade over a host-owned surface. */
  get isSharedSurface(): boolean {
    return this.sharedSurfaceBridge != null;
  }

  /**
   * The booted Monaco namespace (null before mount or in fallback mode).
   * For editor-surface plugins that wire Monaco-level features (on-screen
   * keyboards, actions); prefer the component API where it suffices.
   */
  get monacoNamespace(): any {
    if (this.sharedSurfaceBridge) {
      return this.sharedSurfaceBridge.getMonaco?.() ?? null;
    }
    return this.monaco;
  }

  /** The live Monaco editor instance (null before mount / fallback mode). */
  get monacoEditor(): any {
    if (this.sharedSurfaceBridge) {
      return this.sharedSurfaceBridge.getMonacoEditor?.() ?? null;
    }
    return this.editorInstance;
  }

  /**
   * The Monaco runtime loader this instance was configured with (the shared
   * lazy chunk unless `loadMonacoResources` was passed).
   *
   * `Editor` owns Monaco loading for every surface it drives: an owned mount
   * boots through it in `handleMount()`, and in wrap phase
   * `OpenLyricDashboard` reads it here so the application it wraps loads the
   * runtime through this same loader. Overriding Monaco for a page therefore
   * means `new Editor({ loadMonacoResources })` — there is no second knob.
   */
  get monacoLoader(): LoadMonacoResources {
    return this.loadMonacoResources;
  }

  protected override getOwnedRoot(): HTMLElement | null {
    return this.rootEl;
  }

  /* ------------------------------ bridge API ----------------------------- */

  /** Move the caret to a source position, reveal it, and focus the surface. */
  focusRange(line: number, column: number): void {
    const targetLine = Math.max(1, Math.floor(Number(line) || 1));
    const targetColumn = Math.max(1, Math.floor(Number(column) || 1));

    if (this.sharedSurfaceBridge) {
      this.sharedSurfaceBridge.focusRange(targetLine, targetColumn);
      return;
    }

    if (this.surfaceKind === 'monaco') {
      const clampedLine = Math.min(targetLine, this.model.getLineCount());
      const clampedColumn = Math.min(
        targetColumn,
        this.model.getLineMaxColumn(clampedLine),
      );
      const position = { lineNumber: clampedLine, column: clampedColumn };
      this.editorInstance.focus();
      this.editorInstance.setPosition(position);
      this.editorInstance.setSelection({
        startLineNumber: clampedLine,
        startColumn: clampedColumn,
        endLineNumber: clampedLine,
        endColumn: clampedColumn,
      });
      this.editorInstance.revealPositionInCenter(position);
      return;
    }

    const textarea = this.activeTextarea;
    if (textarea) {
      const offset = this.lineColumnToOffset(
        textarea.value,
        targetLine,
        targetColumn,
      );
      textarea.focus();
      textarea.setSelectionRange(offset, offset);
    }
  }

  focus(): void {
    if (this.sharedSurfaceBridge) {
      this.sharedSurfaceBridge.focus?.();
      return;
    }
    if (this.simpleModeEnabled) {
      this.simpleTextareaEl?.focus();
      return;
    }
    this.editorInstance?.focus();
    this.textareaEl?.focus();
  }

  /* --------------------------- fence navigation -------------------------- */

  /**
   * Every Open Lyric fence the current document declares, in source order,
   * keyed the way the previews key them: `id` is the markdown preview's fence
   * element id and `songViewId` the lyric preview's, so the same value
   * addresses a fence in either direction — hand it to `focusFence` here, or
   * to `document.getElementById` / `PreviewController.jumpToPreviewFence` over
   * there.
   *
   * Read from the live document text on each call, so it is always current;
   * unrecognized ```` ```ol:… ```` headers are skipped, exactly as the
   * previews skip them.
   */
  getFences(): OpenLyricFenceLocation[] {
    return listOpenLyricFences(this.getValue());
  }

  /**
   * Move the caret to a fence named by id, and return whether one matched.
   *
   * Tolerant about what "id" means: either preview's element id
   * (`ol-preview-target-chorus-1`, `ol-song-view-target-chorus-1`) or the part
   * name itself (`Chorus 1`) all resolve to the same fence, so a host can pass
   * back whatever it happens to be holding — the id it read off a clicked
   * preview element, or a name from {@link getFences}.
   */
  focusFence(fenceId: string, options: EditorFenceFocusOptions = {}): boolean {
    const wantedId = toOpenLyricFenceTargetId(fenceId);
    if (!wantedId) {
      return false;
    }

    return this.focusMatchingFence((fence) => fence.id === wantedId, options);
  }

  /**
   * Move the caret to the fence declaring `partName` (`'Chorus 1'`, `'Verse
   * 2'`, `'Config'`), and return whether one matched. Matching ignores case
   * and surrounding/repeated whitespace.
   */
  focusPart(partName: string, options: EditorFenceFocusOptions = {}): boolean {
    const wantedPart = normalizePartNameKey(partName);
    if (!wantedPart) {
      return false;
    }

    return this.focusMatchingFence(
      (fence) => normalizePartNameKey(fence.partName) === wantedPart,
      options,
    );
  }

  /**
   * The shared half of `focusFence`/`focusPart`: pick the requested occurrence
   * and hand the source position to {@link focusRange}, which is what makes
   * both work on every surface — Monaco, the simple textarea, and the shared
   * surface of a dashboard facade.
   */
  private focusMatchingFence(
    matches: (fence: OpenLyricFenceLocation) => boolean,
    options: EditorFenceFocusOptions,
  ): boolean {
    const occurrence = Math.max(1, Math.floor(Number(options.occurrence) || 1));
    const fence = this.getFences().filter(matches)[occurrence - 1];

    if (!fence) {
      return false;
    }

    // A fence with no body has its closing ``` on the very next line, and
    // landing the caret there reads as "outside the block" — such a fence
    // falls back to the header position below.
    const bodyLine = fence.startLine + 1;
    if (options.target === 'body' && bodyLine < fence.endLine) {
      this.focusRange(bodyLine, 1);
      return true;
    }

    this.focusRange(fence.startLine, OL_FENCE_HEADER_CONTENT_COLUMN);
    return true;
  }

  /* ---------------------------- editor commands -------------------------- */

  /**
   * Swap between the Monaco surface and the plain "Simple Editor" textarea,
   * carrying the document across. Monaco stays alive (and keeps its undo
   * stack) behind the hidden surface, exactly as the app shell does.
   */
  setSimpleMode(enabled: boolean): void {
    this.assertNotDestroyed();
    const next = Boolean(enabled);
    if (next === this.simpleModeEnabled) {
      return;
    }
    if (!this.rootEl) {
      // Not mounted yet: remember the choice for the next mount().
      this.simpleModeEnabled = next;
      return;
    }

    const currentValue = this.getValue();
    this.simpleModeEnabled = next;

    if (next) {
      const textarea = this.ensureSimpleTextarea();
      textarea.value = currentValue;
      textarea.hidden = false;
      if (this.surfaceEl) {
        this.surfaceEl.hidden = true;
      }
    } else {
      if (this.simpleTextareaEl) {
        this.simpleTextareaEl.hidden = true;
      }
      if (this.surfaceEl) {
        this.surfaceEl.hidden = false;
      }
      // Push whatever the textarea holds back into the real surface.
      if (this.model) {
        if (this.model.getValue() !== currentValue) {
          this.model.setValue(currentValue);
        }
      } else if (this.textareaEl && this.textareaEl.value !== currentValue) {
        this.textareaEl.value = currentValue;
      }
      this.editorInstance?.layout?.();
    }

    this.lastEmittedValue = this.getValue();
    this.chrome?.syncSurfaceState();
  }

  /** Undo one step on whichever surface is active. */
  undo(): boolean {
    return this.runHistoryCommand('undo');
  }

  /** Redo one step on whichever surface is active. */
  redo(): boolean {
    return this.runHistoryCommand('redo');
  }

  /** Empty the document through the active surface (one undoable edit). */
  clearText(): boolean {
    this.assertNotDestroyed();
    if (this.surfaceKind === 'monaco') {
      const editor = this.editorInstance;
      const model = this.model;
      editor.focus?.();
      if (!model.getValue()) {
        editor.setPosition?.({ lineNumber: 1, column: 1 });
        return true;
      }
      editor.pushUndoStop?.();
      const applied = editor.executeEdits?.('open-lyric-clear-text', [
        { range: model.getFullModelRange(), text: '' },
      ]);
      if (!applied) {
        return false;
      }
      editor.setPosition?.({ lineNumber: 1, column: 1 });
      editor.pushUndoStop?.();
      return true;
    }

    const textarea = this.activeTextarea;
    if (!textarea) {
      return false;
    }
    textarea.focus();
    this.value = '';
    return true;
  }

  /** Copy the whole document to the clipboard. */
  async copyAllText(): Promise<boolean> {
    const text = this.getValue();
    if (!text) {
      return false;
    }
    const copied = await this.writeClipboardText(text);
    if (copied) {
      this.focus();
    }
    return copied;
  }

  /**
   * Clipboard write with the legacy `execCommand` fallback, so the chrome's
   * copy/cut actions work on browsers without the async clipboard API.
   */
  async writeClipboardText(text: string): Promise<boolean> {
    if (!text) {
      return false;
    }
    const clipboard = globalThis.navigator?.clipboard;
    if (typeof clipboard?.writeText === 'function') {
      try {
        await clipboard.writeText(text);
        return true;
      } catch (error) {
        console.warn('Open Lyric editor: clipboard write failed.', error);
      }
    }
    if (typeof document.execCommand !== 'function') {
      return false;
    }
    const scratch = document.createElement('textarea');
    scratch.value = text;
    scratch.setAttribute('readonly', '');
    scratch.style.position = 'fixed';
    scratch.style.left = '-100000px';
    scratch.style.opacity = '0';
    document.body.append(scratch);
    scratch.focus();
    scratch.select();
    try {
      return document.execCommand('copy');
    } catch (error) {
      console.warn('Open Lyric editor: legacy clipboard copy failed.', error);
      return false;
    } finally {
      scratch.remove();
    }
  }

  private runHistoryCommand(command: 'undo' | 'redo'): boolean {
    if (this.surfaceKind === 'monaco') {
      this.editorInstance.focus?.();
      this.editorInstance.trigger?.('open-lyric-toolbar', command, null);
      return true;
    }
    const textarea = this.activeTextarea;
    if (!textarea || typeof document.execCommand !== 'function') {
      return false;
    }
    textarea.focus();
    try {
      const applied = document.execCommand(command);
      if (applied) {
        this.emitValueChange();
      }
      return applied;
    } catch (error) {
      console.warn(`Open Lyric editor: ${command} failed.`, error);
      return false;
    }
  }

  private ensureSimpleTextarea(): HTMLTextAreaElement {
    if (this.simpleTextareaEl) {
      return this.simpleTextareaEl;
    }
    const textarea = document.createElement('textarea');
    textarea.className = 'ol-editor-simple-input editor-panel__simple-input';
    textarea.setAttribute('aria-label', 'Simple markdown editor');
    textarea.spellcheck = false;
    textarea.wrap = 'soft';
    textarea.readOnly = this.readOnly;
    textarea.value = this.valueText;
    this.rootEl?.append(textarea);
    this.simpleTextareaEl = textarea;

    this.wireTextareaEvents(textarea);
    // Built lazily, long after mount() applied the typography and the rules to
    // the surfaces that existed then — so this one takes them on creation.
    this.applyFontFamily();
    this.applyFontSize();
    this.applyVerticalLines();
    return textarea;
  }

  /* --------------------------- shared surface ---------------------------- */

  /**
   * Wrap phase: become a live facade over an editor surface the host owns
   * (see {@link EditorSharedSurfaceBridge}). Mutually exclusive with
   * `mount()` — a facade never builds a surface of its own, and its plugins
   * stay dormant (no `onMount`/`onValueChange`; attached plugins act as the
   * host's composition manifest and are still contract-validated).
   *
   * The host must call {@link notifySharedSurfaceValueChange} when the
   * shared document changes so `change` events fire here too.
   */
  attachSharedSurface(bridge: EditorSharedSurfaceBridge): void {
    this.assertNotDestroyed();
    if (this.isMounted) {
      throw new Error(
        'attachSharedSurface() cannot be used on a mounted Editor; it is a ' +
          'facade mode over a host-owned surface.',
      );
    }
    this.sharedSurfaceBridge = bridge;
    this.lastEmittedValue = this.getValue();
    // The host's panel exists by now, so an already-enabled readout can build
    // itself into it (see syncSelectionState).
    this.syncSelectionState();
    // Rules configured before the bridge existed now have a surface to reach.
    // The host boots Monaco lazily, so this can land before there is one to
    // ask; `reload()` is how a host re-asserts them once it is up.
    this.applyVerticalLines();
  }

  /** Drop the facade bridge; the instance becomes an ordinary component. */
  detachSharedSurface(): void {
    // While the bridge is still here to reach: the rules were drawn on a
    // surface this instance does not own, and it hands it back as it found it.
    this.teardownVerticalLines();
    this.sharedSurfaceBridge = null;
    this.syncSelectionState();
  }

  /** Host notification that the shared surface's document changed. */
  notifySharedSurfaceValueChange(): void {
    if (this.sharedSurfaceBridge) {
      this.emitValueChange();
    }
  }

  /* ------------------------------ lifecycle ------------------------------ */

  protected override async handleMount(container: HTMLElement): Promise<void> {
    if (this.sharedSurfaceBridge) {
      throw new Error(
        'This Editor is attached to a shared surface (wrap phase); call ' +
          'detachSharedSurface() before mounting an owned surface.',
      );
    }
    // The faces this surface renders Latin text with, for an embed that only
    // ever calls mount() (a page entry gets them from installShellMarkup()).
    // Declared here, synchronously, so the browser can start fetching before
    // the awaits below; the surface waits for the result further down.
    ensureFontFacesInjected();

    // The owned root holds the surfaces (Monaco host + the simple-editor
    // textarea) and is what the chrome, when built, moves into its panel body.
    const rootEl = document.createElement('div');
    rootEl.className = 'ol-editor-root';
    rootEl.style.width = '100%';
    rootEl.style.height = '100%';
    const surfaceEl = document.createElement('div');
    surfaceEl.className = 'ol-editor-surface editor-panel__surface';
    surfaceEl.style.width = '100%';
    surfaceEl.style.height = '100%';
    rootEl.append(surfaceEl);
    container.append(rootEl);
    this.rootEl = rootEl;
    this.surfaceEl = surfaceEl;

    try {
      // Both in flight at once. The font wait is what lets `bootMonaco` hand
      // Monaco a family it can actually measure — Monaco sizes its glyph cell
      // once, at creation, so a face that lands afterwards leaves every column
      // laid out against the fallback. Running it serially would add its
      // latency to every mount; running it concurrently with the Monaco chunk
      // usually costs nothing, since the fonts are the smaller download.
      // Only the Monaco half can reject (`ensureFontFacesLoaded` resolves even
      // on a failed or timed-out font), so the fallback below is unchanged.
      const [, monaco] = await Promise.all([
        ensureFontFacesLoaded(),
        loadOpenLyricMonaco(this.loadMonacoResources),
      ]);
      // A destroy() can land while Monaco loads; don't build a surface for a
      // dead component (the base also undoes any partial mount).
      if (this.isDestroyed) {
        return;
      }
      this.bootMonaco(monaco, surfaceEl);
    } catch (error) {
      console.warn(
        'Open Lyric editor: Monaco unavailable, using textarea fallback.',
        error,
      );
      if (this.isDestroyed) {
        return;
      }
      this.bootTextarea(surfaceEl);
    }

    // `setSimpleMode(true)` before mount(): build that surface up front.
    if (this.simpleModeEnabled) {
      const textarea = this.ensureSimpleTextarea();
      textarea.value = this.valueText;
      surfaceEl.hidden = true;
    }

    // Plugins are attached before mount(), so their contributed faces are
    // known here but had no surface to land on until now.
    this.applyFontFamily();
    this.applyFontSize();

    this.installChrome(container);
    // After the chrome: the readout renders into the panel body it builds, and
    // the rules are measured in the font that panel's stylesheet gives the
    // surfaces it has just moved into it.
    this.applyVerticalLines();
    this.syncSelectionState();
    this.syncSaveShortcut();
  }

  /**
   * Build or tear down the selection readout so it matches
   * {@link isSelectionStateEnabled} and the current lifecycle state.
   *
   * Called from every transition that changes what there is to read from:
   * mount (the panel now exists), unmount/destroy (it no longer does), and
   * attach/detach of a shared surface (the app's panel takes over). A readout
   * failure must never take the editor down with it.
   */
  private syncSelectionState(): void {
    // Keyed on "is there a surface to read?", not on the lifecycle flag:
    // `handleMount()` runs before the component is marked mounted, and the
    // owned root is exactly what it builds there and drops on unmount.
    const shouldShow =
      this.selectionStateEnabled &&
      !this.isDestroyed &&
      (this.rootEl != null || this.sharedSurfaceBridge != null);

    if (!shouldShow) {
      try {
        this.selectionStateTeardown?.();
      } catch (error) {
        console.error(
          'Open Lyric editor: selection readout teardown failed.',
          error,
        );
      }
      this.selectionStateTeardown = null;
      return;
    }

    if (this.selectionStateTeardown) {
      return;
    }

    try {
      // Facade mode: the host application owns the surfaces (and swaps Monaco
      // ⇄ Simple Editor underneath), so the readout reads the app's editor
      // panel rather than this instance, which drives none of its own.
      this.selectionStateTeardown = installEditorSelectionStats(
        this.sharedSurfaceBridge ? {} : { editor: this },
      );
    } catch (error) {
      console.error('Open Lyric editor: selection readout failed.', error);
      this.selectionStateTeardown = null;
    }
  }

  /**
   * Wire or drop the Ctrl/Cmd+S handler so it matches
   * {@link isSaveShortcutEnabled} and the current lifecycle state. Mirrors
   * {@link syncSelectionState}: called from mount, unmount and destroy.
   *
   * One DOM listener rather than a Monaco action, deliberately — it is the
   * only form that covers all three surfaces this component can be editing
   * through (Monaco, the fallback textarea, the Simple Editor textarea), and
   * a Monaco action alongside it would fire the event twice.
   */
  private syncSaveShortcut(): void {
    const container = this.container;
    // Same "is there an owned surface?" keying as the readout above, minus the
    // facade case: a bridged instance drives no keystrokes of its own.
    const shouldInstall =
      this.saveShortcutEnabled &&
      !this.isDestroyed &&
      !this.sharedSurfaceBridge &&
      this.rootEl != null &&
      container != null;

    if (!shouldInstall) {
      this.saveShortcutTeardown?.();
      this.saveShortcutTeardown = null;
      return;
    }

    if (this.saveShortcutTeardown) {
      return;
    }

    const onKeydown = (event: KeyboardEvent) => {
      // Cmd on macOS/iPadOS, Ctrl elsewhere. Alt/Shift variants are the
      // browser's own (Ctrl+Shift+S is "Save as" in several) — leave them.
      if (!(event.metaKey || event.ctrlKey) || event.altKey || event.shiftKey) {
        return;
      }
      // `code` as well as `key`: with a non-Latin layout active (the km-KH
      // NiDA keyboard, say) `key` is the mapped character, while the physical
      // S position is what the user pressed.
      if (
        String(event.key ?? '').toLowerCase() !== 's' &&
        event.code !== 'KeyS'
      ) {
        return;
      }
      // Before the repeat check, not after — a held Ctrl+S must not start
      // leaking "Save page" dialogs once the first keystroke is swallowed.
      event.preventDefault();
      if (event.repeat) {
        return;
      }
      this.emitSave('shortcut');
    };

    // Capture, on the container rather than the surfaces: it runs before
    // Monaco's own keydown handling (which stops propagation of what it
    // handles), and it still covers the chrome's toolbar and menus, which sit
    // beside the surface root inside this same container.
    container.addEventListener('keydown', onKeydown, true);
    this.saveShortcutTeardown = () => {
      container.removeEventListener('keydown', onKeydown, true);
    };
  }

  private emitSave(source: OpenLyricSavePayload['source']): void {
    this.emitter.emit('save', { value: this.getValue(), source });
    // After the listeners, so a host reading `isDirty` inside its own handler
    // still sees the state the user issued the command in.
    this.markSaved();
  }

  /**
   * Mirror the dirty flag onto the chrome (the Reset/Save pair's enabled
   * state and the panel's red top edge). No-op when unchanged, so the chrome
   * is not re-rendered on every keystroke of an already-dirty document.
   */
  private setDirtyState(next: boolean): void {
    if (next === this.dirtyFlag) {
      return;
    }
    this.dirtyFlag = next;
    try {
      this.chrome?.syncDirtyState();
    } catch (error) {
      console.error('Open Lyric editor: dirty-state sync failed.', error);
    }
  }

  /**
   * Build the standalone toolbar + tools menu around the mounted surface. A
   * chrome failure must never take the editor down with it — the surface stays
   * usable without its panel.
   */
  private installChrome(container: HTMLElement): void {
    if (!this.chromeEnabled || !this.rootEl || this.chrome) {
      return;
    }
    try {
      const chrome = new EditorStandaloneChrome(this);
      chrome.attach(this.rootEl, container);
      this.chrome = chrome;
    } catch (error) {
      console.error('Open Lyric editor: chrome failed to mount.', error);
      this.chrome = null;
    }
  }

  protected override handleUnmount(): void {
    // Preserve content so a later mount() restores it.
    this.valueText = this.getValue();

    // Before the surfaces go: the rules keep a sheet outside this component,
    // and a marker on the element that is about to be dropped. The list itself
    // survives, so a later mount() draws them again.
    this.teardownVerticalLines();

    // Tear the chrome down first: it hands the owned root back to the
    // container, so the teardown below removes exactly what it created.
    try {
      this.chrome?.destroy();
    } catch (error) {
      console.error('Open Lyric editor chrome teardown failed.', error);
    }
    this.chrome = null;

    while (this.disposables.length) {
      const disposable = this.disposables.pop();
      try {
        disposable?.dispose?.();
      } catch (error) {
        console.error('Open Lyric editor disposable failed.', error);
      }
    }
    if (this.editorInstance) {
      try {
        this.editorInstance.dispose();
      } catch (error) {
        console.error('Open Lyric editor dispose failed.', error);
      }
      this.editorInstance = null;
    }
    if (this.model) {
      try {
        this.model.dispose();
      } catch (error) {
        console.error('Open Lyric editor model dispose failed.', error);
      }
      this.model = null;
    }
    this.textareaEl = null;
    this.simpleTextareaEl = null;
    this.surfaceEl = null;
    // The surfaces that carried the typography are gone; a later mount()
    // applies it afresh rather than trying to clear what no longer exists.
    this.fontFamilyApplied = false;
    this.fontSizeApplied = false;
    this.monacoDefaultFontSizePx = 0;
    if (this.rootEl) {
      this.rootEl.remove();
      this.rootEl = null;
    }
    this.monaco = null;
    // The chrome took its panel (and the readout inside it) down with it; drop
    // the listeners and intervals that were watching the gone surface. The
    // settings themselves survive, so a later mount() rebuilds both.
    this.syncSelectionState();
    this.syncSaveShortcut();
  }

  protected override handleDestroy(): void {
    // Before the bridge goes, so a facade's rules are lifted off the host's
    // surface rather than left painted on it (an owned mount already tore
    // them down through handleUnmount).
    this.teardownVerticalLines();
    this.sharedSurfaceBridge = null;
    this.syncSelectionState();
    this.syncSaveShortcut();
  }

  protected override handleReload(): void {
    this.editorInstance?.layout?.();
    // Re-measured with the surface: the textarea rules are drawn at multiples
    // of a character width, which a re-laid-out panel can have changed.
    this.applyVerticalLines();
  }

  protected override handleThemeChange(theme: OpenLyricTheme): void {
    // Monaco themes are global; setTheme applies to all editors on the page.
    // In facade mode `this.monaco` is null — the host owns theming there.
    this.monaco?.editor.setTheme(getEditorThemeName(theme));
  }

  /* ------------------------------ internals ------------------------------ */

  private bootMonaco(monaco: any, surfaceEl: HTMLElement): void {
    this.monaco = monaco;

    // Own the model explicitly. Passing `value`/`language` instead would make
    // Monaco create AND own a model, so `editor.dispose()` would dispose it
    // and our own `model.dispose()` would double-dispose. An explicitly
    // created model also gets its own generated URI, keeping instances
    // isolated from each other.
    const model = monaco.editor.createModel(this.valueText, this.language);
    const editorOptions: any = {
      model,
      // NOTE: Monaco applies themes globally — see README "Known limitations".
      theme: getEditorThemeName(this.theme),
      // Set at creation, never through a later `updateOptions`: Monaco measures
      // the glyph cell while building the view, so a font handed over
      // afterwards would need an explicit remeasure to take proper effect.
      // `handleMount` has already awaited the family for exactly this reason.
      fontFamily: this.resolvedFontFamily || EDITOR_FONT_BASE_STACK,
      readOnly: this.readOnly,
      automaticLayout: true,
      minimap: { enabled: false },
      renderWhitespace: 'all',
      wordWrap: 'on',
      wordSeparators: MONACO_WORD_SEPARATORS,
      scrollBeyondLastLine: false,
      fixedOverflowWidgets: true,
      unicodeHighlight: { invisibleCharacters: false },
    };

    const editorInstance = monaco.editor.create(surfaceEl, editorOptions);
    this.editorInstance = editorInstance;
    this.model = model;
    this.lastEmittedValue = this.getValue();
    // Read before the first `fontSize` override, so clearing the setting can
    // put Monaco back exactly where it started (it has no "unset").
    this.monacoDefaultFontSizePx =
      readMonacoFontSizePx(monaco, editorInstance) ||
      MONACO_DEFAULT_FONT_SIZE_PX;

    this.disposables.push(
      editorInstance.onDidChangeModelContent(() => this.emitValueChange()),
      editorInstance.onDidFocusEditorText(() => this.emitter.emit('focus', {})),
      editorInstance.onDidBlurEditorText(() => this.emitter.emit('blur', {})),
    );
  }

  private bootTextarea(surfaceEl: HTMLElement): void {
    const textarea = document.createElement('textarea');
    textarea.className = 'ol-editor-textarea';
    textarea.value = this.valueText;
    textarea.readOnly = this.readOnly;
    textarea.spellcheck = false;
    textarea.style.width = '100%';
    textarea.style.height = '100%';
    // Inherit the surface's `--ol-*`-driven colors and fonts.
    textarea.style.background = 'transparent';
    textarea.style.color = 'inherit';
    textarea.style.font = 'inherit';
    textarea.style.border = 'none';
    surfaceEl.append(textarea);
    this.textareaEl = textarea;
    this.lastEmittedValue = this.getValue();

    this.wireTextareaEvents(textarea);
  }

  /**
   * Wire the value/focus/blur events a textarea surface emits, and register the
   * matching disposers. Shared by both textarea surfaces — the fallback one
   * {@link bootTextarea} builds when Monaco is unavailable, and the simple-mode
   * one {@link ensureSimpleTextarea} builds lazily.
   */
  private wireTextareaEvents(textarea: HTMLTextAreaElement): void {
    const onInput = () => this.emitValueChange();
    const onFocus = () => this.emitter.emit('focus', {});
    const onBlur = () => this.emitter.emit('blur', {});
    textarea.addEventListener('input', onInput);
    textarea.addEventListener('focus', onFocus);
    textarea.addEventListener('blur', onBlur);
    this.disposables.push(
      { dispose: () => textarea.removeEventListener('input', onInput) },
      { dispose: () => textarea.removeEventListener('focus', onFocus) },
      { dispose: () => textarea.removeEventListener('blur', onBlur) },
    );
  }

  /**
   * Push {@link resolvedFontFamily} onto whichever surfaces exist — Monaco
   * through `updateOptions`, the fallback and Simple Editor textareas inline,
   * so both surfaces of one panel agree. Called on mount, when the host
   * assigns {@link fontFamily}, and when a surface is built late.
   *
   * With nothing to apply it does nothing unless it had pushed a stack before,
   * in which case it clears back to the stylesheet's own font — that is what
   * `fontFamilyApplied` tracks, so clearing the override really does undo it
   * instead of leaving the last stack stuck on the surfaces.
   */
  private applyFontFamily(): void {
    const stack = this.resolvedFontFamily;
    if (!stack && !this.fontFamilyApplied) {
      return;
    }

    // Monaco has no "unset" for a font option, so clearing means handing it
    // back the base stack it would have used anyway.
    this.editorInstance?.updateOptions?.({
      fontFamily: stack || EDITOR_FONT_BASE_STACK,
    });
    // Clearing an inline style is a real unset, letting the panel CSS win.
    for (const textarea of [this.textareaEl, this.simpleTextareaEl]) {
      if (textarea) {
        textarea.style.fontFamily = stack;
      }
    }

    this.fontFamilyApplied = Boolean(stack);
  }

  /**
   * Push {@link fontSize} onto whichever surfaces exist. The CSS length goes
   * inline onto the Monaco host and the textareas; Monaco itself takes a
   * unitless pixel number, which is read back off the host it was just written
   * to — so `rem`/`%`/`em` resolve against the real page instead of an assumed
   * root size, and Monaco's glyph cell matches what the textareas render.
   *
   * Mirrors {@link applyFontFamily}: with nothing to apply it does nothing
   * unless it had pushed a size before, in which case it clears back to the
   * stylesheet's own size and hands Monaco back the size it booted with.
   */
  private applyFontSize(): void {
    const size = this.fontSizeValue;
    if (!size && !this.fontSizeApplied) {
      return;
    }

    // Clearing an inline style is a real unset, letting the panel CSS win.
    for (const element of [
      this.surfaceEl,
      this.textareaEl,
      this.simpleTextareaEl,
    ]) {
      if (element) {
        element.style.fontSize = size;
      }
    }

    // Monaco has no "unset" for a font option, so clearing means handing it
    // back the size it chose for itself before the first override.
    const px =
      resolveFontSizePx(size, this.surfaceEl) || this.monacoDefaultFontSizePx;
    if (px > 0) {
      this.editorInstance?.updateOptions?.({ fontSize: px });
    }

    this.fontSizeApplied = Boolean(size);
  }

  /**
   * Draw {@link verticalLines} on whichever surfaces exist — Monaco through its
   * `rulers` option, the textareas as background layers, so both surfaces of
   * one panel guide the eye to the same columns.
   *
   * Mirrors {@link applyFontFamily}: with nothing to draw it does nothing
   * unless rules were drawn before, in which case it clears them — that is what
   * `verticalLinesApplied` tracks, so an empty `setVerticalLines([])` really
   * does erase the guides instead of leaving the last set painted on.
   *
   * The textarea half measures, so it must run after the surfaces are in the
   * DOM they will render in (the chrome moves them into its panel, whose
   * stylesheet sets the font they are measured in).
   */
  private applyVerticalLines(): void {
    const lines = this.verticalLineList;
    if (!lines.length && !this.verticalLinesApplied) {
      return;
    }

    // An empty array is Monaco's own "no rulers", so clearing needs no
    // special case here.
    this.monacoEditor?.updateOptions?.({ rulers: toMonacoRulers(lines) });
    this.syncVerticalLineWidthStyle(lines);

    for (const textarea of [this.textareaEl, this.simpleTextareaEl]) {
      if (!textarea) {
        continue;
      }
      const background = buildVerticalLineBackground(
        lines,
        measureCharacterWidthPx(textarea),
        measureTextStartOffsetPx(textarea),
      );
      // Longhands, never the `background` shorthand: the fallback surface sets
      // `background: transparent` to inherit the panel's color, and writing
      // the shorthand here would take that with it.
      textarea.style.backgroundImage = background?.backgroundImage ?? '';
      textarea.style.backgroundPosition = background?.backgroundPosition ?? '';
      textarea.style.backgroundRepeat = background?.backgroundRepeat ?? '';
      textarea.style.backgroundSize = background?.backgroundSize ?? '';
    }

    this.verticalLinesApplied = lines.length > 0;
  }

  /**
   * Keep the width-override sheet in step with the rules — built on the first
   * rule thicker than the 1px Monaco draws, and dropped again when none is
   * left, so the default case ships no CSS at all.
   */
  private syncVerticalLineWidthStyle(
    lines: readonly ResolvedEditorVerticalLine[],
  ): void {
    const scopeEl = this.getVerticalLineScopeElement();
    const css = scopeEl
      ? buildVerticalLineWidthCss(
          `[${VERTICAL_LINES_SCOPE_ATTRIBUTE}="${this.verticalLinesScopeId}"]`,
          lines,
        )
      : '';

    if (!css) {
      scopeEl?.removeAttribute(VERTICAL_LINES_SCOPE_ATTRIBUTE);
      this.verticalLinesStyleEl?.remove();
      this.verticalLinesStyleEl = null;
      return;
    }

    scopeEl?.setAttribute(
      VERTICAL_LINES_SCOPE_ATTRIBUTE,
      this.verticalLinesScopeId,
    );
    if (!this.verticalLinesStyleEl) {
      const style = document.createElement('style');
      style.setAttribute(
        VERTICAL_LINES_SCOPE_ATTRIBUTE,
        this.verticalLinesScopeId,
      );
      document.head.append(style);
      this.verticalLinesStyleEl = style;
    }
    this.verticalLinesStyleEl.textContent = css;
  }

  /**
   * What the width CSS is scoped to: this instance's own surface host when it
   * has one, else — facade mode — the host application's Monaco root, which is
   * the surface the rules were pushed onto. Null when there is neither, and the
   * sheet is then not built at all.
   */
  private getVerticalLineScopeElement(): HTMLElement | null {
    if (this.surfaceEl) {
      return this.surfaceEl;
    }
    const domNode = this.monacoEditor?.getDomNode?.();
    return typeof domNode?.setAttribute === 'function' ? domNode : null;
  }

  /**
   * Drop everything the rules put outside this component — the width sheet in
   * `document.head`, and the scope marker, which in facade mode sits on an
   * element the host owns and must be handed back clean.
   */
  private teardownVerticalLines(): void {
    if (this.verticalLinesApplied) {
      // Matters in facade mode, where the surface outlives this instance; on
      // an owned mount the editor it speaks to is disposed moments later.
      this.monacoEditor?.updateOptions?.({ rulers: [] });
    }
    this.getVerticalLineScopeElement()?.removeAttribute(
      VERTICAL_LINES_SCOPE_ATTRIBUTE,
    );
    this.verticalLinesStyleEl?.remove();
    this.verticalLinesStyleEl = null;
    this.verticalLinesApplied = false;
  }

  private setValueInternal(next: string): void {
    if (this.sharedSurfaceBridge) {
      // Writes route through the host's own document pipeline; the host
      // reports back via notifySharedSurfaceValueChange().
      if (this.getValue() !== next) {
        this.sharedSurfaceBridge.setValue(next);
      }
      return;
    }
    if (this.simpleModeEnabled && this.simpleTextareaEl) {
      // Monaco (still holding the previous text) is re-synced when simple mode
      // is turned off, so the two surfaces never fight over the document.
      if (this.simpleTextareaEl.value !== next) {
        this.simpleTextareaEl.value = next;
        this.emitValueChange();
      }
      return;
    }
    if (this.model) {
      // Monaco fires onDidChangeModelContent → emitValueChange handles events.
      if (this.model.getValue() !== next) {
        this.model.setValue(next);
      }
      return;
    }
    if (this.textareaEl) {
      if (this.textareaEl.value !== next) {
        this.textareaEl.value = next;
        this.emitValueChange();
      }
      return;
    }
    // Not mounted: store only; a live surface emits change once it exists.
    this.valueText = next;
    this.lastEmittedValue = next;
  }

  private emitValueChange(): void {
    const oldValue = this.lastEmittedValue;
    const newValue = this.getValue();
    if (newValue === oldValue) {
      return;
    }
    this.lastEmittedValue = newValue;
    this.valueText = newValue;
    // Before the listeners: the chrome re-renders its menu off the `change`
    // event, and by then the Reset/Save pair has to know it is enabled.
    this.setDirtyState(newValue !== this.savedValueText);
    // Facade mode keeps plugins dormant (the host application provides the
    // editor features); `change` still mirrors the shared document.
    if (!this.sharedSurfaceBridge) {
      this.pluginHost.handleValueChange(oldValue, newValue);
    }
    this.emitter.emit('change', { oldValue, newValue });
  }

  private lineColumnToOffset(
    text: string,
    line: number,
    column: number,
  ): number {
    const lines = String(text ?? '').split('\n');
    const lineIndex = Math.min(line - 1, lines.length - 1);
    let offset = 0;
    for (let index = 0; index < lineIndex; index += 1) {
      offset += lines[index].length + 1;
    }
    offset += Math.min(column - 1, (lines[lineIndex] ?? '').length);
    return offset;
  }
}
