// Word suggestions — the single source shared by the app's
// `MonacoFeatureController` and the standalone `EditorStandaloneChrome`.
//
// Monaco's built-in word-based suggestions are deliberately kept OFF on every
// surface (`suggest.showWords`): they rank purely by proximity, cannot label
// where a word came from, and know nothing about the Hunspell dictionaries the
// editor ships. This module is the replacement — current-document words first,
// then dictionary suggestions from `scripts/spellcheck.ts` — plus the
// manual-trigger session that lets Ctrl/Cmd+Space open the widget while
// auto-suggest is off.
//
// Everything here is parameterized by the Monaco namespace rather than reading
// a global, so a standalone `Editor` embed and the app pages can register the
// same provider against their own instances.

import { LANGUAGE_ID, MONACO_WORD_PATTERN } from './shared.ts';
import {
  detectLanguageCode,
  getWordSeparator,
  getWordSuggestTriggerCharacters as getRegisteredSuggestTriggerCharacters,
} from './spellcheck-common.ts';
import { loadAutocompleteSpellcheckSuggestions } from './spellcheck.ts';

/** The Monaco action id both surfaces expose in the command palette. */
export const WORD_SUGGEST_ACTION_ID = 'open-lyric.trigger-suggest';
/** Monaco's own "trigger suggest", which the manual shortcut delegates to. */
export const MONACO_TRIGGER_SUGGEST_ACTION_ID = 'editor.action.triggerSuggest';
export const WORD_SUGGEST_SHORTCUT_LABEL = 'Ctrl/Cmd+Space';

/**
 * How long a manual trigger keeps answering. The initial window covers the
 * first request Monaco makes right after the shortcut; the session window is
 * refreshed on every answered request, so the widget keeps up as the user
 * narrows the fragment but lapses once they move on.
 */
export const WORD_SUGGEST_INITIAL_TTL_MS = 250;
export const WORD_SUGGEST_SESSION_TTL_MS = 1500;

export const WORD_SUGGEST_MAX_DOCUMENT_RESULTS = 20;
export const WORD_SUGGEST_MAX_DICTIONARY_RESULTS = 40;

/** `markdown` too, so the plain-markdown fallback model still gets words. */
export const WORD_SUGGEST_LANGUAGE_IDS: readonly string[] = [
  LANGUAGE_ID,
  'markdown',
];

/**
 * Autocomplete trigger characters, taken from the registered languages'
 * `suggestTriggerCharacters`.
 *
 * A script that runs without spaces has no separator keystroke to trigger on,
 * so every one of its letters has to be a trigger. Which letters those are is
 * the language plugin's business — each contributes its own range — so this
 * module carries no character range of its own.
 */
export function getWordSuggestTriggerCharacters(): string[] {
  return getRegisteredSuggestTriggerCharacters();
}

const DOCUMENT_SUGGESTION_DETAIL = 'Current document';

/** The slice of a Monaco text model the suggestion pass needs. */
export interface WordSuggestionModel {
  getValue(): string;
  getLineContent(lineNumber: number): string;
}

export interface WordSuggestionPosition {
  lineNumber: number;
  column: number;
}

/** The partial word under the caret, and the range it occupies. */
export interface WordSuggestionContext {
  fragment: string;
  /** 1-based, Monaco column convention. */
  startColumn: number;
  endColumn: number;
}

export interface WordSuggestionEntry {
  detail: string;
  /** `null` when no registered spellcheck spec claims the word. */
  languageCode: string | null;
  suggestion: string;
}

/** One dictionary hit, as `scripts/spellcheck.ts` reports it. */
export interface DictionarySuggestion {
  sourceLabel?: string;
  suggestion: string;
}

export type LoadDictionarySuggestions = (
  word: string,
  options: { limit?: number },
) => Promise<DictionarySuggestion[]> | DictionarySuggestion[];

export interface CancellationTokenLike {
  isCancellationRequested?: boolean;
}

/** Elapsed-time source: monotonic where available, so a clock change can't strand a session. */
export function wordSuggestionNow(): number {
  return typeof globalThis.performance?.now === 'function'
    ? globalThis.performance.now()
    : Date.now();
}

/**
 * Match the fragment's casing so an ALL-CAPS or Capitalized prefix does not
 * come back lowercased from the dictionary.
 */
export function shapeWordSuggestion(
  fragment: string,
  suggestion: string,
): string {
  const normalizedFragment = String(fragment || '');
  const normalizedSuggestion = String(suggestion || '');

  if (!normalizedFragment || !normalizedSuggestion) {
    return normalizedSuggestion;
  }

  if (normalizedFragment.toUpperCase() === normalizedFragment) {
    return normalizedSuggestion.toUpperCase();
  }

  if (
    normalizedFragment[0] &&
    normalizedFragment[0].toUpperCase() === normalizedFragment[0] &&
    normalizedFragment.slice(1).toLowerCase() === normalizedFragment.slice(1)
  ) {
    return (
      (normalizedSuggestion[0]?.toUpperCase() ?? '') +
      normalizedSuggestion.slice(1)
    );
  }

  return normalizedSuggestion;
}

/**
 * The word being typed, taken from the caret's own line.
 *
 * Monaco's `getWordUntilPosition` is not usable here: it splits on
 * `wordSeparators`, which for an invisibly separated script means the whole
 * run reads as one word.
 * Re-scanning the line with {@link MONACO_WORD_PATTERN} keeps both surfaces on
 * the same definition of a word as the language configuration.
 */
export function getWordSuggestionContext(
  model: WordSuggestionModel | null | undefined,
  position: WordSuggestionPosition | null | undefined,
): WordSuggestionContext | null {
  const lineNumber = Number(position?.lineNumber);
  const requestedColumn = Number(position?.column);
  const lineContent = model?.getLineContent?.(lineNumber);

  if (
    !model ||
    !Number.isInteger(lineNumber) ||
    !Number.isInteger(requestedColumn) ||
    typeof lineContent !== 'string'
  ) {
    return null;
  }

  const column = Math.max(1, Math.min(requestedColumn, lineContent.length + 1));
  const cursorIndex = column - 1;
  const wordPattern = new RegExp(
    MONACO_WORD_PATTERN.source,
    MONACO_WORD_PATTERN.flags,
  );

  for (const match of lineContent.matchAll(wordPattern)) {
    const matchedWord = String(match?.[0] || '');
    const startIndex = Number(match?.index);

    if (!matchedWord || !Number.isInteger(startIndex)) {
      continue;
    }

    const endIndex = startIndex + matchedWord.length;

    // The caret must sit inside the word, never at its opening edge — there is
    // no prefix to complete from there.
    if (cursorIndex <= startIndex || cursorIndex > endIndex) {
      continue;
    }

    const fragment = matchedWord.slice(0, cursorIndex - startIndex).trim();

    if (!fragment) {
      return null;
    }

    return {
      fragment,
      startColumn: startIndex + 1,
      endColumn: column,
    };
  }

  return null;
}

/**
 * Words already in the document that extend the fragment — the fastest way to
 * stay consistent with terms this song has established, dictionary or not.
 * Shortest first, so the nearest completion is the default pick.
 */
export function collectDocumentWordSuggestions(
  model: WordSuggestionModel | null | undefined,
  fragment: string,
  limit: number = WORD_SUGGEST_MAX_DOCUMENT_RESULTS,
): WordSuggestionEntry[] {
  const normalizedFragment = String(fragment || '').trim();

  if (!model || !normalizedFragment) {
    return [];
  }

  const matches = Array.from(
    String(model.getValue?.() ?? '').matchAll(
      new RegExp(MONACO_WORD_PATTERN.source, MONACO_WORD_PATTERN.flags),
    ),
  );
  const normalizedFragmentLower = normalizedFragment.toLocaleLowerCase();
  const documentWords = new Map<string, string>();

  matches.forEach((match) => {
    const candidateWord = String(match?.[0] || '').trim();
    const candidateKey = candidateWord.toLocaleLowerCase();

    if (
      !candidateWord ||
      candidateKey === normalizedFragmentLower ||
      !candidateKey.startsWith(normalizedFragmentLower)
    ) {
      return;
    }

    if (!documentWords.has(candidateKey)) {
      documentWords.set(
        candidateKey,
        shapeWordSuggestion(normalizedFragment, candidateWord),
      );
    }
  });

  return Array.from(documentWords.values())
    .sort((left, right) => {
      if (left.length !== right.length) {
        return left.length - right.length;
      }

      return left.localeCompare(right, undefined, { sensitivity: 'base' });
    })
    .slice(0, Math.max(0, limit))
    .map((suggestion) => ({
      detail: DOCUMENT_SUGGESTION_DETAIL,
      languageCode: detectLanguageCode(suggestion),
      suggestion,
    }));
}

/**
 * What to append after an accepted word at end of line: the language's own
 * word separator (an invisible one for scripts that declare it, a plain space
 * otherwise). Mid-line acceptances append nothing — the following text already
 * provides the boundary.
 */
export function resolveWordSuggestionSuffix(
  languageCode: string | null,
  model: WordSuggestionModel | null | undefined,
  position: WordSuggestionPosition | null | undefined,
): string {
  if (!model || !position) {
    return '';
  }

  const nextCharacter = String(
    model.getLineContent?.(position.lineNumber) ?? '',
  ).charAt(Math.max(0, position.column - 1));

  if (nextCharacter) {
    return '';
  }

  // The language's own boundary mark: an invisible separator for scripts that
  // declare one, a plain space for everything else (the default).
  return getWordSeparator(languageCode);
}

/* ------------------------------- session -------------------------------- */

/** Where a session keeps its two expiry stamps (the app backs this with `runtime`). */
export interface WordSuggestionSessionStore {
  initialExpiryMs: number;
  sessionExpiryMs: number;
}

export interface WordSuggestionSession {
  /** A manual trigger fired: start answering. */
  begin(): void;
  /** A request was answered: keep answering while the user narrows the word. */
  extend(): void;
  clear(): void;
  isActive(): boolean;
}

export function createWordSuggestionSession(
  store: WordSuggestionSessionStore = {
    initialExpiryMs: 0,
    sessionExpiryMs: 0,
  },
  now: () => number = wordSuggestionNow,
): WordSuggestionSession {
  return {
    begin() {
      const timestamp = now();
      store.initialExpiryMs = timestamp + WORD_SUGGEST_INITIAL_TTL_MS;
      store.sessionExpiryMs = timestamp + WORD_SUGGEST_SESSION_TTL_MS;
    },
    extend() {
      store.sessionExpiryMs = now() + WORD_SUGGEST_SESSION_TTL_MS;
    },
    clear() {
      store.initialExpiryMs = 0;
      store.sessionExpiryMs = 0;
    },
    isActive() {
      const timestamp = now();
      return (
        timestamp <= Number(store.initialExpiryMs || 0) ||
        timestamp <= Number(store.sessionExpiryMs || 0)
      );
    },
  };
}

/**
 * Whether Monaco's suggest widget is on screen. Once it is open the user is in
 * a suggestion flow, so keep answering even with auto-suggest off.
 */
export function isSuggestWidgetVisible(
  ownerDocument: Document | null | undefined = globalThis.document,
): boolean {
  return Boolean(ownerDocument?.querySelector?.('.suggest-widget.visible'));
}

function isApplePlatform(): boolean {
  const navigatorLike = globalThis.navigator as
    (Navigator & { userAgentData?: { platform?: string } }) | undefined;
  const platform =
    navigatorLike?.userAgentData?.platform ||
    navigatorLike?.platform ||
    navigatorLike?.userAgent ||
    '';

  return /mac|iphone|ipad|ipod/iu.test(platform);
}

/**
 * The manual-trigger chords. Apple hardware keeps Cmd+Space for the OS input
 * switcher / Spotlight, so plain Ctrl+Space is registered alongside it there.
 */
export function resolveWordSuggestKeybindings(monaco: any): number[] {
  const keyMod = monaco?.KeyMod;
  const space = monaco?.KeyCode?.Space;

  if (!keyMod || typeof space !== 'number') {
    return [];
  }

  const keybindings = [keyMod.CtrlCmd | space];

  if (isApplePlatform() && typeof keyMod.WinCtrl === 'number') {
    keybindings.push(keyMod.WinCtrl | space);
  }

  return keybindings;
}

/* ------------------------------- provider -------------------------------- */

export interface BuildWordSuggestionsOptions {
  monaco: any;
  model: WordSuggestionModel | null | undefined;
  position: WordSuggestionPosition | null | undefined;
  token?: CancellationTokenLike | null;
  session?: WordSuggestionSession | null;
  loadDictionarySuggestions?: LoadDictionarySuggestions;
  maxDocumentResults?: number;
  maxDictionaryResults?: number;
}

function createSuggestionRange(
  monaco: any,
  lineNumber: number,
  startColumn: number,
  endColumn: number,
): unknown {
  if (typeof monaco?.Range === 'function') {
    return new monaco.Range(lineNumber, startColumn, lineNumber, endColumn);
  }

  // A plain `IRange` — Monaco lifts it, so an embed without the constructor
  // (or a test double) still gets a usable completion item.
  return {
    startLineNumber: lineNumber,
    startColumn,
    endLineNumber: lineNumber,
    endColumn,
  };
}

/**
 * Build the completion list for the word under the caret: document words
 * first (`zz1-` sort keys), then dictionary suggestions (`zz2-`), both after
 * anything the Open Lyric language itself contributes.
 */
export async function buildWordSuggestions({
  monaco,
  model,
  position,
  token,
  session,
  loadDictionarySuggestions = loadAutocompleteSpellcheckSuggestions,
  maxDocumentResults = WORD_SUGGEST_MAX_DOCUMENT_RESULTS,
  maxDictionaryResults = WORD_SUGGEST_MAX_DICTIONARY_RESULTS,
}: BuildWordSuggestionsOptions): Promise<{
  incomplete: boolean;
  suggestions: any[];
}> {
  const wordContext = getWordSuggestionContext(model, position);
  const fragment = String(wordContext?.fragment || '');

  if (!fragment || !wordContext || !position) {
    return { incomplete: true, suggestions: [] };
  }

  session?.extend();

  const kind = monaco?.languages?.CompletionItemKind?.Value;
  const range = createSuggestionRange(
    monaco,
    position.lineNumber,
    wordContext.startColumn,
    wordContext.endColumn,
  );
  const suggestions: any[] = [];
  const seenSuggestions = new Set<string>();

  const pushEntry = (
    entry: WordSuggestionEntry,
    index: number,
    sortGroup: string,
  ) => {
    const suggestionKey = entry.suggestion.toLocaleLowerCase();

    if (seenSuggestions.has(suggestionKey)) {
      return;
    }

    seenSuggestions.add(suggestionKey);
    suggestions.push({
      detail: entry.detail,
      kind,
      label: entry.suggestion,
      insertText: `${entry.suggestion}${resolveWordSuggestionSuffix(
        entry.languageCode,
        model,
        position,
      )}`,
      filterText: entry.suggestion,
      range,
      sortText: `${sortGroup}-${String(index).padStart(4, '0')}-${suggestionKey}`,
    });
  };

  collectDocumentWordSuggestions(model, fragment, maxDocumentResults).forEach(
    (entry, index) => pushEntry(entry, index, 'zz1'),
  );

  const dictionarySuggestions =
    typeof loadDictionarySuggestions === 'function'
      ? ((await loadDictionarySuggestions(fragment, {
          limit: maxDictionaryResults,
        })) ?? [])
      : [];

  if (token?.isCancellationRequested) {
    return { incomplete: true, suggestions };
  }

  dictionarySuggestions.forEach((entry, index) => {
    const suggestion = String(entry?.suggestion || '');
    if (!suggestion) {
      return;
    }

    pushEntry(
      {
        detail: String(entry?.sourceLabel || ''),
        languageCode: detectLanguageCode(suggestion),
        suggestion,
      },
      index,
      'zz2',
    );
  });

  // Reported as incomplete so Monaco re-queries as the fragment grows instead
  // of only filtering a stale result set — the dictionary results change
  // entirely between prefixes.
  return { incomplete: true, suggestions };
}

export interface WordSuggestionProviderOptions extends Omit<
  BuildWordSuggestionsOptions,
  'model' | 'position' | 'token'
> {
  /**
   * Gate consulted per request — auto-suggest state, an active session, and
   * (for a standalone embed) whether the model is even this editor's, since
   * Monaco keeps completion providers page-globally.
   */
  shouldProvide?: (
    model: WordSuggestionModel,
    position: WordSuggestionPosition,
  ) => boolean;
}

export function createWordSuggestionProvider(
  options: WordSuggestionProviderOptions,
): any {
  return {
    triggerCharacters: getWordSuggestTriggerCharacters(),
    provideCompletionItems: async (
      model: WordSuggestionModel,
      position: WordSuggestionPosition,
      _context: unknown,
      token?: CancellationTokenLike,
    ) => {
      if (options.shouldProvide && !options.shouldProvide(model, position)) {
        return { suggestions: [] };
      }

      if (token?.isCancellationRequested) {
        return { suggestions: [] };
      }

      return buildWordSuggestions({ ...options, model, position, token });
    },
  };
}

export interface RegisterWordSuggestionProviderOptions extends WordSuggestionProviderOptions {
  languageIds?: readonly string[];
}

/**
 * Register the provider for every supported language id. Monaco keeps
 * completion providers page-globally, so the returned disposable is what scopes
 * it to the caller's lifetime.
 */
export function registerWordSuggestionProvider({
  languageIds = WORD_SUGGEST_LANGUAGE_IDS,
  ...options
}: RegisterWordSuggestionProviderOptions): { dispose(): void } {
  const languages = options.monaco?.languages;

  if (typeof languages?.registerCompletionItemProvider !== 'function') {
    return { dispose() {} };
  }

  const provider = createWordSuggestionProvider(options);
  const disposables = languageIds.map((languageId) =>
    languages.registerCompletionItemProvider(languageId, provider),
  );

  return {
    dispose() {
      disposables.forEach((disposable) => {
        disposable?.dispose?.();
      });
    },
  };
}
