import { getOpenLyricMonacoApi } from '../../scripts/open-lyric-plugin.ts';
import {
  LANGUAGE_THEME,
  MONACO_THEME_BY_APP_THEME,
} from '../../scripts/shared.ts';
import type { OpenLyricTheme } from './types.ts';

/**
 * Self-contained Monaco boot for the standalone `Editor`.
 *
 * It reuses the same lazy runtime chunk the app uses (`monaco-runtime.ts`,
 * cached as an ES module) but wires nothing into the global app: no
 * `state.editor`, no `refs`. Language + theme registration is globally
 * idempotent, so any number of standalone editors share one registration.
 */

import type * as MonacoRuntimeNamespace from '../../scripts/monaco-runtime.ts';

type MonacoRuntimeModule = typeof MonacoRuntimeNamespace;
export type MonacoNamespace = MonacoRuntimeModule['monaco'];
type EditorWorkerCtor = MonacoRuntimeModule['EditorWorker'];

/** Loader for the Monaco runtime chunk; injectable for tests / embeds. */
export type LoadMonacoResources = () =>
  Promise<Partial<MonacoRuntimeModule>> | Partial<MonacoRuntimeModule>;

export const defaultLoadMonacoResources: LoadMonacoResources = () =>
  import('../../scripts/monaco-runtime.ts');

/** Map a component theme to its registered Monaco theme name. */
export function getEditorThemeName(theme: OpenLyricTheme): string {
  return MONACO_THEME_BY_APP_THEME[theme] ?? LANGUAGE_THEME;
}

/**
 * Load Monaco, configure its web worker once, and register the Open Lyric
 * language + themes (idempotent). Returns the Monaco namespace.
 */
export async function loadOpenLyricMonaco(
  loadResources: LoadMonacoResources,
): Promise<MonacoNamespace> {
  const runtimeModule = await Promise.resolve(loadResources());
  const monaco = runtimeModule?.monaco;
  const EditorWorker = runtimeModule?.EditorWorker as
    EditorWorkerCtor | undefined;

  if (!monaco?.editor || !EditorWorker) {
    throw new Error('Monaco resources are unavailable.');
  }

  const monacoEnvironment = (
    globalThis as typeof globalThis & {
      MonacoEnvironment?: { getWorker?: (...args: unknown[]) => Worker };
    }
  ).MonacoEnvironment;

  if (!monacoEnvironment?.getWorker) {
    (
      globalThis as typeof globalThis & { MonacoEnvironment?: unknown }
    ).MonacoEnvironment = {
      ...(monacoEnvironment || {}),
      getWorker: () => new EditorWorker(),
    };
  }

  // The OL language module reads the page-global `monaco` (the same global
  // the application's loader sets). Monaco is inherently page-global anyway
  // (themes, MonacoEnvironment), so provide it before registering.
  const monacoHost = globalThis as typeof globalThis & { monaco?: unknown };
  if (!monacoHost.monaco) {
    monacoHost.monaco = monaco;
  }

  // Registers the `markdown-ol` language and defines the OL Monaco themes.
  // No-op after the first call anywhere on the page.
  getOpenLyricMonacoApi()?.registerMarkdownOlLanguage?.();

  return monaco;
}
