import selectionStatsStylesheetUrl from '../styles/selection-stats.scss?url';
import { injectStylesheetLinkOnce } from '../components/internal/inject-style.ts';
import { getCurrentValue, refs, state } from './shared.ts';

const STATS_ELEMENT_ID = 'editorSelectionStats';
const STATS_ELEMENT_CLASS = 'editor-panel__selection-stats';
/** Head marker for the readout's own stylesheet, linked at install time. */
const STATS_STYLE_ELEMENT_ID = 'open-lyric-selection-stats-styles';
const SURFACE_SYNC_INTERVAL_MS = 250;
const STARTUP_REFRESH_INTERVAL_MS = 250;
const STARTUP_REFRESH_DURATION_MS = 6000;
const TEXTAREA_EVENTS = [
  'input',
  'select',
  'keyup',
  'mouseup',
  'touchend',
  'focus',
];

const wordSegmenter =
  typeof Intl !== 'undefined' && typeof Intl.Segmenter === 'function'
    ? new Intl.Segmenter(undefined, { granularity: 'word' })
    : null;

/**
 * The subset of a standalone `Editor` this readout reads. Structural on
 * purpose: passing the component keeps `selection-stats.ts` out of the
 * component's import graph (and out of every bundle that never installs it).
 */
interface EditorSelectionStatsEditorLike {
  container: HTMLElement | null;
  surfaceKind: string;
  activeTextarea: HTMLTextAreaElement | null;
  monacoEditor: any;
  getValue(): string;
  on(event: any, handler: () => void): () => void;
}

interface EditorSelectionStatsOptions {
  /**
   * Read counts from this standalone `Editor` instead of the app shell's
   * surface state. Pass it on a page that mounts an `Editor` of its own
   * (`ol-lyric-editor.html`); omit it on the app pages, where the readout
   * follows whichever surface the shell is editing through.
   */
  editor?: EditorSelectionStatsEditorLike;
  /** Mount target override; defaults to the source's editor panel body. */
  container?: HTMLElement | null;
}

function normalizeText(text) {
  return String(text ?? '').replace(/\r\n?/g, '\n');
}

function pluralize(count, singular, plural) {
  return `${count} ${count === 1 ? singular : plural}`;
}

function countWords(text) {
  const normalizedText = normalizeText(text).trim();

  if (!normalizedText) {
    return 0;
  }

  if (wordSegmenter) {
    let wordCount = 0;

    for (const segment of wordSegmenter.segment(normalizedText)) {
      if (segment.isWordLike) {
        wordCount += 1;
      }
    }

    if (wordCount > 0) {
      return wordCount;
    }
  }

  return normalizedText.split(/[\s\u200b]+/u).filter(Boolean).length;
}

function countCharacters(text) {
  return Array.from(normalizeText(text)).length;
}

function getTextTotals(texts) {
  return texts.reduce(
    (totals, text) => {
      totals.words += countWords(text);
      totals.characters += countCharacters(text);
      return totals;
    },
    { words: 0, characters: 0 },
  );
}

function isMonacoSelectionEmpty(selection) {
  return (
    !selection ||
    (selection.startLineNumber === selection.endLineNumber &&
      selection.startColumn === selection.endColumn)
  );
}

/** Selected text (or the whole document) of a live Monaco editor instance. */
function getMonacoTextParts(editor) {
  const model = editor?.getModel?.();

  if (!editor || !model) {
    return null;
  }

  const selections =
    typeof editor.getSelections === 'function'
      ? editor.getSelections()
      : [editor.getSelection?.()].filter(Boolean);
  const selectedTexts = (selections || [])
    .filter((selection) => !isMonacoSelectionEmpty(selection))
    .map((selection) => model.getValueInRange(selection))
    .filter((text) => text.length > 0);

  if (selectedTexts.length > 0) {
    return { scope: 'Selected', texts: selectedTexts };
  }

  const value = editor.getValue?.() ?? model.getValue?.() ?? '';
  return { scope: 'All', texts: [value] };
}

/** Same, for a plain textarea surface (Simple Editor / Monaco fallback). */
function getTextareaTextParts(textarea) {
  if (!(textarea instanceof HTMLTextAreaElement)) {
    return null;
  }

  const value = textarea.value;
  const start = Math.min(
    textarea.selectionStart ?? 0,
    textarea.selectionEnd ?? 0,
  );
  const end = Math.max(
    textarea.selectionStart ?? 0,
    textarea.selectionEnd ?? 0,
  );

  if (start !== end) {
    return { scope: 'Selected', texts: [value.slice(start, end)] };
  }

  return { scope: 'All', texts: [value] };
}

/**
 * Where the counts come from, and where the readout lives. Two implementations
 * — the app shell's `state`/`refs` surfaces, and a standalone `Editor`
 * instance — so one readout serves every page that edits text.
 */
function createShellSource() {
  return {
    // The shell readout owns the well-known id: e2e specs and host CSS
    // target `#editorSelectionStats`, and a page has at most one shell.
    ownsSharedId: true,
    getPanelBody: () =>
      document.querySelector('[data-ol-ref="editorPanel"] .editor-panel__body'),
    getMonacoEditor: () => state.editor || null,
    // The shell's textarea is static markup, bound once in subscribe().
    getTextarea: () => null,
    getTextParts: () => {
      const parts =
        state.editorMode === 'simple'
          ? getTextareaTextParts(refs.simpleEditorTextarea)
          : getMonacoTextParts(
              state.editorMode === 'monaco' ? state.editor : null,
            );

      return parts || { scope: 'All', texts: [getCurrentValue()] };
    },
    subscribe: (scheduleUpdate) => {
      const textarea = refs.simpleEditorTextarea;
      const toggle = refs.simpleEditorToggle;

      for (const eventName of TEXTAREA_EVENTS) {
        textarea?.addEventListener(eventName, scheduleUpdate);
      }
      toggle?.addEventListener('change', scheduleUpdate);

      return () => {
        for (const eventName of TEXTAREA_EVENTS) {
          textarea?.removeEventListener(eventName, scheduleUpdate);
        }
        toggle?.removeEventListener('change', scheduleUpdate);
      };
    },
  };
}

function createComponentSource(editor: EditorSelectionStatsEditorLike) {
  return {
    // A component readout never claims the shared id unless the page has no
    // shell readout — several `Editor` embeds can share one page.
    ownsSharedId: false,
    getPanelBody: () => {
      const root = editor.container;

      if (!(root instanceof HTMLElement)) {
        return null;
      }

      // `chrome: true` (the default) builds the panel; a bare surface has
      // none, so the host container is the next best positioned ancestor.
      return root.querySelector('.editor-panel__body') || root;
    },
    getMonacoEditor: () => editor.monacoEditor || null,
    // Built lazily when the user switches to Simple Editor, so it is resolved
    // on every sync tick rather than bound once.
    getTextarea: () => editor.activeTextarea || null,
    getTextParts: () => {
      const parts =
        editor.surfaceKind === 'textarea'
          ? getTextareaTextParts(editor.activeTextarea)
          : getMonacoTextParts(
              editor.surfaceKind === 'monaco' ? editor.monacoEditor : null,
            );

      return parts || { scope: 'All', texts: [editor.getValue()] };
    },
    subscribe: (scheduleUpdate) => editor.on('change', scheduleUpdate),
  };
}

/**
 * The stats readout is this feature's own UI: pages don't ship it in their
 * markup (the editor panel is a shared fragment — see
 * `src/editor/html/editor-panel.html`, and the standalone chrome builds its
 * own); calling {@link installEditorSelectionStats} creates it inside the
 * editor panel body.
 */
function ensureStatsElement(mountTarget, ownsSharedId) {
  if (ownsSharedId) {
    const existingElement = document.getElementById(STATS_ELEMENT_ID);

    if (existingElement instanceof HTMLElement) {
      return { element: existingElement, created: false };
    }
  } else if (mountTarget instanceof HTMLElement) {
    const existingElement = mountTarget.querySelector(
      `.${STATS_ELEMENT_CLASS}`,
    );

    if (existingElement instanceof HTMLElement) {
      return { element: existingElement, created: false };
    }
  }

  if (!(mountTarget instanceof HTMLElement)) {
    return { element: null, created: false };
  }

  const statsElement = document.createElement('div');

  if (ownsSharedId || !document.getElementById(STATS_ELEMENT_ID)) {
    statsElement.id = STATS_ELEMENT_ID;
  }

  statsElement.className = STATS_ELEMENT_CLASS;
  statsElement.setAttribute('role', 'status');
  statsElement.setAttribute('aria-live', 'polite');
  statsElement.setAttribute('aria-atomic', 'true');
  statsElement.textContent = 'All: 0 words / 0 chars';
  mountTarget.append(statsElement);

  return { element: statsElement, created: true };
}

/**
 * Install the live "words / characters" readout on an editor surface.
 *
 * Every piece of per-install state lives in this closure, so a page may
 * install one readout per editor it shows (the app shell's editor panel, plus
 * any standalone `Editor` embeds). Returns its teardown; it also runs on
 * `pagehide`.
 */
function installEditorSelectionStats(
  options: EditorSelectionStatsOptions = {},
) {
  const source = options.editor
    ? createComponentSource(options.editor)
    : createShellSource();
  const mountTarget =
    options.container instanceof HTMLElement
      ? options.container
      : source.getPanelBody();
  const { element: statsElement, created } = ensureStatsElement(
    mountTarget,
    source.ownsSharedId,
  );

  if (!(statsElement instanceof HTMLElement)) {
    return () => {};
  }

  // The readout ships its own stylesheet the same way the surface classes'
  // `installShellStyle()` statics ship theirs — the page links nothing.
  injectStylesheetLinkOnce(STATS_STYLE_ELEMENT_ID, selectionStatsStylesheetUrl);

  let frameId = 0;
  let lastLabel = '';
  let boundMonacoEditor = null;
  let monacoDisposables = [];
  let boundTextarea = null;
  let isTornDown = false;

  const scheduleUpdate = () => {
    if (frameId || isTornDown) {
      return;
    }

    frameId = requestAnimationFrame(() => {
      // A frame requested just before teardown still fires; the surfaces it
      // would read are already gone by then.
      if (isTornDown) {
        return;
      }

      updateStats();
    });
  };

  function disposeMonacoListeners() {
    for (const disposable of monacoDisposables) {
      disposable?.dispose?.();
    }

    boundMonacoEditor = null;
    monacoDisposables = [];
  }

  function unbindTextarea() {
    for (const eventName of TEXTAREA_EVENTS) {
      boundTextarea?.removeEventListener(eventName, scheduleUpdate);
    }

    boundTextarea = null;
  }

  /**
   * Surfaces come and go under the readout — Monaco boots asynchronously, the
   * Simple Editor textarea is built on first use, and the app shell swaps
   * between them — so both bindings are re-resolved rather than bound once.
   */
  function syncSurfaceListeners() {
    const nextEditor = source.getMonacoEditor();

    if (nextEditor !== boundMonacoEditor) {
      disposeMonacoListeners();
      boundMonacoEditor = nextEditor;

      if (boundMonacoEditor) {
        if (typeof boundMonacoEditor.onDidChangeModelContent === 'function') {
          monacoDisposables.push(
            boundMonacoEditor.onDidChangeModelContent(scheduleUpdate),
          );
        }

        if (
          typeof boundMonacoEditor.onDidChangeCursorSelection === 'function'
        ) {
          monacoDisposables.push(
            boundMonacoEditor.onDidChangeCursorSelection(scheduleUpdate),
          );
        }

        if (typeof boundMonacoEditor.onDidChangeModel === 'function') {
          monacoDisposables.push(
            boundMonacoEditor.onDidChangeModel(scheduleUpdate),
          );
        }
      }
    }

    const nextTextarea = source.getTextarea();

    if (nextTextarea !== boundTextarea) {
      unbindTextarea();
      boundTextarea = nextTextarea;

      for (const eventName of TEXTAREA_EVENTS) {
        boundTextarea?.addEventListener(eventName, scheduleUpdate);
      }
    }
  }

  function updateStats() {
    frameId = 0;
    syncSurfaceListeners();

    const { scope, texts } = source.getTextParts();
    const totals = getTextTotals(texts);
    const label = `${scope}: ${pluralize(totals.words, 'word', 'words')} / ${pluralize(
      totals.characters,
      'char',
      'chars',
    )}`;

    if (label === lastLabel) {
      return;
    }

    lastLabel = label;
    statsElement.textContent = label;
    statsElement.title = `${scope} text: ${pluralize(
      totals.words,
      'word',
      'words',
    )}, ${pluralize(totals.characters, 'character', 'characters')}`;
    statsElement.setAttribute('aria-label', statsElement.title);
  }

  const unsubscribeSource = source.subscribe(scheduleUpdate);

  document.addEventListener('selectionchange', scheduleUpdate);
  window.addEventListener('focus', scheduleUpdate);

  const surfaceSyncIntervalId = window.setInterval(
    syncSurfaceListeners,
    SURFACE_SYNC_INTERVAL_MS,
  );
  const startupRefreshIntervalId = window.setInterval(
    scheduleUpdate,
    STARTUP_REFRESH_INTERVAL_MS,
  );

  window.setTimeout(() => {
    window.clearInterval(startupRefreshIntervalId);
  }, STARTUP_REFRESH_DURATION_MS);

  const teardown = () => {
    if (isTornDown) {
      return;
    }

    isTornDown = true;

    if (frameId) {
      cancelAnimationFrame(frameId);
      frameId = 0;
    }

    window.clearInterval(surfaceSyncIntervalId);
    window.clearInterval(startupRefreshIntervalId);
    disposeMonacoListeners();
    unbindTextarea();
    unsubscribeSource?.();
    document.removeEventListener('selectionchange', scheduleUpdate);
    window.removeEventListener('focus', scheduleUpdate);
    window.removeEventListener('pagehide', teardown);

    // Take the readout with it, so turning the setting off actually hides it
    // — but only the element this install built; one it adopted from the page
    // belongs to whoever put it there.
    if (created) {
      statsElement.remove();
    }
  };

  window.addEventListener('pagehide', teardown);

  scheduleUpdate();

  return teardown;
}

export { installEditorSelectionStats };
export type { EditorSelectionStatsOptions };
