import { parseFenceHeader } from '../../domain/parser/fences.ts';
import {
  refs,
  replaceDocumentLineRange,
} from '../../../../editor/scripts/shared.ts';

/**
 * Starting a song from a blank markdown preview.
 *
 * A document with nothing in it renders as one card with a "Start a new song"
 * control (`OLConfig.renderPreviewEmptyDocument`). Pressing it writes the
 * smallest song the language accepts — a `Config` fence with every required
 * field filled, and the first section its `Structure` names — and opens the
 * `Title` editor with the placeholder selected, so the reader's first
 * keystroke is their song's title.
 *
 * The write is a text edit through `replaceDocumentLineRange`, never a DOM
 * mutation, so the panels, the text panel and the undo stack stay in step: one
 * press is one undo step. The document is re-read at press time and the write
 * is refused unless it is still blank, so a card a re-render left behind can
 * never overwrite a song.
 *
 * Markdown panel only — the lyric/presentation panel shares the delegated
 * listeners, so every lookup here is scoped to `refs.preview`.
 */

/** The section a started song opens with, as `Config` declares it. */
const FALLBACK_STARTER_SECTION_PART_NAME = 'Verse 1';

/**
 * The whole document "Start a new song" writes, as lines, or `null` when the
 * language has no `Config` definition to build it from.
 *
 * Both halves come from the `Config` fence definition, which is what keeps its
 * `- Structure:` step and the section written beside it naming the same part.
 */
function buildStarterDocumentLines() {
  const definition: any = parseFenceHeader('Config')?.definition || null;
  const bodyLines = definition?.getStarterBodyLines?.();

  if (!Array.isArray(bodyLines) || !bodyLines.length) {
    return null;
  }

  const sectionPartName = String(
    definition.getStarterSectionPartName?.() ||
      FALLBACK_STARTER_SECTION_PART_NAME,
  );
  const sectionHeader = parseFenceHeader(sectionPartName);

  if (!sectionHeader?.partName) {
    return null;
  }

  return [
    '```ol:Config',
    ...bodyLines.map((line) => String(line ?? '')),
    '```',
    '',
    `\`\`\`ol:${sectionHeader.partName}`,
    '```',
  ];
}

function isBlankDocument(markdown) {
  return !String(markdown ?? '').trim();
}

/** How many lines the blank document has — the range the starter replaces. */
function countDocumentLines(markdown) {
  return String(markdown ?? '')
    .replace(/\r\n?/g, '\n')
    .split('\n').length;
}

function applyPreviewControllerSongStartingMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    /**
     * Write the starter song into a blank document and open its `Title`.
     *
     * Returns whether the document was written. Refuses — writing nothing —
     * when the panel has no document behind it or the document is no longer
     * blank.
     */
    startPreviewSong(this: any) {
      if (!this.canEditPreviewSections()) {
        return false;
      }

      const markdown = this.getCurrentValue();

      if (!isBlankDocument(markdown)) {
        return false;
      }

      const starterLines = buildStarterDocumentLines();

      if (!starterLines) {
        return false;
      }

      // The blank lines a draft may hold are replaced rather than kept above
      // the song, so the `Config` fence is always the first line.
      const applied = replaceDocumentLineRange(
        1,
        countDocumentLines(markdown),
        starterLines,
      );

      if (!applied) {
        return false;
      }

      this.openStartedSongTitleEditor();

      return true;
    },

    /**
     * Hand the reader straight into the title. The placeholder is selected so
     * typing replaces it; a text input is the sanctioned touch-iOS auto-focus.
     * A panel that did not re-render (hidden, or not wired) has no Title
     * control to open, which leaves the write in place and nothing else.
     */
    openStartedSongTitleEditor(this: any) {
      const trigger = this.getPreviewConfigTextEditorTrigger?.('Title');

      if (!(trigger instanceof HTMLElement)) {
        return false;
      }

      trigger
        .closest('.ol-preview-fence')
        ?.scrollIntoView?.({ block: 'start', inline: 'nearest' });

      if (!this.openPreviewConfigTextEditor?.(trigger)) {
        return false;
      }

      this.previewConfigTextEditor?.input?.select?.();

      return true;
    },

    /** The "Start a new song" control, when the panel is showing it. */
    getPreviewStartSongTrigger(this: any) {
      if (!(refs.preview instanceof HTMLElement)) {
        return null;
      }

      return refs.preview.querySelector('[data-preview-action="start-song"]');
    },
  });
}

export {
  applyPreviewControllerSongStartingMethods,
  buildStarterDocumentLines,
  countDocumentLines,
  isBlankDocument,
};
