import { getOpenLyricThemeSurface } from '../../../../editor/components/internal/theme.ts';
import { getOpenLyricPreviewApi } from '../../../../editor/scripts/open-lyric-plugin.ts';
import {
  refs,
  setStatus,
  state,
  supportsClipboardCopy,
} from '../../../../editor/scripts/shared.ts';
import {
  OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
  isTransparentColor,
} from './constants.ts';

function getSelectedStructureKeys() {
  return state.openLyricStructureKeys &&
    typeof state.openLyricStructureKeys === 'object'
    ? state.openLyricStructureKeys
    : {};
}

function updatePreviewExportProgressElements(
  {
    progressElement = null,
    progressBarElement = null,
    progressLabelElement = null,
    panelElement = null,
  } = {},
  {
    label = '',
    currentStep = 0,
    totalSteps = OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
    state: progressState = 'busy',
    hidden = false,
  } = {},
) {
  if (!progressElement || !progressBarElement || !progressLabelElement) {
    return;
  }

  const safeTotalSteps = Math.max(1, Number(totalSteps) || 1);
  const safeCurrentStep = Math.max(
    0,
    Math.min(safeTotalSteps, Number(currentStep) || 0),
  );
  const percent = Math.round((safeCurrentStep / safeTotalSteps) * 100);
  // A finished run is 100% whatever step it stopped on, and the readout has to
  // agree with the bar — a terminal state with no step would otherwise announce
  // 0% under a full bar.
  const displayPercent =
    progressState === 'complete' || progressState === 'error' ? 100 : percent;
  const labelText = label
    ? `${label}${safeCurrentStep ? ` (${safeCurrentStep}/${safeTotalSteps})` : ''}`
    : '';

  progressElement.hidden = Boolean(hidden);
  progressElement.dataset.state = hidden ? 'idle' : progressState;
  if (panelElement) {
    panelElement.dataset.exportProgressVisible = hidden ? 'false' : 'true';
  }
  progressLabelElement.textContent = labelText;
  progressBarElement.style.width = `${displayPercent}%`;
  progressBarElement.setAttribute('aria-valuenow', String(displayPercent));
  progressBarElement.setAttribute('aria-valuetext', labelText || label || '');
  progressBarElement.classList.toggle(
    'progress-bar-striped',
    progressState === 'busy',
  );
  progressBarElement.classList.toggle(
    'progress-bar-animated',
    progressState === 'busy',
  );
}

function applyPreviewControllerExportCommonMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    setOpenLyricActionPending(this: any, nextPending) {
      this.isOpenLyricActionPending = Boolean(nextPending);

      this.syncOpenLyricActionAvailability();
    },

    syncOpenLyricActionAvailability(this: any) {
      const pluginAvailable = Boolean(state.openLyricPluginAvailable);

      [
        refs.copyOpenLyricTextBtn,
        refs.downloadOpenLyricImageBtn,
        refs.downloadOpenLyricPowerPointBtn,
        refs.printOpenLyricBtn,
      ].forEach((button) => {
        if (!button) {
          return;
        }

        button.disabled = !pluginAvailable || this.isOpenLyricActionPending;
        button.setAttribute(
          'aria-busy',
          String(pluginAvailable && this.isOpenLyricActionPending),
        );
      });

      if (!pluginAvailable) {
        this.closeOpenLyricOptionsMenu?.();
      }
    },

    syncOpenLyricClipboardActionAvailability(this: any) {
      if (!refs.copyOpenLyricTextBtn) {
        return;
      }

      refs.copyOpenLyricTextBtn.hidden =
        !state.openLyricPluginAvailable || !supportsClipboardCopy();
      this.syncOpenLyricActionAvailability();
    },

    clearOpenLyricProgressResetTimer(this: any) {
      if (!this.openLyricProgressResetTimer) {
        return;
      }

      globalThis.clearTimeout(this.openLyricProgressResetTimer);
      this.openLyricProgressResetTimer = 0;
    },

    updateOpenLyricProgress(
      this: any,
      {
        label = '',
        currentStep = 0,
        totalSteps = OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
        state: progressState = 'busy',
        hidden = false,
      } = {},
    ) {
      updatePreviewExportProgressElements(
        {
          progressElement: refs.openLyricExportProgress,
          progressBarElement: refs.openLyricExportProgressBar,
          progressLabelElement: refs.openLyricExportProgressLabel,
          panelElement: refs.openLyricPanel,
        },
        {
          label,
          currentStep,
          totalSteps,
          state: progressState,
          hidden,
        },
      );
    },

    resetOpenLyricProgress(this: any) {
      this.clearOpenLyricProgressResetTimer();
      this.updateOpenLyricProgress({
        label: '',
        currentStep: 0,
        state: 'idle',
        hidden: true,
      });
    },

    scheduleOpenLyricProgressReset(this: any, delayMs = 0) {
      this.clearOpenLyricProgressResetTimer();

      if (delayMs <= 0) {
        this.resetOpenLyricProgress();
        return;
      }

      this.openLyricProgressResetTimer = globalThis.setTimeout(() => {
        this.openLyricProgressResetTimer = 0;
        this.resetOpenLyricProgress();
      }, delayMs);
    },

    async announceOpenLyricProgress(this: any, label, currentStep) {
      this.updateOpenLyricProgress({
        label,
        currentStep,
        totalSteps: OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
        state: 'busy',
      });
      await this.waitForNextFrame();
    },

    clearMarkdownPreviewProgressResetTimer(this: any) {
      if (!this.markdownPreviewProgressResetTimer) {
        return;
      }

      globalThis.clearTimeout(this.markdownPreviewProgressResetTimer);
      this.markdownPreviewProgressResetTimer = 0;
    },

    updateMarkdownPreviewProgress(
      this: any,
      {
        label = '',
        currentStep = 0,
        totalSteps = OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
        state: progressState = 'busy',
        hidden = false,
      } = {},
    ) {
      updatePreviewExportProgressElements(
        {
          progressElement: refs.markdownPreviewExportProgress,
          progressBarElement: refs.markdownPreviewExportProgressBar,
          progressLabelElement: refs.markdownPreviewExportProgressLabel,
          panelElement: refs.previewPanel,
        },
        {
          label,
          currentStep,
          totalSteps,
          state: progressState,
          hidden,
        },
      );
    },

    resetMarkdownPreviewProgress(this: any) {
      this.clearMarkdownPreviewProgressResetTimer();
      this.updateMarkdownPreviewProgress({
        label: '',
        currentStep: 0,
        state: 'idle',
        hidden: true,
      });
    },

    scheduleMarkdownPreviewProgressReset(this: any, delayMs = 0) {
      this.clearMarkdownPreviewProgressResetTimer();

      if (delayMs <= 0) {
        this.resetMarkdownPreviewProgress();
        return;
      }

      this.markdownPreviewProgressResetTimer = globalThis.setTimeout(() => {
        this.markdownPreviewProgressResetTimer = 0;
        this.resetMarkdownPreviewProgress();
      }, delayMs);
    },

    async announceMarkdownPreviewProgress(this: any, label, currentStep) {
      this.updateMarkdownPreviewProgress({
        label,
        currentStep,
        totalSteps: OPEN_LYRIC_EXPORT_PROGRESS_TOTAL_STEPS,
        state: 'busy',
      });
      await this.waitForNextFrame();
    },

    getOpenLyricSurfaceBackgroundColor(this: any) {
      const panelBackgroundColor = refs.openLyricPanel
        ? globalThis.getComputedStyle(refs.openLyricPanel).backgroundColor
        : '';

      if (!isTransparentColor(panelBackgroundColor)) {
        return panelBackgroundColor;
      }

      const previewBackgroundColor = refs.openLyricPreview
        ? globalThis.getComputedStyle(refs.openLyricPreview).backgroundColor
        : '';

      if (!isTransparentColor(previewBackgroundColor)) {
        return previewBackgroundColor;
      }

      return getOpenLyricThemeSurface(document.documentElement.dataset.theme);
    },

    sanitizeOpenLyricExportName(this: any, value) {
      return String(value ?? '')
        .replace(/[<>:"/\\|?*\u0000-\u001f]/g, '-')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^[.-]+|[.-]+$/g, '')
        .trim();
    },

    getOpenLyricExportBaseName(this: any) {
      const sourceName = String(state.fileName || '')
        .replace(/\.(md|markdown)$/i, '')
        .trim();
      const sanitizedSourceName = this.sanitizeOpenLyricExportName(sourceName);
      const presentationTitle =
        this.getOpenLyricPresentationData()?.title || '';
      const sanitizedTitle =
        this.sanitizeOpenLyricExportName(presentationTitle);
      const genericSourceNames = new Set([
        'open-lyric',
        'shared-link',
        'untitled',
      ]);

      if (
        sanitizedTitle &&
        (!sanitizedSourceName || genericSourceNames.has(sanitizedSourceName))
      ) {
        return sanitizedTitle;
      }

      return sanitizedSourceName || sanitizedTitle || 'open-lyric';
    },

    getOpenLyricImageFileName(this: any) {
      return `${this.getOpenLyricExportBaseName()}-open-lyric.jpg`;
    },

    getOpenLyricPowerPointFileName(this: any) {
      return `${this.getOpenLyricExportBaseName()}-open-lyric.pptx`;
    },

    async waitForNextFrame(this: any) {
      await new Promise((resolve) => {
        if (typeof globalThis.requestAnimationFrame === 'function') {
          globalThis.requestAnimationFrame(() => {
            resolve(undefined);
          });
          return;
        }

        resolve(undefined);
      });
    },

    async waitForFonts(this: any, targetDocument = document) {
      const fontSet = targetDocument.fonts;

      if (!fontSet?.ready || typeof fontSet.ready.then !== 'function') {
        return;
      }

      try {
        await fontSet.ready;
      } catch (_error) {
        // Ignore font loading failures and continue with the best available render.
      }
    },

    canvasToBlob(this: any, canvas, type, quality) {
      return new Promise((resolve, reject) => {
        canvas.toBlob(
          (blob) => {
            if (blob) {
              resolve(blob);
              return;
            }

            reject(new Error('Unable to convert canvas to image.'));
          },
          type,
          quality,
        );
      });
    },

    downloadBlob(this: any, blob, fileName) {
      const objectUrl = URL.createObjectURL(blob);
      const link = document.createElement('a');

      link.href = objectUrl;
      link.download = fileName;
      link.click();

      globalThis.setTimeout(() => {
        URL.revokeObjectURL(objectUrl);
      }, 0);
    },

    async copyTextToClipboard(this: any, text) {
      if (!supportsClipboardCopy()) {
        throw new Error('Clipboard copy is unavailable.');
      }

      if (globalThis.navigator?.clipboard?.writeText) {
        await globalThis.navigator.clipboard.writeText(text);
        return;
      }

      const textarea = document.createElement('textarea');
      const activeElement =
        document.activeElement instanceof HTMLElement
          ? document.activeElement
          : null;

      textarea.value = text;
      textarea.setAttribute('readonly', '');
      textarea.style.position = 'fixed';
      textarea.style.left = '-100000px';
      textarea.style.top = '0';
      textarea.style.opacity = '0';

      document.body.appendChild(textarea);
      textarea.focus();
      textarea.select();

      try {
        if (
          typeof document.execCommand !== 'function' ||
          !document.execCommand('copy')
        ) {
          throw new Error('Copy command failed.');
        }
      } finally {
        textarea.remove();
        activeElement?.focus?.();
      }
    },

    async copyOpenLyricPreviewAsText(this: any) {
      const previewApi = getOpenLyricPreviewApi();

      if (this.isOpenLyricActionPending) {
        return;
      }

      if (
        !state.openLyricPluginAvailable ||
        typeof previewApi?.renderOpenLyricPlainText !== 'function'
      ) {
        setStatus('Open Lyric plugin is disabled');
        return;
      }

      if (!supportsClipboardCopy()) {
        setStatus('Clipboard copy is unavailable in this browser');
        return;
      }

      const text = previewApi.renderOpenLyricPlainText(this.getCurrentValue(), {
        hideBracketedKeys: Boolean(state.openLyricHideKeys),
        hideLeadingBars: Boolean(state.openLyricHideLeadingBars),
        simplifyChords: Boolean(state.openLyricSimplifyChords),
        selectedStructureKeys: getSelectedStructureKeys(),
      });

      if (!text) {
        setStatus('Nothing to copy from Open Lyric preview');
        return;
      }

      try {
        this.setOpenLyricActionPending(true);
        await this.copyTextToClipboard(text);
        setStatus('Open Lyric text copied');
      } catch (error) {
        console.error('Failed to copy Open Lyric preview as text.', error);
        setStatus('Failed to copy Open Lyric text');
      } finally {
        this.setOpenLyricActionPending(false);
      }
    },
  });
}

export { applyPreviewControllerExportCommonMethods };
