import { refs } from '../../shared.ts';
import { closeFloatingMenu, openFloatingMenu } from '../../floating-menu.ts';
import {
  ADD_SECTION_ACTION_ROOT_SELECTOR,
  CONFIG_ADD_ACTION_ROOT_SELECTOR,
  CONFIG_ATTACHMENT_ACTION_ROOT_SELECTOR,
  CONFIG_KEY_ACTION_ROOT_SELECTOR,
  CONFIG_LOCALE_ACTION_ROOT_SELECTOR,
  CONFIG_TEMPO_ACTION_ROOT_SELECTOR,
  CONFIG_TIME_ACTION_ROOT_SELECTOR,
  DECLARE_PART_ACTION_ROOT_SELECTOR,
  SECTION_DELETE_ACTION_ROOT_SELECTOR,
} from './constants.ts';

function applyPreviewControllerMenuMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    ensureDeclarePartPopup(this: any) {
      if (this.declarePartPopup) {
        return this.declarePartPopup;
      }

      const popup = document.createElement('div');
      popup.className = 'ol-preview-declare-part-popup';
      popup.setAttribute('role', 'menu');
      popup.setAttribute('aria-label', 'Choose part for Structure');
      popup.tabIndex = -1;
      popup.hidden = true;
      popup.addEventListener('click', this.handleDeclarePartPopupClick);
      document.body.appendChild(popup);
      this.declarePartPopup = popup;
      return popup;
    },

    isDeclarePartPopupElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(this.declarePartPopup?.contains(element))
      );
    },

    ensureConfigAddPopup(this: any) {
      if (this.configAddPopup) {
        return this.configAddPopup;
      }

      const popup = document.createElement('div');
      popup.className =
        'ol-preview-declare-part-popup ol-preview-config-add-popup';
      popup.setAttribute('role', 'menu');
      popup.setAttribute('aria-label', 'Add missing config field');
      popup.tabIndex = -1;
      popup.hidden = true;
      popup.addEventListener('click', this.handleConfigAddPopupClick);
      document.body.appendChild(popup);
      this.configAddPopup = popup;
      return popup;
    },

    isConfigAddPopupElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(this.configAddPopup?.contains(element))
      );
    },

    ensureConfigKeyPopup(this: any) {
      if (this.configKeyPopup) {
        return this.configKeyPopup;
      }

      const popup = document.createElement('div');
      popup.className =
        'ol-preview-declare-part-popup ol-preview-config-key-popup';
      popup.setAttribute('role', 'menu');
      popup.setAttribute('aria-label', 'Choose key');
      popup.tabIndex = -1;
      popup.hidden = true;
      popup.addEventListener('click', this.handleConfigKeyPopupClick);
      document.body.appendChild(popup);
      this.configKeyPopup = popup;
      return popup;
    },

    isConfigKeyPopupElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(this.configKeyPopup?.contains(element))
      );
    },

    ensureConfigAttachmentPopup(this: any) {
      if (this.configAttachmentPopup) {
        return this.configAttachmentPopup;
      }

      const popup = document.createElement('div');
      popup.className =
        'ol-preview-declare-part-popup ol-preview-config-attachment-popup';
      popup.setAttribute('role', 'dialog');
      popup.setAttribute('aria-label', 'Add attachment');
      popup.tabIndex = -1;
      popup.hidden = true;
      popup.addEventListener('input', this.handleConfigAttachmentPopupInput);
      popup.addEventListener('submit', this.handleConfigAttachmentPopupSubmit);
      document.body.appendChild(popup);
      this.configAttachmentPopup = popup;
      return popup;
    },

    isConfigAttachmentPopupElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(this.configAttachmentPopup?.contains(element))
      );
    },

    ensureConfigLocalePopup(this: any) {
      if (this.configLocalePopup) {
        return this.configLocalePopup;
      }

      const popup = document.createElement('div');
      popup.className =
        'ol-preview-declare-part-popup ol-preview-config-locale-popup';
      // A dialog, not a menu: the supported-locale list is long enough to need
      // the filter field the popup carries above its options.
      popup.setAttribute('role', 'dialog');
      popup.setAttribute('aria-label', 'Add locale');
      popup.tabIndex = -1;
      popup.hidden = true;
      popup.addEventListener('click', this.handleConfigLocalePopupClick);
      popup.addEventListener('input', this.handleConfigLocalePopupInput);
      popup.addEventListener('submit', this.handleConfigLocalePopupSubmit);
      document.body.appendChild(popup);
      this.configLocalePopup = popup;
      return popup;
    },

    isConfigLocalePopupElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(this.configLocalePopup?.contains(element))
      );
    },

    ensureConfigTimePopup(this: any) {
      if (this.configTimePopup) {
        return this.configTimePopup;
      }

      const popup = document.createElement('div');
      popup.className =
        'ol-preview-declare-part-popup ol-preview-config-time-popup';
      popup.setAttribute('role', 'menu');
      popup.setAttribute('aria-label', 'Choose time signature');
      popup.tabIndex = -1;
      popup.hidden = true;
      popup.addEventListener('click', this.handleConfigTimePopupClick);
      document.body.appendChild(popup);
      this.configTimePopup = popup;
      return popup;
    },

    isConfigTimePopupElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(this.configTimePopup?.contains(element))
      );
    },

    ensureConfigTempoPopup(this: any) {
      if (this.configTempoPopup) {
        return this.configTempoPopup;
      }

      const popup = document.createElement('div');
      popup.className =
        'ol-preview-declare-part-popup ol-preview-config-tempo-popup';
      popup.setAttribute('role', 'dialog');
      popup.setAttribute('aria-label', 'Choose tempo');
      popup.tabIndex = -1;
      popup.hidden = true;
      popup.addEventListener('input', this.handleConfigTempoPopupInput);
      popup.addEventListener('change', this.handleConfigTempoPopupChange);
      document.body.appendChild(popup);
      this.configTempoPopup = popup;
      return popup;
    },

    isConfigTempoPopupElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(this.configTempoPopup?.contains(element))
      );
    },

    isPreviewSettingsElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(refs.previewSettings?.contains(element))
      );
    },

    closePreviewSettingsMenu(this: any) {
      if (refs.previewSettings) {
        refs.previewSettings.dataset.open = 'false';
      }

      if (refs.previewSettingsBtn) {
        refs.previewSettingsBtn.setAttribute('aria-expanded', 'false');
      }

      if (refs.previewSettingsMenu) {
        closeFloatingMenu(refs.previewSettingsMenu);
        refs.previewSettingsMenu.hidden = true;
      }
    },

    openPreviewSettingsMenu(this: any) {
      if (!refs.previewSettingsBtn || !refs.previewSettingsMenu) {
        return;
      }

      this.syncPreviewSettingsControls();

      if (refs.previewSettings) {
        refs.previewSettings.dataset.open = 'true';
      }

      refs.previewSettingsBtn.setAttribute('aria-expanded', 'true');
      refs.previewSettingsMenu.hidden = false;
      // Along the tool row's right edge rather than the gear's — see the
      // `.preview-panel__floating-tool-actions` note in
      // `styles/_preview-panel-chrome.scss`.
      openFloatingMenu(
        refs.previewSettingsMenu,
        refs.previewSettingsBtn.closest(
          '.preview-panel__floating-tool-actions',
        ) || refs.previewSettingsBtn,
      );

      globalThis.queueMicrotask(() => {
        if (refs.previewFontSizeInput instanceof HTMLInputElement) {
          this.focusElement(refs.previewFontSizeInput, {
            preventScroll: true,
            skipTouchIosForButtons: true,
          });
        }
      });
    },

    isTopbarActionsElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(refs.topbarActions?.contains(element))
      );
    },

    isMarkdownPreviewOptionsElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(refs.markdownPreviewOptions?.contains(element))
      );
    },

    closeMarkdownPreviewOptionsMenu(this: any) {
      if (refs.markdownPreviewOptions) {
        refs.markdownPreviewOptions.dataset.open = 'false';
      }

      if (refs.markdownPreviewOptionsBtn) {
        refs.markdownPreviewOptionsBtn.setAttribute('aria-expanded', 'false');
      }

      if (refs.markdownPreviewOptionsMenu) {
        closeFloatingMenu(refs.markdownPreviewOptionsMenu);
        refs.markdownPreviewOptionsMenu.hidden = true;
      }
    },

    openMarkdownPreviewOptionsMenu(this: any) {
      if (!refs.markdownPreviewOptionsBtn || !refs.markdownPreviewOptionsMenu) {
        return;
      }

      this.syncMarkdownPreviewActionAvailability?.();
      this.syncMarkdownPreviewDocxFileNameInput?.();

      if (refs.markdownPreviewOptions) {
        refs.markdownPreviewOptions.dataset.open = 'true';
      }

      refs.markdownPreviewOptionsBtn.setAttribute('aria-expanded', 'true');
      refs.markdownPreviewOptionsMenu.hidden = false;
      openFloatingMenu(
        refs.markdownPreviewOptionsMenu,
        refs.markdownPreviewOptionsBtn,
      );
    },

    closeTopbarActionsMenu(this: any) {
      if (refs.topbarActions) {
        refs.topbarActions.dataset.open = 'false';
      }

      if (refs.topbarActionsBtn) {
        refs.topbarActionsBtn.setAttribute('aria-expanded', 'false');
      }

      if (refs.topbarActionsMenu) {
        closeFloatingMenu(refs.topbarActionsMenu);
        refs.topbarActionsMenu.hidden = true;
      }
    },

    openTopbarActionsMenu(this: any) {
      if (!refs.topbarActionsBtn || !refs.topbarActionsMenu) {
        return;
      }

      if (refs.topbarActions) {
        refs.topbarActions.dataset.open = 'true';
      }

      refs.topbarActionsBtn.setAttribute('aria-expanded', 'true');
      refs.topbarActionsMenu.hidden = false;
      openFloatingMenu(refs.topbarActionsMenu, refs.topbarActionsBtn, {
        align: 'start',
      });

      globalThis.queueMicrotask(() => {
        this.focusElement(refs.openBtn, {
          preventScroll: true,
          skipTouchIosForButtons: true,
        });
      });
    },

    closeDeclarePartMenus(this: any) {
      if (this.declarePartPopup) {
        this.declarePartPopup.hidden = true;
        this.declarePartPopup.replaceChildren();
        delete this.declarePartPopup.dataset.structureInsertIndex;
        this.declarePartPopup.style.left = '';
        this.declarePartPopup.style.top = '';
      }

      this.activeDeclarePartButton = null;

      if (this.configAddPopup) {
        this.configAddPopup.hidden = true;
        this.configAddPopup.replaceChildren();
        this.configAddPopup.style.left = '';
        this.configAddPopup.style.top = '';
      }

      this.activeConfigAddButton = null;

      if (this.configKeyPopup) {
        this.configKeyPopup.hidden = true;
        this.configKeyPopup.replaceChildren();
        this.configKeyPopup.style.left = '';
        this.configKeyPopup.style.top = '';
      }

      this.activeConfigKeyButton = null;

      if (this.configAttachmentPopup) {
        this.configAttachmentPopup.hidden = true;
        this.configAttachmentPopup.replaceChildren();
        this.configAttachmentPopup.style.left = '';
        this.configAttachmentPopup.style.top = '';
      }

      this.activeConfigAttachmentButton = null;

      if (this.configLocalePopup) {
        this.configLocalePopup.hidden = true;
        this.configLocalePopup.replaceChildren();
        this.configLocalePopup.style.left = '';
        this.configLocalePopup.style.top = '';
      }

      this.activeConfigLocaleButton = null;

      if (this.configTimePopup) {
        this.configTimePopup.hidden = true;
        this.configTimePopup.replaceChildren();
        this.configTimePopup.style.left = '';
        this.configTimePopup.style.top = '';
      }

      this.activeConfigTimeButton = null;

      if (this.configTempoPopup) {
        this.configTempoPopup.hidden = true;
        this.configTempoPopup.replaceChildren();
        this.configTempoPopup.style.left = '';
        this.configTempoPopup.style.top = '';
      }

      this.activeConfigTempoButton = null;

      // Owned by the OpenLyric plugin's `section-naming.ts`, and closed from
      // here so every "a menu is open" exit — an outside pointer-down, Escape,
      // a re-render — still closes exactly one set of popups.
      this.closeAddSectionPopup?.();
      this.closeDeleteSectionPopup?.();

      this.closePreviewSettingsMenu();
      this.closeTopbarActionsMenu();
      this.closeMarkdownPreviewOptionsMenu();

      [refs.preview, refs.openLyricPreview].forEach((container) => {
        container
          ?.querySelectorAll(DECLARE_PART_ACTION_ROOT_SELECTOR)
          .forEach((button) => {
            button.setAttribute('aria-expanded', 'false');
          });

        container
          ?.querySelectorAll(CONFIG_ADD_ACTION_ROOT_SELECTOR)
          .forEach((button) => {
            button.setAttribute('aria-expanded', 'false');
          });

        container
          ?.querySelectorAll(CONFIG_KEY_ACTION_ROOT_SELECTOR)
          .forEach((button) => {
            button.setAttribute('aria-expanded', 'false');
          });

        container
          ?.querySelectorAll(CONFIG_ATTACHMENT_ACTION_ROOT_SELECTOR)
          .forEach((button) => {
            button.setAttribute('aria-expanded', 'false');
          });

        container
          ?.querySelectorAll(CONFIG_LOCALE_ACTION_ROOT_SELECTOR)
          .forEach((button) => {
            button.setAttribute('aria-expanded', 'false');
          });

        container
          ?.querySelectorAll(CONFIG_TIME_ACTION_ROOT_SELECTOR)
          .forEach((button) => {
            button.setAttribute('aria-expanded', 'false');
          });

        container
          ?.querySelectorAll(CONFIG_TEMPO_ACTION_ROOT_SELECTOR)
          .forEach((button) => {
            button.setAttribute('aria-expanded', 'false');
          });
      });

      this.closeOpenLyricOptionsMenu();
    },

    handleDeclarePartViewportChange(this: any) {
      this.closeDeclarePartMenus();
    },

    handlePreviewSettingsToggleClick(this: any, event) {
      event.preventDefault();

      const wasExpanded =
        refs.previewSettingsBtn?.getAttribute('aria-expanded') === 'true' &&
        Boolean(refs.previewSettingsMenu && !refs.previewSettingsMenu.hidden);

      if (wasExpanded) {
        this.closePreviewSettingsMenu();
        return;
      }

      this.closeDeclarePartMenus();
      this.openPreviewSettingsMenu();
    },

    handlePreviewSettingsFocusOut(this: any, event) {
      const nextFocusTarget = event.relatedTarget;

      if (
        nextFocusTarget instanceof Node &&
        refs.previewSettings?.contains(nextFocusTarget)
      ) {
        return;
      }

      globalThis.queueMicrotask(() => {
        const activeElement = document.activeElement;

        if (
          activeElement instanceof Node &&
          refs.previewSettings?.contains(activeElement)
        ) {
          return;
        }

        this.closePreviewSettingsMenu();
      });
    },

    handleTopbarActionsToggleClick(this: any, event) {
      event.preventDefault();

      const wasExpanded =
        refs.topbarActionsBtn?.getAttribute('aria-expanded') === 'true' &&
        Boolean(refs.topbarActionsMenu && !refs.topbarActionsMenu.hidden);

      if (wasExpanded) {
        this.closeTopbarActionsMenu();
        return;
      }

      this.closeDeclarePartMenus();
      this.openTopbarActionsMenu();
    },

    handleTopbarActionsFocusOut(this: any, event) {
      const nextFocusTarget = event.relatedTarget;

      if (
        nextFocusTarget instanceof Node &&
        refs.topbarActions?.contains(nextFocusTarget)
      ) {
        return;
      }

      globalThis.queueMicrotask(() => {
        const activeElement = document.activeElement;

        if (
          activeElement instanceof Node &&
          refs.topbarActions?.contains(activeElement)
        ) {
          return;
        }

        this.closeTopbarActionsMenu();
      });
    },

    handleMarkdownPreviewOptionsToggleClick(this: any, event) {
      event.preventDefault();

      const wasExpanded =
        refs.markdownPreviewOptionsBtn?.getAttribute('aria-expanded') ===
          'true' &&
        Boolean(
          refs.markdownPreviewOptionsMenu &&
          !refs.markdownPreviewOptionsMenu.hidden,
        );

      if (wasExpanded) {
        this.closeMarkdownPreviewOptionsMenu();
        return;
      }

      this.closeDeclarePartMenus();
      this.openMarkdownPreviewOptionsMenu();
    },

    handleMarkdownPreviewOptionsFocusOut(this: any, event) {
      const nextFocusTarget = event.relatedTarget;

      if (
        nextFocusTarget instanceof Node &&
        refs.markdownPreviewOptions?.contains(nextFocusTarget)
      ) {
        return;
      }

      globalThis.queueMicrotask(() => {
        const activeElement = document.activeElement;

        if (
          activeElement instanceof Node &&
          refs.markdownPreviewOptions?.contains(activeElement)
        ) {
          return;
        }

        this.closeMarkdownPreviewOptionsMenu();
      });
    },

    handleMarkdownPreviewPrintClick(this: any) {
      this.closeMarkdownPreviewOptionsMenu();
      this.printMarkdownPreview();
    },

    handleMarkdownPreviewDocxDownloadClick(this: any) {
      this.closeMarkdownPreviewOptionsMenu();
      void this.downloadMarkdownPreviewAsDocx();
    },

    handleMarkdownDocClick(this: any) {
      this.closeMarkdownPreviewOptionsMenu();

      if (typeof globalThis.open !== 'function') {
        return;
      }

      globalThis.open(
        'https://www.markdownguide.org/',
        '_blank',
        'noopener,noreferrer',
      );
    },

    handleMarkdownPreviewImageDownloadClick(this: any) {
      this.closeMarkdownPreviewOptionsMenu();
      void this.downloadMarkdownPreviewAsJpeg();
    },

    handleTopbarActionsMenuClick(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);

      if (!eventTarget?.closest('.topbar-actions__action-btn')) {
        return;
      }

      this.closeTopbarActionsMenu();
    },

    handleDocumentPointerDown(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);

      if (
        eventTarget?.closest(DECLARE_PART_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_ADD_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_KEY_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_ATTACHMENT_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_LOCALE_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_TIME_ACTION_ROOT_SELECTOR) ||
        eventTarget?.closest(CONFIG_TEMPO_ACTION_ROOT_SELECTOR) ||
        this.isDeclarePartPopupElement(eventTarget) ||
        this.isConfigAddPopupElement(eventTarget) ||
        this.isConfigKeyPopupElement(eventTarget) ||
        this.isConfigAttachmentPopupElement(eventTarget) ||
        this.isConfigLocalePopupElement(eventTarget) ||
        this.isConfigTimePopupElement(eventTarget) ||
        this.isConfigTempoPopupElement(eventTarget) ||
        eventTarget?.closest(ADD_SECTION_ACTION_ROOT_SELECTOR) ||
        this.isAddSectionPopupElement?.(eventTarget) ||
        eventTarget?.closest(SECTION_DELETE_ACTION_ROOT_SELECTOR) ||
        this.isDeleteSectionPopupElement?.(eventTarget) ||
        this.isTopbarActionsElement(eventTarget) ||
        this.isMarkdownPreviewOptionsElement(eventTarget) ||
        this.isPreviewSettingsElement(eventTarget) ||
        this.isOpenLyricOptionsElement(eventTarget)
      ) {
        return;
      }

      this.closeDeclarePartMenus();
    },

    handleDocumentKeyDown(this: any, event) {
      if (event.key !== 'Escape') {
        return;
      }

      const shouldRestoreTopbarActionsFocus =
        refs.topbarActionsBtn?.getAttribute('aria-expanded') === 'true';
      const shouldRestoreMarkdownPreviewOptionsFocus =
        refs.markdownPreviewOptionsBtn?.getAttribute('aria-expanded') ===
        'true';
      const shouldRestorePreviewSettingsFocus =
        refs.previewSettingsBtn?.getAttribute('aria-expanded') === 'true';
      const shouldRestoreOpenLyricOptionsFocus =
        refs.openLyricOptionsBtn?.getAttribute('aria-expanded') === 'true';

      this.closeDeclarePartMenus();

      if (shouldRestoreTopbarActionsFocus) {
        this.focusElement(refs.topbarActionsBtn, { preventScroll: true });
        return;
      }

      if (shouldRestoreMarkdownPreviewOptionsFocus) {
        this.focusElement(refs.markdownPreviewOptionsBtn, {
          preventScroll: true,
        });
        return;
      }

      if (shouldRestorePreviewSettingsFocus) {
        this.focusElement(refs.previewSettingsBtn, { preventScroll: true });
        return;
      }

      if (shouldRestoreOpenLyricOptionsFocus) {
        this.focusElement(refs.openLyricOptionsBtn, { preventScroll: true });
      }
    },
  });
}

export { applyPreviewControllerMenuMethods };
