import { hideChordDiagramPopup } from '../../../../plugins/OpenLyric/chord-popup.ts';
import {
  createPreviewSegments,
  createStrummingPatternPreviewContextFromMarkdown,
  renderMarkdownPreview,
  renderMarkdownPreviewSegment,
} from '../../preview.ts';
import { refs, state } from '../../shared.ts';
import {
  DEFAULT_PREVIEW_TYPOGRAPHY,
  IOS_FAMILY_USER_AGENT_RE,
  IPADOS_DESKTOP_USER_AGENT_RE,
  MARKDOWN_PREVIEW_PATTERN_TARGET_ID_PREFIX,
  MAX_PREVIEW_FONT_SIZE_PX,
  MIN_PREVIEW_FONT_SIZE_PX,
} from './constants.ts';

function getSingleLinePreviewChangeLineNumber(contentChangeEvent) {
  if (contentChangeEvent?.isFlush) {
    return 0;
  }

  const changes = Array.isArray(contentChangeEvent?.changes)
    ? contentChangeEvent.changes
    : [];

  if (changes.length !== 1) {
    return 0;
  }

  const [change] = changes;
  const startLineNumber = Number(change?.range?.startLineNumber) || 0;
  const endLineNumber = Number(change?.range?.endLineNumber) || startLineNumber;
  const normalizedText = String(change?.text || '').replace(/\r\n?/g, '\n');

  if (
    !startLineNumber ||
    startLineNumber !== endLineNumber ||
    normalizedText.includes('\n')
  ) {
    return 0;
  }

  return startLineNumber;
}

function findLineRangeElement(
  container,
  selector,
  startAttribute,
  endAttribute,
  lineNumber,
) {
  if (!(container instanceof Element) || !lineNumber) {
    return null;
  }

  return (
    Array.from(container.querySelectorAll(selector)).find((element) => {
      const startLineNumber = Number(element.getAttribute(startAttribute) || 0);
      const endLineNumber = Number(element.getAttribute(endAttribute) || 0);

      return (
        startLineNumber > 0 &&
        endLineNumber >= startLineNumber &&
        lineNumber >= startLineNumber &&
        lineNumber <= endLineNumber
      );
    }) || null
  );
}

function replaceElementFromHtml(element, html) {
  if (!(element instanceof Element)) {
    return null;
  }

  if (!String(html || '').trim()) {
    element.remove();
    return null;
  }

  const template = document.createElement('template');
  template.innerHTML = String(html || '').trim();
  const nextElement = template.content.firstElementChild;

  if (!(nextElement instanceof Element)) {
    element.remove();
    return null;
  }

  element.replaceWith(nextElement);
  return nextElement;
}

function applyPreviewControllerSetupMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    getEventTargetElement(this: any, event) {
      if (event.target instanceof Element) {
        return event.target;
      }

      if (event.target instanceof Node) {
        return event.target.parentElement;
      }

      return null;
    },

    isLikelyIosOrIpadOsBrowser(this: any) {
      const userAgent = String(globalThis.navigator?.userAgent || '');
      const maxTouchPoints = Number(globalThis.navigator?.maxTouchPoints || 0);

      return (
        IOS_FAMILY_USER_AGENT_RE.test(userAgent) ||
        (IPADOS_DESKTOP_USER_AGENT_RE.test(userAgent) && maxTouchPoints > 1)
      );
    },

    isTextEntryFocusableElement(this: any, element) {
      if (element instanceof HTMLTextAreaElement) {
        return true;
      }

      if (element instanceof HTMLInputElement) {
        const inputType = String(element.type || 'text').toLowerCase();

        return [
          'text',
          'search',
          'url',
          'tel',
          'email',
          'password',
          'number',
        ].includes(inputType);
      }

      return (
        element instanceof HTMLElement && Boolean(element.isContentEditable)
      );
    },

    focusElement(
      this: any,
      element,
      { preventScroll = true, skipTouchIosForButtons = false } = {},
    ) {
      if (
        !(element instanceof HTMLElement) ||
        typeof element.focus !== 'function'
      ) {
        return;
      }

      if (
        skipTouchIosForButtons &&
        this.isLikelyIosOrIpadOsBrowser() &&
        !this.isTextEntryFocusableElement(element)
      ) {
        return;
      }

      try {
        if (preventScroll) {
          element.focus({ preventScroll: true });
          return;
        }

        element.focus();
      } catch (_error) {
        element.focus();
      }
    },

    normalizePreviewTypographyPreference(this: any, value) {
      if (
        typeof this.preferences?.normalizePreviewTypographyPreference ===
        'function'
      ) {
        return this.preferences.normalizePreviewTypographyPreference(value);
      }

      const normalizedValue = value && typeof value === 'object' ? value : {};
      const rawFontSize = Number.parseInt(
        String(
          normalizedValue.fontSizePx ??
            normalizedValue.fontSize ??
            DEFAULT_PREVIEW_TYPOGRAPHY.fontSizePx,
        ),
        10,
      );

      return {
        fontSizePx: Math.min(
          MAX_PREVIEW_FONT_SIZE_PX,
          Math.max(
            MIN_PREVIEW_FONT_SIZE_PX,
            Number.isFinite(rawFontSize)
              ? Math.round(rawFontSize)
              : DEFAULT_PREVIEW_TYPOGRAPHY.fontSizePx,
          ),
        ),
        fontFamily:
          typeof normalizedValue.fontFamily === 'string'
            ? normalizedValue.fontFamily.trim()
            : DEFAULT_PREVIEW_TYPOGRAPHY.fontFamily,
      };
    },

    initializePreferenceState(this: any) {
      const savedPreference =
        this.preferences?.loadPreviewTypographyPreference?.() ??
        DEFAULT_PREVIEW_TYPOGRAPHY;

      this.setPreviewTypographyPreference(savedPreference, {
        save: false,
      });
      this.syncOpenLyricClipboardActionAvailability();
      this.syncMarkdownPreviewActionAvailability?.();
    },

    /**
     * Write one panel's font size/family onto its preview container. Each
     * preview owns its own typography — mirroring the standalone components,
     * which each carry their own fonts.
     */
    applyPreviewTypographyTo(this: any, container, typography) {
      if (!container) {
        return;
      }

      const fontFamily = String(typography?.fontFamily ?? '').trim();
      container.style.fontSize = `${typography.fontSizePx}px`;

      if (fontFamily) {
        container.style.fontFamily = fontFamily;
        return;
      }

      container.style.removeProperty('font-family');
    },

    /**
     * The fallback typography path, for a page with no `OpenLyric` component on
     * the lyric panel.
     *
     * An attached component owns that panel's fonts: its typography slot is the
     * popup's font-size slider and font-face picker, and it writes the size and
     * `--ol-font-family` onto the very same element. Two writers on one surface
     * fight — this one would clobber the reader's persisted face back to the
     * app's default on every boot — so where a component is attached, the app
     * only re-balances the sections its own layout owns.
     */
    applyPreviewTypographyPreference(this: any) {
      if (!this.openLyricPreviewComponent) {
        this.applyPreviewTypographyTo(
          refs.openLyricPreview,
          this.previewTypography,
        );
      }

      // Font size/family changes shift lyric line widths, so re-balance the
      // Open Lyric section blocks (spanning may now be needed or no longer be).
      this.applyOpenLyricSectionSpans?.();
    },

    /**
     * "Show comments" lives on the mounted `OpenLyricMarkdownManager` — its
     * settings popup is the component's, in adopt mode as much as standalone —
     * so it is read back off the component here rather than mirrored into
     * `state`. That keeps the app's own render paths (the incremental
     * single-segment patch, and the fallback for a page with no component) on
     * the same value the component renders with.
     */
    getMarkdownPreviewRenderOptions(this: any, markdown) {
      return {
        patternPreviewTargetIdPrefix: MARKDOWN_PREVIEW_PATTERN_TARGET_ID_PREFIX,
        patternPreviewContext:
          createStrummingPatternPreviewContextFromMarkdown(markdown),
        showComments: Boolean(
          this.markdownPreviewComponent?.isShowingCommentText,
        ),
        // The app always has a document behind this panel, so a blank one
        // offers "Start a new song" (see song-starting.ts).
        showEmptyDocumentStart: true,
      };
    },

    /**
     * The lyric popup's own fields. Typography is not among them: the mounted
     * `OpenLyric` component fills that popup’s typography mount with its own
     * slider and font picker, and keeps them in sync off `typography-change`.
     */
    syncPreviewSettingsControls(this: any) {
      this.syncPreviewStructureControls();
      this.syncOpenLyricPluginControls();
      this.syncOpenLyricClipboardActionAvailability?.();
    },

    setPreviewTypographyPreference(this: any, value, { save = true } = {}) {
      this.previewTypography = this.normalizePreviewTypographyPreference(value);
      this.applyPreviewTypographyPreference();
      this.syncPreviewSettingsControls();

      if (!save) {
        return;
      }

      this.preferences?.savePreviewTypographyPreference?.(
        this.previewTypography,
      );
    },

    bindEvents(this: any) {
      this.syncPreviewSectionEditingAvailability?.();
      this.bindPreviewHistoryEvents?.();
      refs.preview?.addEventListener('change', this.handlePreviewChange);
      refs.preview?.addEventListener('click', this.handlePreviewClick);
      refs.preview?.addEventListener('dblclick', this.handlePreviewDoubleClick);
      refs.preview?.addEventListener(
        'scroll',
        this.handleDeclarePartViewportChange,
        {
          passive: true,
        },
      );
      refs.openLyricPreview?.addEventListener(
        'change',
        this.handlePreviewChange,
      );
      refs.openLyricPreview?.addEventListener('click', this.handlePreviewClick);
      refs.openLyricPreview?.addEventListener(
        'dblclick',
        this.handlePreviewDoubleClick,
      );
      refs.openLyricPreview?.addEventListener(
        'scroll',
        this.handleDeclarePartViewportChange,
        { passive: true },
      );
      refs.previewSettingsBtn?.addEventListener(
        'click',
        this.handlePreviewSettingsToggleClick,
      );
      refs.previewSettings?.addEventListener(
        'focusout',
        this.handlePreviewSettingsFocusOut,
      );
      refs.previewStructureKeyPreviousBtn?.addEventListener(
        'click',
        this.handlePreviewStructureKeyStepClick,
      );
      refs.previewStructureKeySelect?.addEventListener(
        'change',
        this.handlePreviewStructureKeyChange,
      );
      refs.previewStructureKeyNextBtn?.addEventListener(
        'click',
        this.handlePreviewStructureKeyStepClick,
      );
      refs.previewOpenLyricShowCommentsToggle?.addEventListener(
        'change',
        this.handlePreviewOpenLyricShowCommentsChange,
      );
      refs.previewOpenLyricSimplifyBtn?.addEventListener(
        'click',
        this.handlePreviewOpenLyricToggleClick,
      );
      refs.previewOpenLyricHideBarsBtn?.addEventListener(
        'click',
        this.handlePreviewOpenLyricToggleClick,
      );
      refs.previewOpenLyricHideKeysBtn?.addEventListener(
        'click',
        this.handlePreviewOpenLyricToggleClick,
      );
      refs.resetPreviewTypographyBtn?.addEventListener(
        'click',
        this.handlePreviewTypographyResetClick,
      );
      refs.topbarActionsBtn?.addEventListener(
        'click',
        this.handleTopbarActionsToggleClick,
      );
      refs.topbarActions?.addEventListener(
        'focusout',
        this.handleTopbarActionsFocusOut,
      );
      refs.topbarActionsMenu?.addEventListener(
        'click',
        this.handleTopbarActionsMenuClick,
      );
      refs.markdownPreviewOptionsBtn?.addEventListener(
        'click',
        this.handleMarkdownPreviewOptionsToggleClick,
      );
      refs.markdownPreviewOptions?.addEventListener(
        'focusout',
        this.handleMarkdownPreviewOptionsFocusOut,
      );
      refs.downloadMarkdownPreviewImageBtn?.addEventListener(
        'click',
        this.handleMarkdownPreviewImageDownloadClick,
      );
      refs.downloadMarkdownPreviewDocxBtn?.addEventListener(
        'click',
        this.handleMarkdownPreviewDocxDownloadClick,
      );
      refs.goToMarkdownDocBtn?.addEventListener(
        'click',
        this.handleMarkdownDocClick,
      );
      refs.printMarkdownPreviewBtn?.addEventListener(
        'click',
        this.handleMarkdownPreviewPrintClick,
      );
      refs.openLyricOptionsBtn?.addEventListener(
        'click',
        this.handleOpenLyricOptionsToggleClick,
      );
      refs.openLyricOptions?.addEventListener(
        'focusout',
        this.handleOpenLyricOptionsFocusOut,
      );
      refs.copyOpenLyricTextBtn?.addEventListener(
        'click',
        this.handleOpenLyricTextCopyClick,
      );
      refs.downloadOpenLyricImageBtn?.addEventListener(
        'click',
        this.handleOpenLyricImageDownloadClick,
      );
      refs.downloadOpenLyricPowerPointBtn?.addEventListener(
        'click',
        this.handleOpenLyricPowerPointDownloadClick,
      );
      refs.printOpenLyricBtn?.addEventListener(
        'click',
        this.handleOpenLyricPrintClick,
      );
      document.addEventListener('pointerdown', this.handleDocumentPointerDown);
      document.addEventListener('keydown', this.handleDocumentKeyDown);
      window.addEventListener('resize', this.handleDeclarePartViewportChange);
      this.wireChordPopupEvents(refs.preview);
      this.wireChordPopupEvents(refs.openLyricPreview);
    },

    handlePanelVisibilityChange(this: any, panelVisibility) {
      const nextPreviewVisible = Boolean(panelVisibility?.previewVisible);
      const nextOpenLyricVisible = Boolean(panelVisibility?.openLyricVisible);

      if (nextPreviewVisible && !this.lastPanelVisibility.previewVisible) {
        this.renderPreview(this.getCurrentValue());
      }

      if (nextOpenLyricVisible && !this.lastPanelVisibility.openLyricVisible) {
        this.renderOpenLyric(this.getCurrentValue());
      }

      if (
        (nextPreviewVisible && !this.lastPanelVisibility.previewVisible) ||
        (nextOpenLyricVisible && !this.lastPanelVisibility.openLyricVisible)
      ) {
        this.schedulePendingConfigFieldActivation();
      }

      this.lastPanelVisibility = {
        openLyricVisible: nextOpenLyricVisible,
        previewVisible: nextPreviewVisible,
      };
    },

    renderPreviewIncrementally(this: any, markdown, contentChangeEvent = null) {
      if (!(refs.preview instanceof Element)) {
        return false;
      }

      const targetLineNumber =
        getSingleLinePreviewChangeLineNumber(contentChangeEvent);

      if (!targetLineNumber) {
        return false;
      }

      // Emptying the document swaps the panel for the "Start a new song" card,
      // which is not a segment the fast path can patch in.
      if (!String(markdown ?? '').trim()) {
        return false;
      }

      const targetSegment = createPreviewSegments(markdown).find((segment) => {
        return (
          targetLineNumber >= segment.startLineNumber &&
          targetLineNumber <= segment.endLineNumber
        );
      });

      if (!targetSegment) {
        return false;
      }

      const currentSegmentElement = findLineRangeElement(
        refs.preview,
        '.ol-preview-segment',
        'data-preview-segment-start-line',
        'data-preview-segment-end-line',
        targetLineNumber,
      );

      if (!(currentSegmentElement instanceof Element)) {
        return false;
      }

      replaceElementFromHtml(
        currentSegmentElement,
        renderMarkdownPreviewSegment(
          targetSegment,
          this.getMarkdownPreviewRenderOptions(markdown),
        ),
      );

      return true;
    },

    /**
     * Attach standalone preview components (`OpenLyricMarkdownManager`,
     * `OpenLyric`) mounted in adopt mode on the panel containers. When
     * attached, full re-renders flow through the components (their pure
     * render functions are the same ones used here); the incremental
     * single-line paths and all panel interactivity stay app-side.
     *
     * The lyric component also owns that panel's typography now, so follow its
     * `typography-change`: a new font size or face shifts lyric line widths, and
     * the section spanning this controller lays out has to be re-balanced for it
     * — the same re-balance the app-side controls used to trigger themselves.
     */
    attachPreviewComponents(this: any, components) {
      for (const off of this.previewComponentUnsubscribes ?? []) {
        off();
      }
      this.previewComponentUnsubscribes = [];

      this.markdownPreviewComponent = components?.markdownManager || null;
      this.openLyricPreviewComponent = components?.openLyric || null;

      const off = this.openLyricPreviewComponent?.on?.(
        'typography-change',
        () => this.applyOpenLyricSectionSpans?.(),
      );
      if (typeof off === 'function') {
        this.previewComponentUnsubscribes.push(off);
      }

      // The markdown popup's "Show comments" is the component's control, but
      // the app has to re-render the panel for it: the render context the app
      // hands the component (`extraRenderOptions`) is applied OVER the
      // component's own options, so the copy stored from the last app render
      // would keep overriding the flag the reader just changed.
      const offMarkdownDisplay = this.markdownPreviewComponent?.on?.(
        'display-change',
        () => this.renderPreview(this.getCurrentValue()),
      );
      if (typeof offMarkdownDisplay === 'function') {
        this.previewComponentUnsubscribes.push(offMarkdownDisplay);
      }
    },

    renderPreview(this: any, markdown, contentChangeEvent = null) {
      if (!refs.preview) {
        return;
      }

      if (this.renderPreviewIncrementally(markdown, contentChangeEvent)) {
        // The fast path patched the DOM itself, so the attached component
        // never saw this value. Hand it over — document-driven state (the
        // locale-matched plugin font) must follow a `- Locales:` edit even
        // when no full re-render happens.
        this.markdownPreviewComponent?.syncRenderedValue?.(markdown);
        this.syncMarkdownPreviewActionAvailability?.();
        this.syncPreviewSectionEditingAvailability?.();
        this.syncPreviewSectionEditorState?.();
        this.syncPreviewConfigTextEditorState?.();
        this.syncPreviewSectionRenameEditorState?.();
        this.syncPreviewHistoryControls?.();
        return;
      }

      const markdownComponent = this.markdownPreviewComponent;

      if (markdownComponent?.isMounted) {
        markdownComponent.extraRenderOptions =
          this.getMarkdownPreviewRenderOptions(markdown);

        if (markdownComponent.value !== markdown) {
          markdownComponent.value = markdown;
        } else {
          markdownComponent.reload();
        }
      } else {
        refs.preview.innerHTML = renderMarkdownPreview(
          markdown,
          this.getMarkdownPreviewRenderOptions(markdown),
        );
      }

      this.syncMarkdownPreviewActionAvailability?.();
      // The section pencils are rendered by the fence markup but only shown on
      // a panel that has a document surface to write back to, and a re-render
      // has just replaced whatever markup an open section editor lived in.
      this.syncPreviewSectionEditingAvailability?.();
      this.syncPreviewSectionEditorState?.();
      this.syncPreviewSectionRenameEditorState?.();
      this.syncPreviewConfigTextEditorState?.();
      // After the editor-state syncs: an undo that re-rendered away an open
      // form must not leave the history buttons standing down for it.
      this.syncPreviewHistoryControls?.();
    },

    renderPanels(this: any, markdown, contentChangeEvent = null) {
      hideChordDiagramPopup();
      this.closeDeclarePartMenus();
      this.renderPreview(markdown, contentChangeEvent);
      this.renderOpenLyric(markdown, contentChangeEvent);
      this.lastPanelVisibility = {
        openLyricVisible: Boolean(state.openLyricVisible),
        previewVisible: Boolean(state.previewVisible),
      };
      this.schedulePendingConfigFieldActivation();
    },

    schedulePendingConfigFieldActivation(this: any) {
      if (!this.pendingConfigFieldActivation) {
        return;
      }

      if (
        this.pendingConfigFieldActivationFrame &&
        typeof globalThis.cancelAnimationFrame === 'function'
      ) {
        globalThis.cancelAnimationFrame(this.pendingConfigFieldActivationFrame);
        this.pendingConfigFieldActivationFrame = 0;
      }

      if (typeof globalThis.requestAnimationFrame !== 'function') {
        this.activatePendingConfigField();
        return;
      }

      this.pendingConfigFieldActivationFrame = globalThis.requestAnimationFrame(
        () => {
          this.pendingConfigFieldActivationFrame = 0;
          this.activatePendingConfigField();
        },
      );
    },

    activatePendingConfigField(this: any) {
      const fieldName = this.pendingConfigFieldActivation;

      this.pendingConfigFieldActivation = '';

      if (!fieldName || !refs.preview) {
        return;
      }

      if (fieldName === 'Key') {
        const triggerButton = refs.preview.querySelector(
          '[data-preview-action="toggle-config-key-menu"][data-config-field="Key"]',
        );

        if (triggerButton instanceof HTMLButtonElement) {
          hideChordDiagramPopup();
          this.showConfigKeyPopup(triggerButton);
        }

        return;
      }

      if (fieldName === 'Time') {
        const triggerButton = refs.preview.querySelector(
          '[data-preview-action="toggle-config-time-menu"][data-config-field="Time"]',
        );

        if (triggerButton instanceof HTMLButtonElement) {
          this.showConfigTimePopup(triggerButton);
        }

        return;
      }

      if (fieldName === 'Tempo') {
        const triggerButton = refs.preview.querySelector(
          '[data-preview-action="toggle-config-tempo-menu"][data-config-field="Tempo"]',
        );

        if (triggerButton instanceof HTMLButtonElement) {
          this.showConfigTempoPopup(triggerButton);
        }

        return;
      }

      if (fieldName === 'Locales') {
        const triggerButton = refs.preview.querySelector(
          '[data-preview-action="toggle-config-locale-menu"][data-config-field="Locales"]',
        );

        if (triggerButton instanceof HTMLButtonElement) {
          this.showConfigLocalePopup(triggerButton);
        }
      }
    },
  });
}

export { applyPreviewControllerSetupMethods };
