import { OpenLyricEventEmitter } from './EventEmitter.ts';
import { PluginHost, type PluginHostContext } from './PluginHost.ts';
import {
  applyThemeSurfaceStyles,
  assertOpenLyricTheme,
  getOpenLyricThemeBase,
} from './theme.ts';
import {
  type OpenLyricChangeListener,
  type OpenLyricComponentHost,
  type OpenLyricComponentOptions,
  type OpenLyricEventHandler,
  type OpenLyricEventName,
  type OpenLyricLifecycleState,
  type OpenLyricPlugin,
  type OpenLyricRendererTargetSpec,
  type OpenLyricSurface,
  type OpenLyricTheme,
  type Unsubscribe,
} from './types.ts';

const DEFAULT_THEME: OpenLyricTheme = 'dark';

/**
 * Shared lifecycle base for every Open Lyric component.
 *
 * It owns the `created → mounted ⇄ unmounted → destroyed` state machine, the
 * unified `on()` event surface, the per-instance plugin host, and the theme
 * marker. It holds **no** global state and touches the DOM only from `mount()`
 * onward, satisfying the redesign's embedding rules (no globals, SSR-safe
 * construction, complete teardown).
 *
 * Concrete components (previews now; editor/dashboard later) override the
 * protected `handle*` hooks; they never re-implement the state machine.
 */
export abstract class OpenLyricComponent implements OpenLyricComponentHost {
  /** Which contribution surface this component represents. */
  abstract readonly surface: OpenLyricSurface;

  protected readonly emitter = new OpenLyricEventEmitter();
  protected readonly pluginHost: PluginHost;

  private lifecycleState: OpenLyricLifecycleState = 'created';
  /** Bumped by mount/unmount/destroy so an in-flight async mount can detect
   * that it was superseded and clean up after itself. */
  private mountGeneration = 0;
  private containerElement: HTMLElement | null = null;
  private themeValue: OpenLyricTheme = DEFAULT_THEME;
  private readonly changeListenerUnsubscribes = new Map<
    OpenLyricChangeListener,
    Unsubscribe
  >();

  constructor(options: OpenLyricComponentOptions = {}) {
    // SSR-safe: read options only; never touch the DOM here.
    if (options.container) {
      this.containerElement = options.container;
    }
    if (options.theme !== undefined) {
      assertOpenLyricTheme(options.theme);
      this.themeValue = options.theme;
    }

    // `surface` is an abstract field the subclass initializes *after* super(),
    // so every read of it is deferred (arrow) until it is set.
    const context: PluginHostContext = {
      getSurface: () => this.surface,
      host: this,
      getContainer: () => this.containerElement,
      getStyleHost: () => this.getPluginStyleHost(),
      isMounted: () => this.lifecycleState === 'mounted',
      emitPluginChange: (type, id) =>
        this.emitter.emit('plugin-change', { type, id }),
      resolveRendererTarget: (target) => this.resolveRendererTarget(target),
      requestRender: () => this.handlePluginRenderRequest(),
    };
    this.pluginHost = new PluginHost(context);
  }

  /* ----------------------------- properties ------------------------------ */

  get container(): HTMLElement | null {
    return this.containerElement;
  }

  /**
   * Reassigning the container is a **detach**: the component unmounts itself
   * from the old one first, so `handleUnmount()` and the theme-marker removal
   * still find their target and the host's element is handed back exactly as
   * it was given. Remounting stays the caller's move — `mount()` is async and
   * must not happen implicitly from a setter.
   */
  set container(next: HTMLElement | null) {
    this.assertNotDestroyed();
    const nextContainer = next ?? null;
    if (nextContainer === this.containerElement) {
      return;
    }
    this.unmount();
    // `unmount()` bails out mid-mount (the state is still `created` while
    // `mount()` awaits), so supersede the generation here too: an in-flight
    // mount must tear itself down rather than settle into a `mounted` state
    // pointing at a container we have already replaced.
    this.mountGeneration += 1;
    this.containerElement = nextContainer;
  }

  get theme(): OpenLyricTheme {
    return this.themeValue;
  }

  set theme(next: OpenLyricTheme) {
    this.assertNotDestroyed();
    assertOpenLyricTheme(next);
    if (next === this.themeValue) {
      return;
    }
    this.themeValue = next;

    if (this.lifecycleState === 'mounted') {
      this.applyThemeMarker();
    }
    // The subclass hook (e.g. editor-bridge sync) needs no DOM, so it runs
    // regardless of mount state.
    this.handleThemeChange(next);
    this.pluginHost.handleThemeChange(next);
    this.emitter.emit('theme-change', { theme: next });
  }

  get state(): OpenLyricLifecycleState {
    return this.lifecycleState;
  }

  get isMounted(): boolean {
    return this.lifecycleState === 'mounted';
  }

  get isDestroyed(): boolean {
    return this.lifecycleState === 'destroyed';
  }

  /* ------------------------------- events -------------------------------- */

  on<E extends OpenLyricEventName>(
    event: E,
    handler: OpenLyricEventHandler<E>,
  ): Unsubscribe {
    return this.emitter.on(event, handler);
  }

  /** Back-compat alias for `on('change', …)`; returns an unsubscribe fn. */
  addOnChangeEventListener(listener: OpenLyricChangeListener): Unsubscribe {
    if (typeof listener !== 'function') {
      return () => {};
    }
    const off = this.emitter.on('change', ({ oldValue, newValue }) =>
      listener(oldValue, newValue),
    );
    const unsubscribe: Unsubscribe = () => {
      off();
      this.changeListenerUnsubscribes.delete(listener);
    };
    this.changeListenerUnsubscribes.set(listener, unsubscribe);
    return unsubscribe;
  }

  removeOnChangeEventListener(listener: OpenLyricChangeListener): void {
    this.changeListenerUnsubscribes.get(listener)?.();
  }

  /* ------------------------------- plugins ------------------------------- */

  addPlugin(id: string, plugin: OpenLyricPlugin): void {
    this.assertNotDestroyed();
    this.pluginHost.add(id, plugin);
  }

  removePlugin(id: string): void {
    this.pluginHost.remove(id);
  }

  hasPlugin(id: string): boolean {
    return this.pluginHost.has(id);
  }

  /** Every attached plugin's contribution for one kind (e.g. `language`). */
  pluginContributions<T = unknown>(kind: string): T[] {
    return this.pluginHost.collectContributions<T>(kind);
  }

  /* ------------------------------ lifecycle ------------------------------ */

  async mount(): Promise<void> {
    this.assertNotDestroyed();
    if (this.lifecycleState === 'mounted') {
      return;
    }
    const container = this.containerElement;
    if (!container) {
      throw new Error('mount() requires a container; set `container` first.');
    }

    const generation = ++this.mountGeneration;
    this.applyThemeMarker();
    await this.handleMount(container);

    // `mount()` is async, so an unmount()/destroy() can land while we await.
    // If it did, undo the partial mount instead of resurrecting a dead
    // component (which would also leak whatever handleMount just built).
    if (generation !== this.mountGeneration) {
      this.handleUnmount();
      this.removeThemeMarker(container);
      return;
    }

    // handleMount just created the owned root; style it from the preset.
    this.applyThemeMarker();
    this.lifecycleState = 'mounted';
    this.pluginHost.handleMount();
    this.emitter.emit('ready', {});
  }

  unmount(): void {
    if (this.lifecycleState !== 'mounted') {
      return;
    }
    this.mountGeneration += 1;
    this.pluginHost.handleUnmount();
    this.handleUnmount();
    this.removeThemeMarker();
    this.lifecycleState = 'unmounted';
  }

  reload(): void {
    if (this.lifecycleState !== 'mounted') {
      return;
    }
    this.handleReload();
  }

  destroy(): void {
    if (this.lifecycleState === 'destroyed') {
      return;
    }
    const container = this.containerElement;
    // Detach before tearing down: clearing the container unmounts (see the
    // setter), so teardown proper always starts from an unmounted component
    // whose host element has already been handed back clean.
    this.container = null;
    // Supersede any in-flight mount() so it tears itself down when it settles.
    // The setter above already did this whenever there *was* a container; this
    // covers `destroy()` on a component that never had one.
    this.mountGeneration += 1;
    this.pluginHost.destroyAll();
    this.handleDestroy();
    this.removeThemeMarker(container);
    this.lifecycleState = 'destroyed';
    this.emitter.emit('destroy', {});
    this.emitter.clear();
    this.changeListenerUnsubscribes.clear();
  }

  /* ----------------------- hooks for subclasses -------------------------- */

  /** Build the DOM inside `container` and start the runtime. */
  protected handleMount(_container: HTMLElement): void | Promise<void> {}

  /** Remove DOM and detach listeners, keeping the instance reusable. */
  protected handleUnmount(): void {}

  /** Re-render from current value/options without a teardown. */
  protected handleReload(): void {}

  /** Final, permanent cleanup (bridge detach, owned children, object URLs). */
  protected handleDestroy(): void {}

  /** React to a theme change while mounted (e.g. re-render). */
  protected handleThemeChange(_theme: OpenLyricTheme): void {}

  /**
   * The element this component created inside `container` (render root,
   * editor surface). Theme preset styles are applied here — never to the
   * host's container — so teardown leaves the container pristine.
   */
  protected getOwnedRoot(): HTMLElement | null {
    return null;
  }

  /**
   * Map a `renderers` contribution target to this surface's rendered DOM.
   * Surfaces without renderer hooks return null (the target is skipped).
   */
  protected resolveRendererTarget(
    _target: string,
  ): OpenLyricRendererTargetSpec | null {
    return null;
  }

  /** A plugin with renderer contributions attached/detached: re-render. */
  protected handlePluginRenderRequest(): void {}

  /** Where plugin `style` contributions are installed (see PluginHost). */
  protected getPluginStyleHost(): HTMLElement | null {
    return this.containerElement;
  }

  /* ------------------------------ internals ------------------------------ */

  protected applyThemeMarker(): void {
    const container = this.containerElement;
    if (!container) {
      return;
    }
    container.setAttribute('data-ol-theme', this.themeValue);
    // The two marker classes are the light/dark BASE, not the theme name: they
    // exist for hosts that only need to know which way round the contrast runs,
    // and a `-bs` theme is still one or the other. The exact palette is on the
    // `data-ol-theme` attribute above.
    const themeBase = getOpenLyricThemeBase(this.themeValue);
    container.classList.toggle('ol-theme--dark', themeBase === 'dark');
    container.classList.toggle('ol-theme--light', themeBase === 'light');

    const ownedRoot = this.getOwnedRoot();
    if (ownedRoot) {
      applyThemeSurfaceStyles(ownedRoot, this.themeValue);
    }
  }

  /**
   * Reverse {@link applyThemeMarker} so a host's container is left exactly as
   * it was handed over. Idempotent; takes an explicit target because
   * `destroy()` clears the container reference.
   */
  protected removeThemeMarker(
    target: HTMLElement | null = this.containerElement,
  ): void {
    if (!target) {
      return;
    }
    target.removeAttribute('data-ol-theme');
    target.classList.remove('ol-theme--dark', 'ol-theme--light');
  }

  protected assertNotDestroyed(): void {
    if (this.lifecycleState === 'destroyed') {
      throw new Error(
        'This component has been destroyed and cannot be reused.',
      );
    }
  }
}
