import type {
  OpenLyricComponentHost,
  OpenLyricSettingsContribution,
  Unsubscribe,
} from './types.ts';

/**
 * The marker a plugin puts on every element it adds to a live preview (a play
 * button, a badge). The standalone chromes' image and print exports copy the
 * live markup, and drop whatever carries it — see {@link readExportMarkup}.
 */
export const PLUGIN_UI_ATTRIBUTE = 'data-ol-plugin-ui';

/**
 * The live render root's markup for an export, without the elements plugins
 * added to it. Returns the markup untouched (and uncloned) when there are none.
 */
export function readExportMarkup(root: HTMLElement | null | undefined): string {
  if (!root) {
    return '';
  }
  if (!root.querySelector(`[${PLUGIN_UI_ATTRIBUTE}]`)) {
    return root.innerHTML.trim();
  }
  const copy = root.cloneNode(true) as HTMLElement;
  for (const node of Array.from(
    copy.querySelectorAll(`[${PLUGIN_UI_ATTRIBUTE}]`),
  )) {
    node.remove();
  }
  return copy.innerHTML.trim();
}

/** The component view the settings fields need: its plugins' contributions. */
interface SettingsContributionHost extends OpenLyricComponentHost {
  pluginContributions<T = unknown>(kind: string): T[];
}

interface RenderedField {
  mount: HTMLElement;
  teardown: (() => void) | null;
}

function isSettingsContribution(
  entry: unknown,
): entry is OpenLyricSettingsContribution {
  return (
    Boolean(entry) &&
    typeof (entry as OpenLyricSettingsContribution).render === 'function'
  );
}

/**
 * The fields attached plugins contribute to a preview's settings popup
 * (`contributes.settings`), placed before `anchor` — the popup's Reset row —
 * or, in a popup without one, at the end of `fallbackParent`.
 *
 * Re-rendered whenever a plugin is added or removed, so the popup always lists
 * exactly what the current composition contributes. With no such plugin it
 * adds nothing, and the popup is exactly the built-in one.
 */
export class PluginSettingsFields {
  private readonly component: SettingsContributionHost;
  private anchor: Element | null;
  private fallbackParent: Element | null;
  private fields: RenderedField[] = [];
  private offPluginChange: Unsubscribe | null;

  constructor(
    component: SettingsContributionHost,
    anchor: Element | null,
    fallbackParent: Element | null = null,
  ) {
    this.component = component;
    this.anchor = anchor;
    this.fallbackParent = fallbackParent;
    this.offPluginChange = component.on('plugin-change', () => this.render());
    this.render();
  }

  render(): void {
    this.clear();
    const place = this.placement();
    if (!place) {
      return;
    }

    for (const contribution of this.contributions()) {
      const mount = document.createElement('div');
      mount.className = 'topbar-settings__field';
      mount.dataset['role'] = 'plugin-settings';
      place(mount);

      try {
        const teardown = contribution.render(mount, this.component);
        this.fields.push({
          mount,
          teardown: typeof teardown === 'function' ? teardown : null,
        });
      } catch (error) {
        console.error('Open Lyric plugin settings field failed.', error);
        mount.remove();
      }
    }
  }

  /** The popup's Reset: every contributed field back to its default. */
  reset(): void {
    for (const contribution of this.contributions()) {
      try {
        contribution.reset?.();
      } catch (error) {
        console.error('Open Lyric plugin settings reset failed.', error);
      }
    }
  }

  destroy(): void {
    this.offPluginChange?.();
    this.offPluginChange = null;
    this.clear();
    this.anchor = null;
    this.fallbackParent = null;
  }

  private placement(): ((mount: HTMLElement) => void) | null {
    const { anchor, fallbackParent } = this;
    if (anchor?.parentNode) {
      return (mount) => anchor.before(mount);
    }
    if (fallbackParent) {
      return (mount) => fallbackParent.append(mount);
    }
    return null;
  }

  private contributions(): OpenLyricSettingsContribution[] {
    return this.component
      .pluginContributions<unknown>('settings')
      .flatMap((entry) => (Array.isArray(entry) ? entry : [entry]))
      .filter(isSettingsContribution);
  }

  private clear(): void {
    for (const { mount, teardown } of this.fields.splice(0)) {
      try {
        teardown?.();
      } catch (error) {
        console.error('Open Lyric plugin settings teardown failed.', error);
      }
      mount.remove();
    }
  }
}
