import { marked } from 'marked';

import { OLParser } from '../../plugins/OpenLyric/domain/parser/OLParser.ts';
import {
  DEFAULT_STRUMMING_PATTERN_TEXT,
  createChordedLyricTextLines,
  createPreviewHelpers,
  createPreviewLineEntries,
  createStrummingPatternPreviewContextFromConfigBody,
  createStrummingPatternPreviewContextFromMarkdown,
  escapeHtml,
  getPreviewSourceLocation,
  normalizeMarkdownRenderableUrls,
  parseStrummingPatterns,
  parseStrummingPatternSteps,
  previewHelpers,
  renderInlineTextPlainText,
  renderOpenLyricEmptyDocumentHtml,
  renderOpenLyricFenceHtml,
  renderStrummingPatternGrid,
  sanitizeHtml,
} from '../../plugins/OpenLyric/preview/helpers.ts';

const OL_FENCE_BLOCK_RE = /^```ol:([^\r\n]*)[ \t]*\r?\n([\s\S]*?)^```[ \t]*$/gm;

function normalizeNewlines(value) {
  return String(value ?? '').replace(/\r\n?/g, '\n');
}

function renderFallbackMarkdown(markdown) {
  const escaped = escapeHtml(markdown);
  return escaped
    .replace(/^### (.*)$/gm, '<h3>$1</h3>')
    .replace(/^## (.*)$/gm, '<h2>$1</h2>')
    .replace(/^# (.*)$/gm, '<h1>$1</h1>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/_(.*?)_/g, '<em>$1</em>')
    .replace(/\n/g, '<br>');
}

function getLineNumberAtOffset(text, offset) {
  if (offset <= 0) {
    return 1;
  }

  return text.slice(0, offset).split('\n').length;
}

function getLineNumberAtEndOffset(text, endOffset) {
  if (endOffset <= 0) {
    return 1;
  }

  return getLineNumberAtOffset(text, Math.max(0, endOffset - 1));
}

function getFirstContentColumn(line) {
  const firstContentIndex = String(line ?? '').search(/\S/);
  return firstContentIndex === -1 ? 1 : firstContentIndex + 1;
}

function getEditorDataAttributes(lineNumber, column = 1) {
  if (!lineNumber) {
    return '';
  }

  return ` data-editor-line="${escapeHtml(lineNumber)}" data-editor-column="${escapeHtml(column || 1)}"`;
}

function getFirstRenderableLineInfo(text) {
  const normalizedText = normalizeNewlines(text);
  const lines = normalizedText.split('\n');

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (!line.trim()) {
      continue;
    }

    return {
      lineOffset: index,
      column: getFirstContentColumn(line),
    };
  }

  return {
    lineOffset: 0,
    column: 1,
  };
}

function createPreviewSegments(markdown) {
  const normalizedMarkdown = normalizeNewlines(markdown);
  const segments = [];
  let lastOffset = 0;

  OL_FENCE_BLOCK_RE.lastIndex = 0;

  for (const match of normalizedMarkdown.matchAll(OL_FENCE_BLOCK_RE)) {
    const matchOffset = match.index || 0;
    if (matchOffset > lastOffset) {
      const markdownChunk = normalizedMarkdown.slice(lastOffset, matchOffset);

      segments.push({
        type: 'markdown',
        raw: markdownChunk,
        markdown: markdownChunk,
        startLineNumber: getLineNumberAtOffset(normalizedMarkdown, lastOffset),
        endLineNumber: getLineNumberAtEndOffset(
          normalizedMarkdown,
          matchOffset,
        ),
      });
    }

    const rawFence = match[0] || '';

    segments.push({
      type: 'olFence',
      raw: rawFence,
      info: (match[1] || '').trim(),
      body: match[2] || '',
      startLineNumber: getLineNumberAtOffset(normalizedMarkdown, matchOffset),
      endLineNumber: getLineNumberAtEndOffset(
        normalizedMarkdown,
        matchOffset + rawFence.length,
      ),
    });

    lastOffset = matchOffset + rawFence.length;
  }

  if (lastOffset < normalizedMarkdown.length) {
    const markdownChunk = normalizedMarkdown.slice(lastOffset);

    segments.push({
      type: 'markdown',
      raw: markdownChunk,
      markdown: markdownChunk,
      startLineNumber: getLineNumberAtOffset(normalizedMarkdown, lastOffset),
      endLineNumber: getLineNumberAtEndOffset(
        normalizedMarkdown,
        normalizedMarkdown.length,
      ),
    });
  }

  return segments;
}

function renderMarkdownChunk(markdown, startLineNumber) {
  if (!markdown.trim()) {
    return '';
  }

  const normalizedMarkdown = normalizeNewlines(markdown);
  const tokens = marked.lexer(normalizedMarkdown, {
    gfm: true,
    breaks: true,
  });
  let searchOffset = 0;

  return tokens
    .map((token) => {
      const tokenRaw = token.raw || '';
      const tokenOffset = normalizedMarkdown.indexOf(tokenRaw, searchOffset);
      const resolvedOffset = tokenOffset === -1 ? searchOffset : tokenOffset;
      const lineInfo = getFirstRenderableLineInfo(tokenRaw);
      const lineNumber =
        startLineNumber +
        getLineNumberAtOffset(normalizedMarkdown, resolvedOffset) -
        1 +
        lineInfo.lineOffset;
      const column = lineInfo.column;

      if (tokenOffset !== -1) {
        searchOffset = tokenOffset + tokenRaw.length;
      }

      return `<div class="ol-preview-markdown-block"${getEditorDataAttributes(lineNumber, column)}>${marked.parser(
        [token],
      )}</div>`;
    })
    .join('');
}

function renderPreviewSegmentContent(segment, helpers = previewHelpers) {
  if (!segment || typeof segment !== 'object') {
    return '';
  }

  if (segment.type === 'olFence') {
    const sourceLocation = getPreviewSourceLocation(
      segment.body,
      segment.startLineNumber,
    );

    return renderOpenLyricFenceHtml(
      segment.info,
      segment.body,
      sourceLocation,
      helpers,
    );
  }

  return renderMarkdownChunk(segment.markdown, segment.startLineNumber);
}

function renderPreviewSegmentContainer(segment, helpers = previewHelpers) {
  const content = renderPreviewSegmentContent(segment, helpers);

  if (!content) {
    return '';
  }

  return [
    `<div class="ol-preview-segment" data-preview-segment-type="${escapeHtml(segment.type)}" data-preview-segment-start-line="${escapeHtml(segment.startLineNumber)}" data-preview-segment-end-line="${escapeHtml(segment.endLineNumber)}">`,
    content,
    '</div>',
  ].join('');
}

function renderMarkdownWithMarked(markdown, context = {}) {
  const helpers = context.previewHelpers || previewHelpers;

  return createPreviewSegments(markdown)
    .map((segment) => renderPreviewSegmentContainer(segment, helpers))
    .join('\n');
}

const previewParser = new OLParser({
  marked: renderMarkdownWithMarked,
  beforeMarked: normalizeNewlines,
  afterMarked: sanitizeHtml,
});

function renderMarkdownPreview(markdown, options = {}) {
  try {
    const helperOptions =
      options && typeof options === 'object' ? { ...options } : {};

    // A blank document renders as the "Start a new song" card rather than as
    // nothing — a reader who never opens the text panel has no other way in.
    // Opt-in: only a host with a document to write the song into asks for it,
    // so a standalone preview (and its export gates) still sees a blank
    // document as empty.
    if (
      helperOptions.showEmptyDocumentStart &&
      !String(markdown ?? '').trim()
    ) {
      return sanitizeHtml(
        renderOpenLyricEmptyDocumentHtml(createPreviewHelpers(helperOptions)),
      );
    }

    if (
      !Object.prototype.hasOwnProperty.call(
        helperOptions,
        'patternPreviewContext',
      )
    ) {
      helperOptions.patternPreviewContext =
        createStrummingPatternPreviewContextFromMarkdown(markdown);
    }

    return previewParser.parse(markdown, {
      context: {
        previewHelpers: createPreviewHelpers(helperOptions),
      },
    });
  } catch (error) {
    console.error('Failed to render markdown preview', error);
    return sanitizeHtml(renderFallbackMarkdown(String(markdown || '')));
  }
}

function renderMarkdownPreviewSegment(segment, options = {}) {
  if (!segment || typeof segment !== 'object') {
    return '';
  }

  const helperOptions =
    options && typeof options === 'object' ? { ...options } : {};
  const helpers = createPreviewHelpers(helperOptions);

  return sanitizeHtml(renderPreviewSegmentContainer(segment, helpers));
}

export {
  DEFAULT_STRUMMING_PATTERN_TEXT,
  createChordedLyricTextLines,
  createPreviewHelpers,
  createPreviewLineEntries,
  createPreviewSegments,
  createStrummingPatternPreviewContextFromConfigBody,
  createStrummingPatternPreviewContextFromMarkdown,
  escapeHtml,
  getPreviewSourceLocation,
  normalizeMarkdownRenderableUrls,
  parseStrummingPatterns,
  parseStrummingPatternSteps,
  previewHelpers,
  renderInlineTextPlainText,
  renderMarkdownPreview,
  renderMarkdownPreviewSegment,
  renderStrummingPatternGrid,
  sanitizeHtml,
};
