import { getCurrentValue, refs } from '../../shared.ts';
import {
  SHARE_QR_GENERATING_MESSAGE,
  SHARE_QR_LINK_ERROR_MESSAGE,
  SHARE_QR_LINK_FULLSCREEN_READY_MESSAGE,
  SHARE_QR_LINK_PENDING_MESSAGE,
  SHARE_QR_LINK_READY_MESSAGE,
  SHARE_QR_TEXT_ERROR_MESSAGE,
  SHARE_QR_TEXT_FULLSCREEN_READY_MESSAGE,
  SHARE_QR_TEXT_PENDING_MESSAGE,
  SHARE_QR_TEXT_READY_MESSAGE,
  renderQrCodeToCanvas,
  splitTextIntoQrChunks,
} from './constants.ts';

function applyDocumentControllerShareQrMethods(DocumentControllerClass) {
  Object.assign(DocumentControllerClass.prototype, {
    getShareQrDescriptor(this: any) {
      if (this.getShareOutputMode() === 'qr-text') {
        return {
          mode: 'qr-text',
          maxCharactersPerChunk: this.getShareQrTextChunkLength(),
          value: String(getCurrentValue() ?? ''),
          pendingMessage: SHARE_QR_TEXT_PENDING_MESSAGE,
          pendingTone: 'info',
          readyMessage: SHARE_QR_TEXT_READY_MESSAGE,
          fullscreenReadyMessage: SHARE_QR_TEXT_FULLSCREEN_READY_MESSAGE,
          errorMessage: SHARE_QR_TEXT_ERROR_MESSAGE,
        };
      }

      return {
        mode: 'qr-link',
        value: String(refs.shareLinkTextarea?.value || '').trim(),
        pendingMessage:
          refs.shareLinkMessage?.textContent || SHARE_QR_LINK_PENDING_MESSAGE,
        pendingTone: refs.shareLinkMessage?.dataset.tone || 'info',
        readyMessage: SHARE_QR_LINK_READY_MESSAGE,
        fullscreenReadyMessage: SHARE_QR_LINK_FULLSCREEN_READY_MESSAGE,
        errorMessage: SHARE_QR_LINK_ERROR_MESSAGE,
      };
    },

    setShareLinkQrMessage(this: any, message, tone = 'muted') {
      if (!refs.shareLinkQrMessage) {
        return;
      }

      refs.shareLinkQrMessage.dataset.tone = tone;
      refs.shareLinkQrMessage.textContent = message;
    },

    setShareLinkQrFullscreenMessage(this: any, message, tone = 'muted') {
      if (!refs.shareLinkQrFullscreenMessage) {
        return;
      }

      refs.shareLinkQrFullscreenMessage.dataset.tone = tone;
      refs.shareLinkQrFullscreenMessage.textContent = message;
    },

    resetShareLinkQrPreview(
      this: any,
      {
        message = SHARE_QR_LINK_PENDING_MESSAGE,
        tone = 'muted',
        invalidatePendingRender = true,
      } = {},
    ) {
      if (invalidatePendingRender) {
        this.shareLinkQrRenderRequestId += 1;
      }

      this.activeShareQrDescriptor = null;
      this.shareQrPreviewTrigger = null;

      if (refs.shareLinkQrItems) {
        refs.shareLinkQrItems.replaceChildren();
        refs.shareLinkQrItems.hidden = true;
      }

      if (refs.shareLinkQrPlaceholder) {
        refs.shareLinkQrPlaceholder.hidden = false;
      }

      this.setShareLinkQrMessage(message, tone);
    },

    resetShareLinkQrFullscreen(
      this: any,
      {
        message = SHARE_QR_LINK_PENDING_MESSAGE,
        tone = 'muted',
        invalidatePendingRender = true,
      } = {},
    ) {
      if (invalidatePendingRender) {
        this.shareLinkQrFullscreenRenderRequestId += 1;
      }

      if (refs.shareLinkQrFullscreenItems) {
        refs.shareLinkQrFullscreenItems.replaceChildren();
        refs.shareLinkQrFullscreenItems.hidden = true;
      }

      if (refs.shareLinkQrFullscreenPlaceholder) {
        refs.shareLinkQrFullscreenPlaceholder.hidden = false;
      }

      this.setShareLinkQrFullscreenMessage(message, tone);
    },

    getShareLinkQrFullscreenWidth(this: any) {
      const viewportWidth = Math.max(320, Number(globalThis.innerWidth) || 320);
      const viewportHeight = Math.max(
        320,
        Number(globalThis.innerHeight) || 320,
      );

      return Math.max(
        280,
        Math.min(720, viewportWidth - 96, viewportHeight - 220),
      );
    },

    getShareLinkQrPreviewWidth(this: any, chunkCount) {
      return chunkCount > 1 ? 208 : 288;
    },

    getShareLinkQrFullscreenItemWidth(this: any, visibleItemCount) {
      if (visibleItemCount > 1) {
        return Math.min(
          420,
          Math.max(240, this.getShareLinkQrFullscreenWidth()),
        );
      }

      return this.getShareLinkQrFullscreenWidth();
    },

    getShareQrReadyMessage(this: any, descriptor) {
      if (descriptor.mode === 'qr-text' && descriptor.chunkCount > 1) {
        return `Markdown text is split into ${descriptor.chunkCount} QR codes with up to ${descriptor.maxCharactersPerChunk} characters each. Scan them in order from 1 to ${descriptor.chunkCount}.`;
      }

      return descriptor.readyMessage;
    },

    getShareQrFullscreenReadyMessage(
      this: any,
      descriptor,
      chunkNumber = null,
    ) {
      if (
        descriptor.mode === 'qr-text' &&
        descriptor.chunkCount > 1 &&
        Number.isInteger(chunkNumber)
      ) {
        return `Showing chunk ${chunkNumber} of ${descriptor.chunkCount}. Scan this QR code, then open the next chunk.`;
      }

      if (descriptor.mode === 'qr-text' && descriptor.chunkCount > 1) {
        return `Markdown text is split into ${descriptor.chunkCount} QR codes with up to ${descriptor.maxCharactersPerChunk} characters each. Scan the chunks in order from 1 to ${descriptor.chunkCount}.`;
      }

      return descriptor.fullscreenReadyMessage;
    },

    async prepareShareQrDescriptorForRender(this: any, baseDescriptor) {
      const chunks =
        baseDescriptor.mode === 'qr-text'
          ? await splitTextIntoQrChunks(
              baseDescriptor.value,
              baseDescriptor.maxCharactersPerChunk,
            )
          : [baseDescriptor.value];

      return {
        ...baseDescriptor,
        chunks,
        chunkCount: chunks.length,
      };
    },

    createShareQrItemElement(
      this: any,
      { chunkCount, chunkIndex, fullscreen = false, interactive = false },
    ) {
      const itemElement = document.createElement(
        interactive ? 'button' : 'div',
      );
      itemElement.className = [
        'share-link-dialog__qr-item',
        interactive ? 'share-link-dialog__qr-item--interactive' : '',
        fullscreen ? 'share-link-dialog__qr-item--fullscreen' : '',
      ]
        .filter(Boolean)
        .join(' ');

      if (interactive) {
        itemElement.type = 'button';
        itemElement.title = 'Open fullscreen QR code';
        itemElement.dataset.chunkIndex = String(chunkIndex - 1);
        itemElement.addEventListener(
          'click',
          this.handleShareQrPreviewActivate,
        );
        itemElement.setAttribute(
          'aria-label',
          chunkCount > 1
            ? `Open fullscreen QR code for chunk ${chunkIndex} of ${chunkCount}`
            : 'Open fullscreen QR code',
        );
      }

      const canvasElement = document.createElement('canvas');
      canvasElement.className = [
        'share-link-dialog__qr-item-canvas',
        fullscreen ? 'share-link-dialog__qr-item-canvas--fullscreen' : '',
      ]
        .filter(Boolean)
        .join(' ');
      canvasElement.setAttribute('aria-hidden', 'true');
      itemElement.append(canvasElement);

      if (chunkCount > 1) {
        const labelElement = document.createElement('span');
        labelElement.className = [
          'share-link-dialog__qr-item-label',
          fullscreen ? 'share-link-dialog__qr-item-label--fullscreen' : '',
        ]
          .filter(Boolean)
          .join(' ');
        labelElement.textContent = `Chunk ${chunkIndex} of ${chunkCount}`;
        itemElement.append(labelElement);
      }

      return {
        canvasElement,
        itemElement,
      };
    },

    async renderShareQrCollection(
      this: any,
      {
        chunkWidth,
        container,
        descriptor,
        chunkEntries,
        fullscreen = false,
        placeholder,
      },
    ) {
      if (!container) {
        return;
      }

      const resolvedChunkEntries =
        chunkEntries ||
        descriptor.chunks.map((chunkValue, index) => ({
          chunkIndex: index + 1,
          chunkValue,
        }));

      const qrItems = resolvedChunkEntries.map(({ chunkIndex, chunkValue }) => {
        const { canvasElement, itemElement } = this.createShareQrItemElement({
          chunkCount: descriptor.chunkCount,
          chunkIndex,
          fullscreen,
          interactive: !fullscreen,
        });

        return {
          canvasElement,
          itemElement,
          chunkValue,
        };
      });

      container.replaceChildren(
        ...qrItems.map(({ itemElement }) => itemElement),
      );
      container.hidden = false;

      if (placeholder) {
        placeholder.hidden = true;
      }

      await Promise.all(
        qrItems.map(({ canvasElement, chunkValue }) => {
          return renderQrCodeToCanvas(canvasElement, chunkValue, chunkWidth);
        }),
      );
    },

    async renderShareLinkQrPreview(this: any, descriptor) {
      if (!refs.shareLinkQrItems) {
        return;
      }

      const requestId = ++this.shareLinkQrRenderRequestId;

      if (refs.shareLinkQrItems) {
        refs.shareLinkQrItems.replaceChildren();
        refs.shareLinkQrItems.hidden = true;
      }

      if (refs.shareLinkQrPlaceholder) {
        refs.shareLinkQrPlaceholder.hidden = false;
      }

      this.setShareLinkQrMessage(SHARE_QR_GENERATING_MESSAGE, 'info');

      try {
        await this.renderShareQrCollection({
          chunkWidth: this.getShareLinkQrPreviewWidth(descriptor.chunkCount),
          container: refs.shareLinkQrItems,
          descriptor,
          placeholder: refs.shareLinkQrPlaceholder,
        });

        if (requestId !== this.shareLinkQrRenderRequestId) {
          return;
        }

        this.activeShareQrDescriptor = descriptor;
        this.setShareLinkQrMessage(
          this.getShareQrReadyMessage(descriptor),
          'success',
        );
      } catch (_error) {
        if (requestId !== this.shareLinkQrRenderRequestId) {
          return;
        }

        this.resetShareLinkQrPreview({
          invalidatePendingRender: false,
          message: descriptor.errorMessage,
          tone: 'error',
        });
      }
    },

    async renderShareLinkQrFullscreen(this: any, descriptor) {
      if (!refs.shareLinkQrFullscreenItems) {
        return;
      }

      const requestId = ++this.shareLinkQrFullscreenRenderRequestId;
      const requestedChunkIndex = Number.isInteger(
        this.shareQrFullscreenChunkIndex,
      )
        ? this.shareQrFullscreenChunkIndex
        : 0;
      const selectedChunkIndex = Math.min(
        Math.max(requestedChunkIndex, 0),
        descriptor.chunkCount - 1,
      );
      const chunkEntries = [
        {
          chunkIndex: selectedChunkIndex + 1,
          chunkValue: descriptor.chunks[selectedChunkIndex],
        },
      ];

      this.shareQrFullscreenChunkIndex = selectedChunkIndex;

      if (refs.shareLinkQrFullscreenItems) {
        refs.shareLinkQrFullscreenItems.replaceChildren();
        refs.shareLinkQrFullscreenItems.hidden = true;
      }

      if (refs.shareLinkQrFullscreenPlaceholder) {
        refs.shareLinkQrFullscreenPlaceholder.hidden = false;
      }

      this.setShareLinkQrFullscreenMessage(SHARE_QR_GENERATING_MESSAGE, 'info');

      try {
        await this.renderShareQrCollection({
          chunkWidth: this.getShareLinkQrFullscreenItemWidth(
            chunkEntries.length,
          ),
          container: refs.shareLinkQrFullscreenItems,
          descriptor,
          chunkEntries,
          fullscreen: true,
          placeholder: refs.shareLinkQrFullscreenPlaceholder,
        });

        if (requestId !== this.shareLinkQrFullscreenRenderRequestId) {
          return;
        }

        this.setShareLinkQrFullscreenMessage(
          this.getShareQrFullscreenReadyMessage(
            descriptor,
            selectedChunkIndex + 1,
          ),
          'success',
        );
      } catch (_error) {
        if (requestId !== this.shareLinkQrFullscreenRenderRequestId) {
          return;
        }

        this.resetShareLinkQrFullscreen({
          invalidatePendingRender: false,
          message: descriptor.errorMessage,
          tone: 'error',
        });
      }
    },

    async refreshShareLinkQrFromCurrentValue(this: any) {
      if (!this.isShareQrModeSelected()) {
        this.activeShareQrDescriptor = null;

        if (refs.shareLinkQrFullscreenDialog?.open) {
          this.closeShareLinkQrFullscreen();
        }

        return;
      }

      const qrDescriptor = this.getShareQrDescriptor();

      if (!qrDescriptor.value.length) {
        this.activeShareQrDescriptor = null;
        this.resetShareLinkQrPreview({
          message: qrDescriptor.pendingMessage,
          tone: qrDescriptor.pendingTone,
        });

        if (refs.shareLinkQrFullscreenDialog?.open) {
          this.resetShareLinkQrFullscreen({
            message: qrDescriptor.pendingMessage,
            tone: qrDescriptor.pendingTone,
          });
        }

        return;
      }

      let preparedQrDescriptor = null;

      try {
        preparedQrDescriptor =
          await this.prepareShareQrDescriptorForRender(qrDescriptor);
      } catch (_error) {
        this.activeShareQrDescriptor = null;
        this.resetShareLinkQrPreview({
          message: qrDescriptor.errorMessage,
          tone: 'error',
        });

        if (refs.shareLinkQrFullscreenDialog?.open) {
          this.resetShareLinkQrFullscreen({
            message: qrDescriptor.errorMessage,
            tone: 'error',
          });
        }

        return;
      }

      await this.renderShareLinkQrPreview(preparedQrDescriptor);

      if (refs.shareLinkQrFullscreenDialog?.open) {
        await this.renderShareLinkQrFullscreen(preparedQrDescriptor);
      }
    },

    async openShareLinkQrFullscreen(this: any) {
      const qrDescriptor = this.activeShareQrDescriptor;

      if (
        !this.isShareQrModeSelected() ||
        !qrDescriptor?.chunkCount ||
        !refs.shareLinkQrItems?.childElementCount ||
        !refs.shareLinkQrFullscreenDialog
      ) {
        return;
      }

      if (!refs.shareLinkQrFullscreenDialog.open) {
        try {
          refs.shareLinkQrFullscreenDialog.showModal();
        } catch (_error) {
          refs.shareLinkQrFullscreenDialog.show();
        }
      }

      this.focusDocumentElement(refs.closeShareLinkQrFullscreenBtn, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });
      await this.renderShareLinkQrFullscreen(qrDescriptor);
    },

    closeShareLinkQrFullscreen(this: any) {
      if (!refs.shareLinkQrFullscreenDialog?.open) {
        return;
      }

      refs.shareLinkQrFullscreenDialog.close();
    },

    handleShareQrPreviewActivate(this: any, event) {
      this.shareQrPreviewTrigger = event.currentTarget;
      const requestedChunkIndex = Number.parseInt(
        event.currentTarget?.dataset.chunkIndex || '0',
        10,
      );
      this.shareQrFullscreenChunkIndex = Number.isInteger(requestedChunkIndex)
        ? requestedChunkIndex
        : 0;
      void this.openShareLinkQrFullscreen();
    },

    handleShareQrFullscreenDialogClose(this: any) {
      this.resetShareLinkQrFullscreen();

      if (!refs.shareLinkDialog?.open) {
        return;
      }

      if (this.shareQrPreviewTrigger?.isConnected) {
        this.focusDocumentElement(this.shareQrPreviewTrigger, {
          preventScroll: true,
          skipTouchIosForButtons: true,
        });
        this.shareQrFullscreenChunkIndex = null;
        return;
      }

      this.shareQrFullscreenChunkIndex = null;
      this.focusDocumentElement(
        refs.shareLinkQrItems?.querySelector('button'),
        {
          preventScroll: true,
          skipTouchIosForButtons: true,
        },
      );
    },
  });
}

export { applyDocumentControllerShareQrMethods };
