import {
  readDocumentLineRange,
  refs,
  replaceDocumentLineRange,
  state,
} from '../../../../editor/scripts/shared.ts';

/**
 * In-preview editing of a section's lyric text.
 *
 * The pencil in each section card header (`ol-preview-fence__edit`, rendered by
 * `OLFenceDefinition.renderPreviewEditAction`) swaps that card's rendered body
 * for a textarea holding the section's *source* lines. Save writes those lines
 * back over the same source range through `replaceDocumentLineRange`, and the
 * panel re-renders from the new document text — the preview never keeps a DOM
 * mutation of its own, so the two panels and Monaco's undo stack stay in step.
 *
 * One textarea per section rather than one control per line is deliberate:
 * editing a line, adding one and removing one are then the same gesture, and
 * the panel only re-renders once, on Save — so no caret is lost mid-word.
 *
 * Markdown panel only. The lyric/presentation panel shares these delegated
 * listeners, so every lookup here is scoped to `refs.preview`.
 */

const SECTION_EDITOR_HINT_TEXT =
  'One line per lyric line. Use "Insert chord" to add a chord at the cursor, or type it in square brackets, like [G].';

function applyPreviewControllerSectionEditingMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    /**
     * Whether this page has a document surface to write an edit back to.
     *
     * A standalone markdown-preview embed renders the same cards but has no
     * editor behind them, so its pencils would be dead controls. The flag goes
     * on the panel element and CSS reveals the pencils off it, which keeps the
     * decision in one place instead of in the (pure) render functions.
     */
    canEditPreviewSections(this: any) {
      return Boolean(
        state.editor ||
        refs.simpleEditorTextarea instanceof HTMLTextAreaElement ||
        refs.editorHost instanceof Element,
      );
    },

    syncPreviewSectionEditingAvailability(this: any) {
      if (!(refs.preview instanceof HTMLElement)) {
        return;
      }

      if (this.canEditPreviewSections()) {
        refs.preview.dataset.olSectionEditing = 'enabled';
        return;
      }

      delete refs.preview.dataset.olSectionEditing;
    },

    /**
     * A full or incremental re-render replaces the markup the open editor form
     * lived in. Nothing is recoverable at that point, so drop the reference
     * rather than leave `Save` pointing at a detached textarea.
     */
    syncPreviewSectionEditorState(this: any) {
      const sectionEditor = this.previewSectionEditor;

      if (!sectionEditor) {
        return;
      }

      if (!sectionEditor.form?.isConnected) {
        this.previewSectionEditor = null;
      }
    },

    getPreviewSectionEditorTrigger(this: any, targetId) {
      if (!targetId || !(refs.preview instanceof HTMLElement)) {
        return null;
      }

      const fence = Array.from(
        refs.preview.querySelectorAll('.ol-preview-fence[id]'),
      ).find((element) => element.id === targetId);

      return (
        fence?.querySelector('[data-preview-action="edit-section-body"]') ||
        null
      );
    },

    buildPreviewSectionEditorForm(
      this: any,
      { label, sourceText, rows, chordStyle = 'annotation', sectionLabel = '' },
    ) {
      const form = document.createElement('form');
      const field = document.createElement('div');
      const textarea = document.createElement('textarea');
      const hint = document.createElement('p');
      const actions = document.createElement('div');
      const saveButton = document.createElement('button');
      const cancelButton = document.createElement('button');
      const hintId = `ol-preview-section-editor-hint-${Math.random().toString(36).slice(2, 10)}`;

      form.className = 'ol-preview-fence__editor';
      form.setAttribute('data-preview-section-editor', 'true');
      // A <details> summary/body pair is not a form context; this one exists
      // only so Enter-on-Save and the submit event behave the way a reader
      // expects inside a card.
      form.noValidate = true;

      field.className = 'ol-preview-fence__editor-field';

      textarea.className = 'ol-preview-fence__editor-input';
      textarea.setAttribute('data-preview-section-editor-input', 'true');
      textarea.setAttribute('aria-label', label);
      textarea.setAttribute('aria-describedby', hintId);
      textarea.setAttribute('spellcheck', 'false');
      textarea.rows = rows;
      textarea.value = sourceText;

      hint.className = 'ol-preview-fence__editor-hint';
      hint.id = hintId;
      hint.textContent = SECTION_EDITOR_HINT_TEXT;

      actions.className = 'ol-preview-fence__editor-actions';

      saveButton.className =
        'ol-preview-fence__editor-button ol-preview-fence__editor-button--save';
      saveButton.type = 'submit';
      saveButton.setAttribute('data-preview-action', 'save-section-body');
      saveButton.textContent = 'Save';

      cancelButton.className =
        'ol-preview-fence__editor-button ol-preview-fence__editor-button--cancel';
      cancelButton.type = 'button';
      cancelButton.setAttribute('data-preview-action', 'cancel-section-body');
      cancelButton.textContent = 'Cancel';

      actions.append(saveButton, cancelButton);

      // The chord picker (section-chords.ts) sits between the textarea and
      // the hint, so the control that writes into the textarea is next to it.
      const chordTools = this.buildPreviewSectionChordTools?.({
        chordStyle,
        sectionLabel,
      });

      field.append(textarea, ...(chordTools ? [chordTools.tools] : []), hint);
      form.append(field, actions);

      return { form, textarea, chordPicker: chordTools?.chordPicker || null };
    },

    /**
     * Open the section editor for one card.
     *
     * The seed comes from the document, never from the rendered body: the
     * rendered line is escaped, comment-filtered, possibly transposed output,
     * while the textarea has to hold the notation itself.
     */
    openPreviewSectionEditor(this: any, trigger) {
      if (!(trigger instanceof HTMLElement)) {
        return false;
      }

      if (!(refs.preview instanceof HTMLElement)) {
        return false;
      }

      if (!refs.preview.contains(trigger) || !this.canEditPreviewSections()) {
        return false;
      }

      const fence = trigger.closest('.ol-preview-fence');
      const body = fence?.querySelector('.ol-preview-fence__body');

      if (!(fence instanceof HTMLElement) || !(body instanceof HTMLElement)) {
        return false;
      }

      const startLineNumber = Number(
        trigger.getAttribute('data-preview-body-start-line'),
      );
      const endLineNumber = Number(
        trigger.getAttribute('data-preview-body-end-line'),
      );

      if (!Number.isInteger(startLineNumber) || startLineNumber < 1) {
        return false;
      }

      if (!Number.isInteger(endLineNumber)) {
        return false;
      }

      const sourceLines = readDocumentLineRange(startLineNumber, endLineNumber);

      if (!sourceLines) {
        return false;
      }

      this.closePreviewSectionEditor({ focusTrigger: false });

      const sectionLabel =
        trigger.getAttribute('data-preview-section-label') || 'section';
      const { form, textarea, chordPicker } =
        this.buildPreviewSectionEditorForm({
          label: `${sectionLabel} text`,
          sourceText: sourceLines.join('\n'),
          rows: Math.min(Math.max(sourceLines.length + 1, 3), 18),
          chordStyle: trigger.getAttribute('data-preview-chord-style') || '',
          sectionLabel,
        });

      if (fence instanceof HTMLDetailsElement) {
        fence.open = true;
      }

      body.hidden = true;
      body.after(form);

      trigger.setAttribute('aria-expanded', 'true');
      fence.dataset.olSectionEditorOpen = 'true';

      this.previewSectionEditor = {
        startLineNumber,
        endLineNumber,
        targetId: fence.id || '',
        sectionLabel,
        body,
        fence,
        form,
        textarea,
        chordPicker,
      };

      form.addEventListener('submit', this.handlePreviewSectionEditorSubmit);
      form.addEventListener('keydown', this.handlePreviewSectionEditorKeyDown);

      // A textarea is the sanctioned auto-focus case on touch iOS/iPadOS — the
      // rule there is about buttons and menuitems swallowing the next tap.
      this.focusElement(textarea, { preventScroll: true });
      textarea.setSelectionRange(textarea.value.length, textarea.value.length);

      return true;
    },

    /**
     * Take one editor form back out of the card, restoring the rendered body.
     *
     * Idempotent, and safe on markup a re-render has already detached — which
     * is how `savePreviewSectionEditor` can run it either side of the write
     * without caring whether the panel re-rendered in between.
     */
    teardownPreviewSectionEditor(this: any, sectionEditor) {
      if (!sectionEditor) {
        return null;
      }

      const { body, fence, form, targetId } = sectionEditor;

      form?.removeEventListener(
        'submit',
        this.handlePreviewSectionEditorSubmit,
      );
      form?.removeEventListener(
        'keydown',
        this.handlePreviewSectionEditorKeyDown,
      );
      form?.remove();

      if (body instanceof HTMLElement) {
        body.hidden = false;
      }

      if (fence instanceof HTMLElement) {
        delete fence.dataset.olSectionEditorOpen;
      }

      // After a re-render the card is new markup, so the pencil to hand focus
      // back to is looked up by the section's target id, not held onto.
      const trigger =
        this.getPreviewSectionEditorTrigger(targetId) ||
        fence?.querySelector?.('[data-preview-action="edit-section-body"]') ||
        null;

      trigger?.setAttribute?.('aria-expanded', 'false');

      return trigger;
    },

    closePreviewSectionEditor(this: any, { focusTrigger = true } = {}) {
      const sectionEditor = this.previewSectionEditor;

      if (!sectionEditor) {
        return false;
      }

      this.previewSectionEditor = null;

      const trigger = this.teardownPreviewSectionEditor(sectionEditor);

      if (focusTrigger) {
        this.focusElement(trigger, {
          preventScroll: true,
          skipTouchIosForButtons: true,
        });
      }

      return true;
    },

    /**
     * Write the textarea back over the section's source lines.
     *
     * The trailing blank lines a reader leaves behind by pressing Enter are
     * dropped, so "Save" never grows the section by an empty line; clearing the
     * textarea entirely removes every body line and leaves an empty section,
     * which is valid notation.
     */
    savePreviewSectionEditor(this: any) {
      const sectionEditor = this.previewSectionEditor;

      if (!sectionEditor) {
        return false;
      }

      if (!sectionEditor.form?.isConnected) {
        this.previewSectionEditor = null;
        return false;
      }

      const { startLineNumber, endLineNumber, textarea } = sectionEditor;
      const nextLines = String(textarea?.value ?? '')
        .replace(/\r\n?/g, '\n')
        .split('\n');

      while (nextLines.length && !nextLines[nextLines.length - 1].trim()) {
        nextLines.pop();
      }

      const previousLines =
        readDocumentLineRange(startLineNumber, endLineNumber) || [];

      if (
        nextLines.length === previousLines.length &&
        nextLines.every((line, index) => line === previousLines[index])
      ) {
        this.closePreviewSectionEditor({ focusTrigger: true });
        return true;
      }

      const previewScrollTop =
        refs.preview instanceof HTMLElement ? refs.preview.scrollTop : 0;

      // Dropped before the write: applying it re-renders the panel
      // synchronously, which takes this form's DOM with it.
      this.previewSectionEditor = null;

      const applied = replaceDocumentLineRange(
        startLineNumber,
        endLineNumber,
        nextLines,
      );

      if (!applied) {
        this.previewSectionEditor = sectionEditor;
        return false;
      }

      // The write re-renders the panel, which usually takes this form with it
      // — but the incremental render paths patch only part of the panel, so the
      // teardown runs unconditionally rather than relying on that.
      const trigger = this.teardownPreviewSectionEditor(sectionEditor);

      // A re-render resets the panel's scroll and blurs whatever was focused.
      // Both are put back so saving a section in a long song does not throw the
      // reader to the top of the document.
      if (refs.preview instanceof HTMLElement) {
        refs.preview.scrollTop = previewScrollTop;
      }

      this.focusElement(trigger, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });

      return true;
    },

    handlePreviewSectionEditorSubmit(this: any, event) {
      event.preventDefault();
      this.savePreviewSectionEditor();
    },

    handlePreviewSectionEditorKeyDown(this: any, event) {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();

        // Escape peels one layer at a time: an open chord picker first, then
        // the editor itself — so dismissing the picker never discards typing.
        if (this.isPreviewSectionChordPickerOpen?.()) {
          this.closePreviewSectionChordPicker({
            focusToggle: !(event.target instanceof HTMLTextAreaElement),
          });
          return;
        }

        this.closePreviewSectionEditor({ focusTrigger: true });
        return;
      }

      // Enter inserts a lyric line, so the keyboard shortcut for saving is the
      // one every multi-line field uses.
      if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
        event.preventDefault();
        this.savePreviewSectionEditor();
      }
    },

    isPreviewSectionEditorElement(this: any, element) {
      if (!(element instanceof Element)) {
        return false;
      }

      return Boolean(element.closest('.ol-preview-fence__editor'));
    },
  });
}

export {
  SECTION_EDITOR_HINT_TEXT,
  applyPreviewControllerSectionEditingMethods,
};
