const SHARED_MARKDOWN_QUERY_PARAM = 'md-text';
const SHARED_MARKDOWN_DATE_QUERY_PARAM = 'md-date';
const SHARED_MARKDOWN_FILE_NAME = 'shared-link.md';
const SHARED_MARKDOWN_QUERY_PARAM_MAX_CHARACTERS = 8000;
const SHARED_MARKDOWN_QUERY_PARAM_WARNING_SUFFIX =
  'This is over the 8,000-character warning threshold, but the link can still be copied.';
const SHARED_MARKDOWN_PASSWORD_PREFIX = 'pwdecrypted:';
const SHARED_MARKDOWN_PASSWORD_DIALOG_MESSAGE =
  'Enter the password to open this shared link.';
const SHARED_MARKDOWN_PASSWORD_REQUIRED_MESSAGE =
  'Password is required before this link can be opened.';
const SHARED_MARKDOWN_PASSWORD_RETRY_MESSAGE =
  'Password was incorrect or the encrypted link is invalid. Try again or cancel.';
const INVALID_MARKDOWN_CONFIRMATION_MESSAGE =
  'There are some errors in the markdown. Do you still want to open it?';
const SHARE_COPY_BUTTON_LABELS = {
  idle: 'Copy Link',
  copying: 'Copying...',
  success: 'Copied',
  error: 'Copy Failed',
};
const SHARE_QR_GENERATING_MESSAGE = 'Generating QR code...';
const SHARE_QR_LINK_READY_MESSAGE =
  'Scan this code with your phone camera to open the shared link.';
const SHARE_QR_LINK_PENDING_MESSAGE =
  'QR code will appear when the share link is ready.';
const SHARE_QR_LINK_ERROR_MESSAGE =
  'QR code could not be generated for this link. Use the link text below instead.';
const SHARE_QR_LINK_FULLSCREEN_READY_MESSAGE =
  'Scan this fullscreen QR code with your phone camera.';
const SHARE_QR_TEXT_READY_MESSAGE =
  'Scan this code to read the raw Open Lyric markdown text.';
const SHARE_QR_TEXT_PENDING_MESSAGE =
  'QR code will appear when the Open Lyric markdown text is ready.';
const SHARE_QR_TEXT_ERROR_MESSAGE =
  'QR code could not be generated from this markdown text. The text may be too large.';
const SHARE_QR_TEXT_FULLSCREEN_READY_MESSAGE =
  'Scan this fullscreen QR code to read the raw Open Lyric markdown text.';
const SHARE_QR_TEXT_DEFAULT_CHARACTERS_PER_CHUNK = 500;
const SHARE_QR_TEXT_MIN_CHARACTERS_PER_CHUNK = 1;
const SHARE_QR_TEXT_MAX_CHARACTERS_PER_CHUNK = 4000;
const SHARE_COPY_BUTTON_RESET_DELAY_MS = 1800;
const SHARE_LINK_REFRESH_DELAY_MS = 250;
const SHARE_ENCRYPTION_ALGORITHM = 'AES-GCM';
const SHARE_ENCRYPTION_DERIVATION_ALGORITHM = 'PBKDF2';
const SHARE_ENCRYPTION_HASH = 'SHA-256';
const SHARE_ENCRYPTION_KEY_LENGTH = 256;
const SHARE_ENCRYPTION_IV_BYTES = 12;
const SHARE_ENCRYPTION_SALT_BYTES = 16;
const SHARE_ENCRYPTION_ITERATIONS = 600000;

let qrCodeModulePromise = null;
let draftExamplesModulePromise = null;

async function loadQrCodeModule() {
  if (!qrCodeModulePromise) {
    qrCodeModulePromise = import('qrcode').then((module) => {
      return module.default || module;
    });
  }

  return qrCodeModulePromise;
}

async function loadDraftExamplesModule() {
  if (!draftExamplesModulePromise) {
    draftExamplesModulePromise = import('../../draft-examples.ts');
  }

  return draftExamplesModulePromise;
}

function encodeBase64Bytes(bytes) {
  let binaryText = '';

  bytes.forEach((byte) => {
    binaryText += String.fromCharCode(byte);
  });

  return globalThis.btoa(binaryText);
}

function decodeBase64Bytes(base64Text) {
  const normalizedBase64Text = String(base64Text ?? '').replace(/\s+/g, '');
  const binaryText = globalThis.atob(normalizedBase64Text);

  return Uint8Array.from(binaryText, (character) => character.charCodeAt(0));
}

function encodeBase64UrlBytes(bytes) {
  return encodeBase64Bytes(bytes)
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function decodeBase64UrlBytes(base64UrlText) {
  const normalizedBase64Text = String(base64UrlText ?? '')
    .replace(/\s+/g, '')
    .replace(/-/g, '+')
    .replace(/_/g, '/');
  const paddingLength = (4 - (normalizedBase64Text.length % 4)) % 4;

  return decodeBase64Bytes(
    `${normalizedBase64Text}${'='.repeat(paddingLength)}`,
  );
}

function encodeBase64Utf8(text) {
  return encodeBase64Bytes(new TextEncoder().encode(String(text ?? '')));
}

function decodeBase64Utf8(base64Text) {
  return new TextDecoder().decode(decodeBase64Bytes(base64Text));
}

async function renderQrCodeToCanvas(canvas, shareLink, width) {
  const qrCodeModule = await loadQrCodeModule();

  return qrCodeModule.toCanvas(canvas, shareLink, {
    color: {
      dark: '#0f172a',
      light: '#ffffffff',
    },
    errorCorrectionLevel: 'L',
    margin: 1,
    width: Math.max(64, Math.floor(width)),
  });
}

function canEncodeQrValue(value, qrCodeModule) {
  try {
    qrCodeModule.create(String(value ?? ''), {
      errorCorrectionLevel: 'L',
    });
    return true;
  } catch (_error) {
    return false;
  }
}

function normalizeShareQrTextChunkLength(value) {
  const parsedValue = Number.parseInt(String(value ?? ''), 10);

  if (!Number.isFinite(parsedValue)) {
    return SHARE_QR_TEXT_DEFAULT_CHARACTERS_PER_CHUNK;
  }

  return Math.min(
    SHARE_QR_TEXT_MAX_CHARACTERS_PER_CHUNK,
    Math.max(SHARE_QR_TEXT_MIN_CHARACTERS_PER_CHUNK, parsedValue),
  );
}

function findLargestEncodableQrChunkLength(
  characters,
  startIndex,
  maxCharactersPerChunk,
  qrCodeModule,
) {
  let low = 1;
  let high = Math.min(maxCharactersPerChunk, characters.length - startIndex);
  let bestLength = 0;

  while (low <= high) {
    const candidateLength = Math.floor((low + high) / 2);
    const candidateValue = characters
      .slice(startIndex, startIndex + candidateLength)
      .join('');

    if (canEncodeQrValue(candidateValue, qrCodeModule)) {
      bestLength = candidateLength;
      low = candidateLength + 1;
      continue;
    }

    high = candidateLength - 1;
  }

  if (bestLength < 1) {
    throw new Error('No valid QR text chunk size was found.');
  }

  return bestLength;
}

async function splitTextIntoQrChunks(text, maxCharactersPerChunk) {
  const normalizedText = String(text ?? '');

  if (!normalizedText.length) {
    return [];
  }

  const qrCodeModule = await loadQrCodeModule();

  const characters = Array.from(normalizedText);
  const normalizedChunkLength = normalizeShareQrTextChunkLength(
    maxCharactersPerChunk,
  );

  const chunks = [];
  let startIndex = 0;

  while (startIndex < characters.length) {
    const chunkLength = findLargestEncodableQrChunkLength(
      characters,
      startIndex,
      normalizedChunkLength,
      qrCodeModule,
    );
    const chunkValue = characters
      .slice(startIndex, startIndex + chunkLength)
      .join('');

    chunks.push(chunkValue);
    startIndex += chunkLength;
  }

  return chunks;
}

function formatShareDateForUrl(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const seconds = String(date.getSeconds()).padStart(2, '0');

  return `${year}-${month}-${day}_${hours}-${minutes}-${seconds}`;
}

function normalizeSharedMarkdownParam(value) {
  const trimmedValue = String(value ?? '').trim();

  if (
    trimmedValue.length >= 2 &&
    trimmedValue.startsWith('"') &&
    trimmedValue.endsWith('"')
  ) {
    return trimmedValue.slice(1, -1);
  }

  return trimmedValue;
}

function getShareCrypto() {
  if (!globalThis.crypto?.subtle) {
    return null;
  }

  return globalThis.crypto;
}

function isShareEncryptionSupported() {
  return Boolean(getShareCrypto());
}

async function deriveShareEncryptionKey(password, salt, iterations) {
  const cryptoApi = getShareCrypto();

  if (!cryptoApi) {
    throw new Error('Web Crypto is unavailable.');
  }

  const baseKey = await cryptoApi.subtle.importKey(
    'raw',
    new TextEncoder().encode(password),
    SHARE_ENCRYPTION_DERIVATION_ALGORITHM,
    false,
    ['deriveKey'],
  );

  return cryptoApi.subtle.deriveKey(
    {
      name: SHARE_ENCRYPTION_DERIVATION_ALGORITHM,
      salt,
      iterations,
      hash: SHARE_ENCRYPTION_HASH,
    },
    baseKey,
    {
      name: SHARE_ENCRYPTION_ALGORITHM,
      length: SHARE_ENCRYPTION_KEY_LENGTH,
    },
    false,
    ['encrypt', 'decrypt'],
  );
}

function serializeEncryptedShareValue({ iterations, salt, iv, ciphertext }) {
  return `${SHARED_MARKDOWN_PASSWORD_PREFIX}v1.${iterations}.${encodeBase64UrlBytes(
    salt,
  )}.${encodeBase64UrlBytes(iv)}.${encodeBase64UrlBytes(ciphertext)}`;
}

function parseEncryptedShareValue(encryptedValue) {
  if (
    !String(encryptedValue ?? '').startsWith(SHARED_MARKDOWN_PASSWORD_PREFIX)
  ) {
    throw new Error('Encrypted share prefix is missing.');
  }

  const payloadText = String(encryptedValue).slice(
    SHARED_MARKDOWN_PASSWORD_PREFIX.length,
  );
  const parts = payloadText.split('.');

  if (parts.length !== 5) {
    throw new Error('Encrypted share payload is malformed.');
  }

  const [version, iterationText, saltText, ivText, ciphertextText] = parts;
  const iterations = Number.parseInt(iterationText, 10);

  if (version !== 'v1' || !Number.isSafeInteger(iterations) || iterations < 1) {
    throw new Error('Encrypted share payload metadata is invalid.');
  }

  return {
    iterations,
    salt: decodeBase64UrlBytes(saltText),
    iv: decodeBase64UrlBytes(ivText),
    ciphertext: decodeBase64UrlBytes(ciphertextText),
  };
}

async function encryptSharedMarkdown(markdown, password) {
  const cryptoApi = getShareCrypto();

  if (!cryptoApi) {
    throw new Error('Web Crypto is unavailable.');
  }

  const salt = cryptoApi.getRandomValues(
    new Uint8Array(SHARE_ENCRYPTION_SALT_BYTES),
  );
  const iv = cryptoApi.getRandomValues(
    new Uint8Array(SHARE_ENCRYPTION_IV_BYTES),
  );
  const key = await deriveShareEncryptionKey(
    password,
    salt,
    SHARE_ENCRYPTION_ITERATIONS,
  );
  const ciphertextBuffer = await cryptoApi.subtle.encrypt(
    {
      name: SHARE_ENCRYPTION_ALGORITHM,
      iv,
    },
    key,
    new TextEncoder().encode(markdown),
  );

  return serializeEncryptedShareValue({
    iterations: SHARE_ENCRYPTION_ITERATIONS,
    salt,
    iv,
    ciphertext: new Uint8Array(ciphertextBuffer),
  });
}

async function decryptSharedMarkdown(encryptedValue, password) {
  const cryptoApi = getShareCrypto();

  if (!cryptoApi) {
    throw new Error('Web Crypto is unavailable.');
  }

  const { iterations, salt, iv, ciphertext } =
    parseEncryptedShareValue(encryptedValue);
  const key = await deriveShareEncryptionKey(password, salt, iterations);
  const plaintextBuffer = await cryptoApi.subtle.decrypt(
    {
      name: SHARE_ENCRYPTION_ALGORITHM,
      iv,
    },
    key,
    ciphertext,
  );

  return new TextDecoder().decode(plaintextBuffer);
}

export {
  INVALID_MARKDOWN_CONFIRMATION_MESSAGE,
  SHARE_COPY_BUTTON_LABELS,
  SHARE_COPY_BUTTON_RESET_DELAY_MS,
  SHARE_LINK_REFRESH_DELAY_MS,
  SHARE_QR_GENERATING_MESSAGE,
  SHARE_QR_LINK_ERROR_MESSAGE,
  SHARE_QR_LINK_FULLSCREEN_READY_MESSAGE,
  SHARE_QR_LINK_PENDING_MESSAGE,
  SHARE_QR_LINK_READY_MESSAGE,
  SHARE_QR_TEXT_DEFAULT_CHARACTERS_PER_CHUNK,
  SHARE_QR_TEXT_ERROR_MESSAGE,
  SHARE_QR_TEXT_FULLSCREEN_READY_MESSAGE,
  SHARE_QR_TEXT_PENDING_MESSAGE,
  SHARE_QR_TEXT_READY_MESSAGE,
  SHARED_MARKDOWN_DATE_QUERY_PARAM,
  SHARED_MARKDOWN_FILE_NAME,
  SHARED_MARKDOWN_PASSWORD_DIALOG_MESSAGE,
  SHARED_MARKDOWN_PASSWORD_PREFIX,
  SHARED_MARKDOWN_PASSWORD_REQUIRED_MESSAGE,
  SHARED_MARKDOWN_PASSWORD_RETRY_MESSAGE,
  SHARED_MARKDOWN_QUERY_PARAM,
  SHARED_MARKDOWN_QUERY_PARAM_MAX_CHARACTERS,
  SHARED_MARKDOWN_QUERY_PARAM_WARNING_SUFFIX,
  decodeBase64Utf8,
  decryptSharedMarkdown,
  encodeBase64Utf8,
  encryptSharedMarkdown,
  formatShareDateForUrl,
  isShareEncryptionSupported,
  loadDraftExamplesModule,
  normalizeShareQrTextChunkLength,
  normalizeSharedMarkdownParam,
  renderQrCodeToCanvas,
  splitTextIntoQrChunks,
};
