import {
  createPreviewTargetId,
  parseOpenLyricFences,
} from '../../domain/fence-locations.ts';
import { parseFenceHeader, registry } from '../../domain/parser/fences.ts';
import { formatDeclaredPartName } from '../../domain/parser/fences/OLFenceDefinition.ts';
import {
  findAdjacentDuplicateStructureError,
  parseStructureValue,
} from '../../domain/structure.ts';
import {
  normalizeConfigFieldName,
  readDocumentLineRange,
  refs,
  replaceDocumentLineRange,
} from '../../../../editor/scripts/shared.ts';
import { STRUCTURE_DEFINITIONS_BY_HEADER } from './constants.ts';

/**
 * Creating, naming and removing sections from the rendered preview.
 *
 * Three affordances, one mechanism. "Add Lyric" — the control `OLConfig` renders
 * in the gap under the Config card — opens a picker for the section type and
 * its number, and writes a new ```` ```ol:Verse 3 ```` fence after the last
 * fence in the document. The tag beside a section card's title opens the same
 * picker over that section's existing name, and rewrites its header line.
 *
 * Both are text edits through `replaceDocumentLineRange`, never DOM mutations
 * the preview keeps, so the panels, the text panel and the undo stack stay in
 * step — the rule `section-editing.ts` and `config-text-editing.ts` already
 * follow.
 *
 * The section-type list comes from `OLFenceRegistry`, so a fence added to the
 * language appears in the picker without an edit here, and a name the picker
 * can produce is always a name the parser accepts: the reader picks a header
 * and a number rather than typing notation, and a name already declared is
 * refused before the write rather than left as an invisible "Duplicate ol
 * part" marker.
 *
 * A rename — and a delete — carries the song's running order with it: every
 * `- Structure:` step naming the part is rewritten or removed in the *same*
 * document edit, so neither can silently leave `V1` pointing at a part that no
 * longer exists. That orphan is a real diagnostic ("Structure references
 * undeclared ol part", `document/validation.ts`) and one a preview-only reader
 * cannot see, which is why carrying the running order is not optional here.
 * Deleting is the one destructive gesture in the preview, so it asks first, and
 * the question names how many running-order steps go with the section.
 *
 * Markdown panel only. The lyric/presentation panel shares these delegated
 * listeners, so every lookup here is scoped to `refs.preview`.
 */

/** `  ```ol:Verse 1  ` → the ```` ```ol: ```` prefix and the header info. */
const FENCE_HEADER_LINE_RE = /^(\s*```ol:)([^\r\n]*?)[ \t]*$/;

/** `- Structure:   IV1CO` → prefix, field name, separator, value. */
const CONFIG_FIELD_LINE_RE = /^(\s*-\s*([^:]+):)([ \t]*)(.*)$/;

function splitLines(text) {
  return String(text ?? '')
    .replace(/\r\n?/g, '\n')
    .split('\n');
}

/**
 * Every section type the language defines, in registry order.
 *
 * `Config` is excluded: it is metadata, it is required, and exactly one of it
 * may exist — none of which the "add a section" gesture means.
 */
function getSectionTypeOptions() {
  return registry
    .getDefinitions()
    .filter((definition) => definition.header !== 'Config')
    .map((definition) => ({
      header: definition.header,
      allowsNumbering: Boolean(definition.allowsNumbering),
      allowsDuplicates: Boolean(definition.allowsDuplicateDeclaredPart?.()),
      description: definition.description || '',
    }));
}

/** The part names the document already declares — `Config` aside. */
function collectDeclaredSectionPartNames(markdown) {
  const partNames = new Set<string>();

  parseOpenLyricFences(markdown).forEach((fence) => {
    const partName = String(fence.parsedHeader?.partName ?? '');

    if (partName && fence.parsedHeader?.header !== 'Config') {
      partNames.add(partName);
    }
  });

  return partNames;
}

/**
 * The lowest index this header has no fence for yet.
 *
 * `Verse 1` and `Verse 2` present means the reader is offered `Verse 3` — the
 * number they were going to type anyway, and the one that cannot collide.
 */
function getNextFreeSectionIndexText(declaredPartNames, header, option) {
  if (!option?.allowsNumbering) {
    return '';
  }

  let index = 1;

  while (declaredPartNames.has(formatDeclaredPartName(header, String(index)))) {
    index += 1;
  }

  return String(index);
}

/**
 * The document edit that adds an empty section.
 *
 * It lands after the last fence in the document rather than at the click's own
 * position: a song grows at the end, and inserting under `Config` would build
 * every song backwards. Returns `null` when the name is not one the parser
 * accepts, so a picker that somehow produced nonsense writes nothing.
 */
function buildSectionInsertion(markdown, partName) {
  const parsedHeader = parseFenceHeader(String(partName ?? '').trim());

  if (!parsedHeader?.partName) {
    return null;
  }

  const lines = splitLines(markdown);
  const fences = parseOpenLyricFences(markdown);
  const lastFence = fences.length ? fences[fences.length - 1] : null;
  let anchorLineNumber = lastFence ? lastFence.endLineNumber : lines.length;

  if (!lastFence) {
    // Nothing recognizable in the document: append after its last written
    // line, so an empty draft does not gain a leading blank line.
    while (anchorLineNumber > 0 && !lines[anchorLineNumber - 1].trim()) {
      anchorLineNumber -= 1;
    }
  }

  const anchorLine = lines[anchorLineNumber - 1] ?? '';
  const nextLines = [`\`\`\`ol:${parsedHeader.partName}`, '```'];

  if (anchorLine.trim()) {
    nextLines.unshift('');
  }

  return {
    // `endLineNumber === startLineNumber - 1` is the insertion form: nothing
    // is consumed and the new lines land before `startLineNumber`.
    startLineNumber: anchorLineNumber + 1,
    endLineNumber: anchorLineNumber,
    nextLines,
    partName: parsedHeader.partName,
  };
}

/**
 * The fence's opening line as it should read once renamed, or `null`.
 *
 * `expectedPartName` is the name the control was rendered with; the line is
 * refused when it no longer declares it, so markup a re-render left behind
 * renames nothing. The indentation and the ```` ```ol: ```` prefix the document
 * already had are always preserved — a rename can only ever replace the header
 * info.
 */
function buildRenamedFenceHeaderLine(
  sourceLine,
  expectedPartName,
  nextPartName,
) {
  const headerMatch = String(sourceLine ?? '').match(FENCE_HEADER_LINE_RE);

  if (!headerMatch) {
    return null;
  }

  const currentHeader = parseFenceHeader(headerMatch[2].trim());

  if (!currentHeader?.partName || currentHeader.partName !== expectedPartName) {
    return null;
  }

  const nextHeader = parseFenceHeader(String(nextPartName ?? '').trim());

  if (!nextHeader?.partName || nextHeader.header === 'Config') {
    return null;
  }

  return `${headerMatch[1]}${nextHeader.partName}`;
}

/**
 * Where the `Config` fence declares `- Structure:`, if it declares it on one
 * line. A value continued onto a second line is left alone rather than
 * half-rewritten.
 */
function findConfigStructureFieldLine(markdown) {
  const configFence = parseOpenLyricFences(markdown).find(
    (fence) => fence.parsedHeader?.header === 'Config',
  );

  if (!configFence) {
    return null;
  }

  const lines = splitLines(markdown);

  for (
    let lineNumber = configFence.startLineNumber + 1;
    lineNumber < configFence.endLineNumber;
    lineNumber += 1
  ) {
    const fieldMatch = String(lines[lineNumber - 1] ?? '').match(
      CONFIG_FIELD_LINE_RE,
    );

    if (!fieldMatch) {
      continue;
    }

    if (normalizeConfigFieldName(fieldMatch[2].trim()) !== 'Structure') {
      continue;
    }

    const followingLine = String(lines[lineNumber] ?? '');

    if (
      lineNumber + 1 < configFence.endLineNumber &&
      followingLine.trim() &&
      !CONFIG_FIELD_LINE_RE.test(followingLine)
    ) {
      return null;
    }

    return {
      lineNumber,
      prefix: fieldMatch[1],
      separator: fieldMatch[3],
      valueText: fieldMatch[4].replace(/\s+$/, ''),
    };
  }

  return null;
}

/**
 * The `- Structure:` line with every step naming `partName` re-coded to
 * `nextPartName`, and how many steps that was.
 *
 * Each step keeps whatever followed its code in the source — a repeat suffix
 * such as `x2` — so renaming a part never quietly drops a repeat. A value the
 * structure parser cannot read, or a part with no structure code of its own, is
 * left untouched (`null`): a rename must not be the thing that rewrites a
 * `Structure` the reader has not fixed yet.
 */
function buildRenamedStructureLine(sourceLine, partName, nextPartName) {
  const fieldMatch = String(sourceLine ?? '').match(CONFIG_FIELD_LINE_RE);

  if (!fieldMatch) {
    return null;
  }

  if (normalizeConfigFieldName(fieldMatch[2].trim()) !== 'Structure') {
    return null;
  }

  const nextHeader = parseFenceHeader(String(nextPartName ?? '').trim());
  const nextDefinition = nextHeader
    ? STRUCTURE_DEFINITIONS_BY_HEADER.get(nextHeader.header)
    : null;

  if (!nextDefinition) {
    return null;
  }

  const parsedStructure = parseStructureValue(
    fieldMatch[4].replace(/\s+$/, ''),
  );

  if (parsedStructure.error) {
    return null;
  }

  const nextToken = `${nextDefinition.code}${
    nextDefinition.allowsNumbering ? nextHeader.indexText || '' : ''
  }`;
  const source = parsedStructure.text;
  let nextValue = '';
  let cursor = 0;
  let changedCount = 0;

  parsedStructure.steps.forEach((step) => {
    if (step.partName !== partName) {
      return;
    }

    const rawSuffix = String(step.rawText ?? '').slice(
      String(step.code ?? '').length + String(step.indexText ?? '').length,
    );

    nextValue += source.slice(cursor, step.startOffset) + nextToken + rawSuffix;
    cursor = step.endOffset;
    changedCount += 1;
  });

  if (!changedCount) {
    return null;
  }

  nextValue += source.slice(cursor);

  // The rewrite has to still be a `Structure` the parser reads the same way —
  // otherwise the rename would hand the reader a diagnostic instead of a song.
  const reparsedStructure = parseStructureValue(nextValue);

  if (reparsedStructure.error) {
    return null;
  }

  return {
    changedCount,
    line: `${fieldMatch[1]}${fieldMatch[3] || ' '}${nextValue}`,
  };
}

/**
 * The one document edit a rename is: the fence's opening line, plus the
 * `- Structure:` line when it names the part, and every line between them
 * written back unchanged.
 *
 * One range rather than two writes is the whole point — one user action stays
 * one undo step, and the document can never be left half-renamed.
 */
function buildSectionRenameEdit(
  markdown,
  headerLineNumber,
  partName,
  nextPartName,
) {
  const lines = splitLines(markdown);
  const headerLine = lines[headerLineNumber - 1];

  if (headerLine === undefined) {
    return null;
  }

  const nextHeaderLine = buildRenamedFenceHeaderLine(
    headerLine,
    partName,
    nextPartName,
  );

  if (nextHeaderLine === null) {
    return null;
  }

  const structureField = findConfigStructureFieldLine(markdown);
  const structureRewrite =
    structureField && structureField.lineNumber !== headerLineNumber
      ? buildRenamedStructureLine(
          lines[structureField.lineNumber - 1],
          partName,
          nextPartName,
        )
      : null;

  if (!structureField || !structureRewrite) {
    return {
      startLineNumber: headerLineNumber,
      endLineNumber: headerLineNumber,
      nextLines: [nextHeaderLine],
      structureStepCount: 0,
    };
  }

  const startLineNumber = Math.min(headerLineNumber, structureField.lineNumber);
  const endLineNumber = Math.max(headerLineNumber, structureField.lineNumber);
  const nextLines = lines.slice(startLineNumber - 1, endLineNumber);

  nextLines[headerLineNumber - startLineNumber] = nextHeaderLine;
  nextLines[structureField.lineNumber - startLineNumber] =
    structureRewrite.line;

  return {
    startLineNumber,
    endLineNumber,
    nextLines,
    structureStepCount: structureRewrite.changedCount,
  };
}

/** A step's repeat count as a number — `Cx2` is 2, a bare `C` is 1. */
function getStructureStepRepeatCount(step) {
  const repeatMatch = String(step?.repeatText ?? '').match(/^(\d+)x$/);

  return repeatMatch ? Number.parseInt(repeatMatch[1], 10) : 1;
}

/** How many `- Structure:` steps name `partName` right now. */
function countStructureStepsForPart(markdown, partName) {
  const structureField = findConfigStructureFieldLine(markdown);

  if (!structureField) {
    return 0;
  }

  const parsedStructure = parseStructureValue(structureField.valueText);

  if (parsedStructure.error) {
    return 0;
  }

  return parsedStructure.steps.filter((step) => step.partName === partName)
    .length;
}

/**
 * The `- Structure:` line with every step naming `partName` taken out, and how
 * many steps that was.
 *
 * The surviving steps are re-emitted from their parsed parts rather than
 * spliced out of the raw text, because removing a step can leave its two
 * neighbours identical and adjacent — `V1CV1` minus the `Chorus` is the verse
 * sung twice, which the notation spells `V1x2`, not `V1V1` (that is the
 * "cannot place X twice in a row" diagnostic). Merging sums the repeat counts,
 * so the song still runs the same number of times.
 *
 * An emptied value keeps the field declared (`- Structure:` with nothing after
 * it), the same thing clearing a free-text `Config` field does — and an empty
 * `Structure` is not a diagnostic, since the validator only checks the value
 * when there is one.
 */
function buildRemovedStructureLine(sourceLine, partName) {
  const fieldMatch = String(sourceLine ?? '').match(CONFIG_FIELD_LINE_RE);

  if (!fieldMatch) {
    return null;
  }

  if (normalizeConfigFieldName(fieldMatch[2].trim()) !== 'Structure') {
    return null;
  }

  const parsedStructure = parseStructureValue(
    fieldMatch[4].replace(/\s+$/, ''),
  );

  if (parsedStructure.error) {
    return null;
  }

  const survivingSteps = [];
  let removedStepCount = 0;

  parsedStructure.steps.forEach((step) => {
    if (step.partName === partName) {
      removedStepCount += 1;
      return;
    }

    const previousStep = survivingSteps[survivingSteps.length - 1];

    if (previousStep && previousStep.partName === step.partName) {
      previousStep.repeatCount += getStructureStepRepeatCount(step);
      return;
    }

    survivingSteps.push({
      partName: step.partName,
      code: step.code,
      indexText: step.definition?.allowsNumbering ? step.indexText || '' : '',
      repeatCount: getStructureStepRepeatCount(step),
    });
  });

  if (!removedStepCount) {
    return null;
  }

  const nextValue = survivingSteps
    .map(
      (step) =>
        `${step.code}${step.indexText}${
          step.repeatCount > 1 ? `x${step.repeatCount}` : ''
        }`,
    )
    .join('');
  const reparsedStructure = parseStructureValue(nextValue);

  if (
    reparsedStructure.error ||
    findAdjacentDuplicateStructureError(reparsedStructure.steps)
  ) {
    return null;
  }

  return {
    removedStepCount,
    line: `${fieldMatch[1]}${nextValue ? fieldMatch[3] || ' ' : ''}${nextValue}`,
  };
}

/**
 * The one document edit a delete is: the fence's whole source range, one blank
 * line beside it, and the `- Structure:` line when it names the part — with
 * every line between them written back unchanged.
 *
 * One range rather than two writes, for the same reason the rename uses one:
 * one user action stays one undo step, and the song can never be left with a
 * running order pointing at a section that is gone.
 *
 * Refuses (`null`) when the range no longer opens and closes this fence, so a
 * control left behind by stale markup deletes nothing.
 */
function buildSectionDeleteEdit(
  markdown,
  fenceStartLineNumber,
  fenceEndLineNumber,
  partName,
) {
  const lines = splitLines(markdown);
  const fenceStart = Math.trunc(Number(fenceStartLineNumber) || 0);
  const fenceEnd = Math.trunc(Number(fenceEndLineNumber) || 0);

  if (fenceStart < 1 || fenceEnd < fenceStart || fenceEnd > lines.length) {
    return null;
  }

  if (
    buildRenamedFenceHeaderLine(lines[fenceStart - 1], partName, partName) ===
    null
  ) {
    return null;
  }

  if (!/^\s*```\s*$/.test(lines[fenceEnd - 1])) {
    return null;
  }

  // One blank line goes with the fence, or deleting from the middle of a song
  // leaves a double gap behind. The one *before* is preferred, so a document
  // that ended in a newline still does.
  let removeStart = fenceStart;
  let removeEnd = fenceEnd;

  if (fenceStart > 1 && !lines[fenceStart - 2].trim()) {
    removeStart = fenceStart - 1;
  } else if (fenceEnd < lines.length && !lines[fenceEnd].trim()) {
    removeEnd = fenceEnd + 1;
  }

  const structureField = findConfigStructureFieldLine(markdown);
  const structureRewrite =
    structureField &&
    (structureField.lineNumber < removeStart ||
      structureField.lineNumber > removeEnd)
      ? buildRemovedStructureLine(
          lines[structureField.lineNumber - 1],
          partName,
        )
      : null;

  if (!structureField || !structureRewrite) {
    return {
      startLineNumber: removeStart,
      endLineNumber: removeEnd,
      nextLines: [],
      structureStepCount: 0,
    };
  }

  const startLineNumber = Math.min(removeStart, structureField.lineNumber);
  const endLineNumber = Math.max(removeEnd, structureField.lineNumber);
  const nextLines = [];

  for (
    let lineNumber = startLineNumber;
    lineNumber <= endLineNumber;
    lineNumber += 1
  ) {
    if (lineNumber >= removeStart && lineNumber <= removeEnd) {
      continue;
    }

    nextLines.push(
      lineNumber === structureField.lineNumber
        ? structureRewrite.line
        : lines[lineNumber - 1],
    );
  }

  return {
    startLineNumber,
    endLineNumber,
    nextLines,
    structureStepCount: structureRewrite.removedStepCount,
  };
}

/**
 * The section just before `partName` in the document, so focus has somewhere to
 * land once the card under the reader's pointer is gone.
 */
function getPrecedingSectionPartName(markdown, partName) {
  const sectionPartNames = parseOpenLyricFences(markdown)
    .filter((fence) => fence.parsedHeader?.header !== 'Config')
    .map((fence) => String(fence.parsedHeader?.partName ?? ''));
  const index = sectionPartNames.indexOf(partName);

  return index > 0 ? sectionPartNames[index - 1] : '';
}

/**
 * The second line of the confirmation — what else goes when this section does.
 *
 * Named rather than counted silently: removing a section quietly shortens the
 * running order, and a reader who never opens the text panel would have no
 * other way to find that out.
 */
function describeSectionDeletion(structureStepCount) {
  if (!structureStepCount) {
    return 'It is not in the running order, so nothing else changes.';
  }

  if (structureStepCount === 1) {
    return 'It is used once in the running order — that step will be removed too.';
  }

  return `It is used ${structureStepCount} times in the running order — those steps will be removed too.`;
}

function applyPreviewControllerSectionNamingMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    /**
     * The type/number picker both affordances are built from.
     *
     * A `<select>` of headers and a number field rather than a free-text box:
     * the reader is naming a section, not writing notation, and every name this
     * can produce is one `parseFenceHeader` accepts. The status line is what
     * turns a refusal into something actionable — it always says what the
     * resulting section will be called, or why that name cannot be used.
     */
    buildSectionNamePicker(
      this: any,
      {
        partName = '',
        excludePartName = '',
        idPrefix = 'ol-section-name',
      } = {},
    ) {
      const options = getSectionTypeOptions();
      const currentHeader = parseFenceHeader(String(partName ?? '').trim());
      const root = document.createElement('div');
      const typeLabel = document.createElement('label');
      const typeLabelText = document.createElement('span');
      const typeSelect = document.createElement('select');
      const indexLabel = document.createElement('label');
      const indexLabelText = document.createElement('span');
      const indexInput = document.createElement('input');
      const statusText = document.createElement('p');
      const statusId = `${idPrefix}-status-${Math.random()
        .toString(36)
        .slice(2, 10)}`;

      root.className = 'ol-preview-section-name';

      typeLabel.className = 'ol-preview-section-name__field';
      typeLabelText.className = 'ol-preview-section-name__field-label';
      typeLabelText.textContent = 'Section';
      typeSelect.className = 'ol-preview-section-name__type';
      typeSelect.setAttribute('data-preview-section-name-type', 'true');
      typeSelect.setAttribute('aria-label', 'Section type');
      typeSelect.setAttribute('aria-describedby', statusId);

      options.forEach((option) => {
        const optionElement = document.createElement('option');

        optionElement.value = option.header;
        optionElement.textContent = option.header;
        typeSelect.append(optionElement);
      });

      typeSelect.value = currentHeader?.header || 'Verse';

      if (!typeSelect.value && options.length) {
        typeSelect.value = options[0].header;
      }

      typeLabel.append(typeLabelText, typeSelect);

      indexLabel.className =
        'ol-preview-section-name__field ol-preview-section-name__field--index';
      indexLabelText.className = 'ol-preview-section-name__field-label';
      indexLabelText.textContent = 'Number';
      indexInput.className = 'ol-preview-section-name__index';
      indexInput.setAttribute('data-preview-section-name-index', 'true');
      indexInput.type = 'number';
      indexInput.min = '1';
      indexInput.step = '1';
      indexInput.inputMode = 'numeric';
      indexInput.autocomplete = 'off';
      indexInput.setAttribute('aria-label', 'Section number');
      indexInput.setAttribute('aria-describedby', statusId);
      indexInput.value = currentHeader?.indexText || '';
      indexLabel.append(indexLabelText, indexInput);

      statusText.className = 'ol-preview-section-name__status';
      statusText.id = statusId;
      statusText.setAttribute('role', 'status');

      root.append(typeLabel, indexLabel, statusText);

      const picker = {
        root,
        typeSelect,
        indexLabel,
        indexInput,
        statusText,
        excludePartName: String(excludePartName ?? ''),
        // Seeded once; changing the type re-seeds it with that type's next
        // free number, which is what a reader adding `Chorus` after `Verse 2`
        // expects to see.
        seededIndexText: currentHeader?.indexText || '',
        submitButton: null,
      };

      typeSelect.addEventListener('change', () => {
        picker.seededIndexText = '';
        this.refreshSectionNamePicker(picker, { reseedIndex: true });
      });
      indexInput.addEventListener('input', () => {
        this.refreshSectionNamePicker(picker);
      });

      return picker;
    },

    /** The part name the picker currently describes, or `''`. */
    readSectionNamePickerPartName(this: any, picker) {
      const header = String(picker?.typeSelect?.value ?? '').trim();

      if (!header) {
        return '';
      }

      const option = getSectionTypeOptions().find(
        (entry) => entry.header === header,
      );

      if (!option) {
        return '';
      }

      const indexText = option.allowsNumbering
        ? String(picker?.indexInput?.value ?? '').trim()
        : '';

      if (indexText && !/^[1-9]\d*$/.test(indexText)) {
        return '';
      }

      return formatDeclaredPartName(header, indexText);
    },

    /**
     * Re-derive everything the picker shows from its two controls: whether the
     * number applies at all, what the section will be called, and whether that
     * name can be used. Runs on every change, and once on open.
     */
    refreshSectionNamePicker(this: any, picker, { reseedIndex = false } = {}) {
      if (!picker) {
        return '';
      }

      const header = String(picker.typeSelect?.value ?? '').trim();
      const option = getSectionTypeOptions().find(
        (entry) => entry.header === header,
      );
      const declaredPartNames = collectDeclaredSectionPartNames(
        this.getCurrentValue(),
      );

      if (!option?.allowsNumbering) {
        picker.indexInput.value = '';
        picker.indexInput.disabled = true;
        picker.indexLabel.hidden = true;
      } else {
        picker.indexInput.disabled = false;
        picker.indexLabel.hidden = false;

        // Only ever on open and on a type change. An empty box is a choice —
        // `ol:Chorus` with no number is valid notation — so a reader who
        // clears it must not have it filled back in under their cursor.
        if (reseedIndex) {
          picker.indexInput.value =
            picker.seededIndexText ||
            getNextFreeSectionIndexText(declaredPartNames, header, option);
        }
      }

      const nextPartName = this.readSectionNamePickerPartName(picker);
      const isUnchanged =
        Boolean(nextPartName) && nextPartName === picker.excludePartName;
      const isTaken =
        Boolean(nextPartName) &&
        !isUnchanged &&
        !option?.allowsDuplicates &&
        declaredPartNames.has(nextPartName);

      if (!nextPartName) {
        picker.statusText.textContent =
          'Enter a section number of 1 or more, or leave it blank.';
      } else if (isTaken) {
        picker.statusText.textContent = `${nextPartName} is already in this song. Choose another number.`;
      } else if (isUnchanged) {
        picker.statusText.textContent = `This section is already called ${nextPartName}.`;
      } else {
        picker.statusText.textContent = `This section will be called ${nextPartName}.`;
      }

      const isValid = Boolean(nextPartName) && !isTaken && !isUnchanged;

      if (picker.submitButton instanceof HTMLButtonElement) {
        picker.submitButton.disabled = !isValid;
      }

      return isValid ? nextPartName : '';
    },

    ensureAddSectionPopup(this: any) {
      if (this.addSectionPopup) {
        return this.addSectionPopup;
      }

      const popup = document.createElement('div');

      popup.className =
        'ol-preview-declare-part-popup ol-preview-add-section-popup';
      popup.setAttribute('role', 'dialog');
      popup.setAttribute('aria-label', 'Add a lyric section');
      popup.tabIndex = -1;
      popup.hidden = true;
      popup.addEventListener('submit', this.handleAddSectionPopupSubmit);
      document.body.appendChild(popup);
      this.addSectionPopup = popup;
      return popup;
    },

    isAddSectionPopupElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(this.addSectionPopup?.contains(element))
      );
    },

    closeAddSectionPopup(this: any) {
      if (this.addSectionPopup) {
        this.addSectionPopup.hidden = true;
        this.addSectionPopup.replaceChildren();
        this.addSectionPopup.style.left = '';
        this.addSectionPopup.style.top = '';
      }

      this.activeAddSectionButton?.setAttribute?.('aria-expanded', 'false');
      this.activeAddSectionButton = null;
      this.addSectionPicker = null;
    },

    populateAddSectionPopup(this: any) {
      const popup = this.ensureAddSectionPopup();
      const form = document.createElement('form');
      const picker = this.buildSectionNamePicker({
        idPrefix: 'ol-add-section',
      });
      const hint = document.createElement('p');
      const actions = document.createElement('div');
      const submitButton = document.createElement('button');

      popup.replaceChildren();

      form.className = 'ol-preview-add-section__form';
      form.noValidate = true;

      hint.className = 'ol-preview-add-section__hint';
      hint.textContent =
        'Added at the end of the song. Use + on the Structure row to put it in the running order.';

      actions.className = 'ol-preview-add-section__actions';
      submitButton.className = 'ol-preview-add-section__submit';
      submitButton.type = 'submit';
      submitButton.textContent = 'Add section';
      actions.append(submitButton);

      picker.submitButton = submitButton;

      form.append(picker.root, hint, actions);
      popup.append(form);

      this.addSectionPicker = picker;
      this.refreshSectionNamePicker(picker, { reseedIndex: true });

      return popup;
    },

    showAddSectionPopup(this: any, triggerButton) {
      const popup = this.populateAddSectionPopup();

      this.activeAddSectionButton = triggerButton;
      triggerButton.setAttribute('aria-expanded', 'true');
      this.positionDeclarePartPopup(triggerButton, popup);

      // A `<select>` is not a text-entry control, so `focusElement` leaves it
      // alone on a touch-opened iOS popup — the tap-swallowing rule.
      this.focusElement(this.addSectionPicker?.typeSelect || popup, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });
    },

    handleAddSectionPopupSubmit(this: any, event) {
      if (!(event.target instanceof HTMLFormElement)) {
        return;
      }

      if (!this.isAddSectionPopupElement(event.target)) {
        return;
      }

      event.preventDefault();

      const partName = this.refreshSectionNamePicker(this.addSectionPicker);

      if (!partName) {
        return;
      }

      this.closeDeclarePartMenus();
      this.addPreviewSection(partName);
    },

    /**
     * Write a new, empty section into the document and hand the reader
     * straight into its lyrics.
     *
     * The section editor is opened on the fresh card rather than leaving an
     * empty box on screen: "add a verse" means "write a verse", and the
     * textarea is the sanctioned touch-iOS auto-focus.
     */
    addPreviewSection(this: any, partName) {
      if (!this.canEditPreviewSections()) {
        return false;
      }

      const insertion = buildSectionInsertion(this.getCurrentValue(), partName);

      if (!insertion) {
        return false;
      }

      const applied = replaceDocumentLineRange(
        insertion.startLineNumber,
        insertion.endLineNumber,
        insertion.nextLines,
      );

      if (!applied) {
        return false;
      }

      const trigger = this.getPreviewSectionEditorTrigger(
        createPreviewTargetId(insertion.partName),
      );

      if (!(trigger instanceof HTMLElement)) {
        return true;
      }

      trigger
        .closest('.ol-preview-fence')
        ?.scrollIntoView?.({ block: 'center', inline: 'nearest' });
      this.openPreviewSectionEditor(trigger);

      return true;
    },

    ensureDeleteSectionPopup(this: any) {
      if (this.deleteSectionPopup) {
        return this.deleteSectionPopup;
      }

      const popup = document.createElement('div');

      popup.className =
        'ol-preview-declare-part-popup ol-preview-delete-section-popup';
      popup.setAttribute('role', 'dialog');
      popup.setAttribute('aria-label', 'Delete section');
      popup.tabIndex = -1;
      popup.hidden = true;
      popup.addEventListener('click', this.handleDeleteSectionPopupClick);
      document.body.appendChild(popup);
      this.deleteSectionPopup = popup;
      return popup;
    },

    isDeleteSectionPopupElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(this.deleteSectionPopup?.contains(element))
      );
    },

    closeDeleteSectionPopup(this: any) {
      if (this.deleteSectionPopup) {
        this.deleteSectionPopup.hidden = true;
        this.deleteSectionPopup.replaceChildren();
        this.deleteSectionPopup.style.left = '';
        this.deleteSectionPopup.style.top = '';
      }

      this.activeDeleteSectionButton?.setAttribute?.('aria-expanded', 'false');
      this.activeDeleteSectionButton = null;
      this.pendingSectionDelete = null;
    },

    populateDeleteSectionPopup(this: any, { partName, structureStepCount }) {
      const popup = this.ensureDeleteSectionPopup();
      const question = document.createElement('p');
      const detail = document.createElement('p');
      const actions = document.createElement('div');
      const confirmButton = document.createElement('button');
      const cancelButton = document.createElement('button');

      popup.replaceChildren();

      question.className = 'ol-preview-delete-section__question';
      question.textContent = `Delete ${partName}?`;

      detail.className = 'ol-preview-delete-section__detail';
      detail.textContent = describeSectionDeletion(structureStepCount);

      actions.className = 'ol-preview-delete-section__actions';

      confirmButton.className = 'ol-preview-delete-section__confirm';
      confirmButton.type = 'button';
      confirmButton.setAttribute(
        'data-preview-action',
        'confirm-delete-section',
      );
      confirmButton.textContent = 'Delete';

      cancelButton.className = 'ol-preview-delete-section__cancel';
      cancelButton.type = 'button';
      cancelButton.setAttribute('data-preview-action', 'cancel-delete-section');
      cancelButton.textContent = 'Cancel';

      actions.append(confirmButton, cancelButton);
      popup.append(question, detail, actions);

      return popup;
    },

    /**
     * Ask before removing a section.
     *
     * Destructive, one click away, and it shortens the running order as a side
     * effect — so the question names the section and says how many
     * `- Structure:` steps go with it. The edit is built here too, before the
     * question is asked: markup whose lines no longer open and close this fence
     * must not get as far as a confirmation.
     */
    showDeleteSectionPopup(this: any, trigger) {
      if (!(trigger instanceof HTMLElement)) {
        return false;
      }

      if (!(refs.preview instanceof HTMLElement)) {
        return false;
      }

      if (!refs.preview.contains(trigger) || !this.canEditPreviewSections()) {
        return false;
      }

      const partName = trigger.getAttribute('data-preview-part-name') || '';
      const startLineNumber = Number(
        trigger.getAttribute('data-preview-fence-start-line'),
      );
      const endLineNumber = Number(
        trigger.getAttribute('data-preview-fence-end-line'),
      );

      if (!partName) {
        return false;
      }

      const markdown = this.getCurrentValue();

      if (
        !buildSectionDeleteEdit(
          markdown,
          startLineNumber,
          endLineNumber,
          partName,
        )
      ) {
        return false;
      }

      this.closePreviewSectionRenameEditor?.({ focusTrigger: false });

      const popup = this.populateDeleteSectionPopup({
        partName,
        structureStepCount: countStructureStepsForPart(markdown, partName),
      });

      this.pendingSectionDelete = {
        partName,
        startLineNumber,
        endLineNumber,
        previousPartName: getPrecedingSectionPartName(markdown, partName),
      };
      this.activeDeleteSectionButton = trigger;
      trigger.setAttribute('aria-expanded', 'true');
      this.positionDeclarePartPopup(trigger, popup);

      // Cancel, not Delete: a stray Enter on a confirmation a reader opened by
      // accident must not be the thing that removes their verse. A button is
      // also left alone on a touch-opened iOS popup, which is the rule here.
      this.focusElement(
        popup.querySelector('[data-preview-action="cancel-delete-section"]') ||
          popup,
        { preventScroll: true, skipTouchIosForButtons: true },
      );

      return true;
    },

    handleDeleteSectionPopupClick(this: any, event) {
      const eventTarget = this.getEventTargetElement(event);
      const action = eventTarget?.closest(
        '[data-preview-action="confirm-delete-section"], [data-preview-action="cancel-delete-section"]',
      );

      if (!action || !this.isDeleteSectionPopupElement(action)) {
        return;
      }

      event.preventDefault();

      if (
        action.getAttribute('data-preview-action') === 'cancel-delete-section'
      ) {
        const trigger = this.activeDeleteSectionButton;

        this.closeDeclarePartMenus();
        this.focusElement(trigger, {
          preventScroll: true,
          skipTouchIosForButtons: true,
        });
        return;
      }

      this.confirmPreviewSectionDelete();
    },

    /**
     * Remove the section the confirmation named.
     *
     * The edit is rebuilt from the document as it is *now* rather than from
     * anything cached when the question was asked, so a change behind the open
     * confirmation refuses the delete instead of removing the wrong lines.
     */
    confirmPreviewSectionDelete(this: any) {
      const pendingDelete = this.pendingSectionDelete;

      if (!pendingDelete || !this.canEditPreviewSections()) {
        return false;
      }

      const deleteEdit = buildSectionDeleteEdit(
        this.getCurrentValue(),
        pendingDelete.startLineNumber,
        pendingDelete.endLineNumber,
        pendingDelete.partName,
      );

      if (!deleteEdit) {
        this.closeDeclarePartMenus();
        return false;
      }

      const previewScrollTop =
        refs.preview instanceof HTMLElement ? refs.preview.scrollTop : 0;

      // Closed before the write: applying it re-renders the panel, which takes
      // the card this popup is anchored to with it.
      this.closeDeclarePartMenus();

      const applied = replaceDocumentLineRange(
        deleteEdit.startLineNumber,
        deleteEdit.endLineNumber,
        deleteEdit.nextLines,
      );

      if (!applied) {
        return false;
      }

      if (refs.preview instanceof HTMLElement) {
        refs.preview.scrollTop = previewScrollTop;
      }

      // The card that had focus is gone, so focus goes to the section above it
      // — or, for the first section, to the control that adds one back.
      this.focusElement(
        this.getPreviewSectionDeleteTrigger(pendingDelete.previousPartName) ||
          this.getPreviewAddSectionTrigger(),
        { preventScroll: true, skipTouchIosForButtons: true },
      );

      return true;
    },

    /** The bin for one part, looked up after a re-render replaced it. */
    getPreviewSectionDeleteTrigger(this: any, partName) {
      if (!partName || !(refs.preview instanceof HTMLElement)) {
        return null;
      }

      return (
        Array.from(
          refs.preview.querySelectorAll(
            '[data-preview-action="delete-section"]',
          ),
        ).find(
          (element) =>
            element.getAttribute('data-preview-part-name') === partName,
        ) || null
      );
    },

    getPreviewAddSectionTrigger(this: any) {
      if (!(refs.preview instanceof HTMLElement)) {
        return null;
      }

      return refs.preview.querySelector(
        '[data-preview-action="toggle-add-section-menu"]',
      );
    },

    /**
     * A full or incremental re-render replaces the markup an open rename form
     * lived in. Nothing is recoverable at that point, so drop the reference
     * rather than leave `Save` pointing at a detached control.
     */
    syncPreviewSectionRenameEditorState(this: any) {
      const renameEditor = this.previewSectionRenameEditor;

      if (!renameEditor) {
        return;
      }

      if (!renameEditor.form?.isConnected) {
        this.previewSectionRenameEditor = null;
      }
    },

    /** The rename tag for one part, looked up after a re-render replaced it. */
    getPreviewSectionRenameTrigger(this: any, partName) {
      if (!partName || !(refs.preview instanceof HTMLElement)) {
        return null;
      }

      return (
        Array.from(
          refs.preview.querySelectorAll(
            '[data-preview-action="edit-section-title"]',
          ),
        ).find(
          (element) =>
            element.getAttribute('data-preview-part-name') === partName,
        ) || null
      );
    },

    openPreviewSectionRenameEditor(this: any, trigger) {
      if (!(trigger instanceof HTMLElement)) {
        return false;
      }

      if (!(refs.preview instanceof HTMLElement)) {
        return false;
      }

      if (!refs.preview.contains(trigger) || !this.canEditPreviewSections()) {
        return false;
      }

      const fence = trigger.closest('.ol-preview-fence');
      const summary = fence?.querySelector('.ol-preview-fence__summary');

      if (
        !(fence instanceof HTMLElement) ||
        !(summary instanceof HTMLElement)
      ) {
        return false;
      }

      const partName = trigger.getAttribute('data-preview-part-name') || '';
      const headerLineNumber = Number(
        trigger.getAttribute('data-preview-header-line'),
      );

      if (
        !partName ||
        !Number.isInteger(headerLineNumber) ||
        headerLineNumber < 1
      ) {
        return false;
      }

      // The line the control points at no longer declares this part, so the
      // markup is stale — renaming over it would rewrite something else.
      const sourceLines = readDocumentLineRange(
        headerLineNumber,
        headerLineNumber,
      );

      if (
        !sourceLines?.length ||
        buildRenamedFenceHeaderLine(sourceLines[0], partName, partName) === null
      ) {
        return false;
      }

      this.closePreviewSectionRenameEditor({ focusTrigger: false });
      this.closePreviewSectionEditor?.({ focusTrigger: false });

      const form = document.createElement('form');
      const picker = this.buildSectionNamePicker({
        partName,
        excludePartName: partName,
        idPrefix: 'ol-rename-section',
      });
      const actions = document.createElement('div');
      const saveButton = document.createElement('button');
      const cancelButton = document.createElement('button');

      form.className = 'ol-preview-fence__rename-editor';
      form.setAttribute('data-preview-section-rename-editor', 'true');
      form.noValidate = true;

      actions.className = 'ol-preview-fence__editor-actions';
      saveButton.className =
        'ol-preview-fence__editor-button ol-preview-fence__editor-button--save';
      saveButton.type = 'submit';
      saveButton.setAttribute('data-preview-action', 'save-section-title');
      saveButton.textContent = 'Rename';
      cancelButton.className = 'ol-preview-fence__editor-button';
      cancelButton.type = 'button';
      cancelButton.setAttribute('data-preview-action', 'cancel-section-title');
      cancelButton.textContent = 'Cancel';
      actions.append(saveButton, cancelButton);

      picker.submitButton = saveButton;
      form.append(picker.root, actions);

      if (fence instanceof HTMLDetailsElement) {
        fence.open = true;
      }

      // After the summary rather than inside it: a `<summary>` swallows clicks
      // and keystrokes as "toggle this card", which a select and a number
      // field cannot survive.
      summary.after(form);

      trigger.setAttribute('aria-expanded', 'true');
      fence.dataset.olSectionRenameOpen = 'true';

      this.previewSectionRenameEditor = {
        fence,
        form,
        headerLineNumber,
        partName,
        picker,
      };

      this.refreshSectionNamePicker(picker);

      form.addEventListener('submit', this.handlePreviewSectionRenameSubmit);
      form.addEventListener('keydown', this.handlePreviewSectionRenameKeyDown);

      this.focusElement(picker.typeSelect, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });

      return true;
    },

    /**
     * Take one rename form back out of the card.
     *
     * Idempotent, and safe on markup a re-render has already detached — which
     * is how `savePreviewSectionRenameEditor` can run it either side of the
     * write without caring whether the panel re-rendered in between.
     */
    teardownPreviewSectionRenameEditor(this: any, renameEditor, focusPartName) {
      if (!renameEditor) {
        return null;
      }

      const { fence, form, partName } = renameEditor;

      form?.removeEventListener(
        'submit',
        this.handlePreviewSectionRenameSubmit,
      );
      form?.removeEventListener(
        'keydown',
        this.handlePreviewSectionRenameKeyDown,
      );
      form?.remove();

      if (fence instanceof HTMLElement) {
        delete fence.dataset.olSectionRenameOpen;
      }

      // After a re-render the card is new markup — and after a *successful*
      // rename it is also under a new name, so the control to hand focus back
      // to is looked up by the name the document now has.
      const trigger =
        this.getPreviewSectionRenameTrigger(focusPartName || partName) ||
        fence?.querySelector?.('[data-preview-action="edit-section-title"]') ||
        null;

      trigger?.setAttribute?.('aria-expanded', 'false');

      return trigger;
    },

    closePreviewSectionRenameEditor(this: any, { focusTrigger = true } = {}) {
      const renameEditor = this.previewSectionRenameEditor;

      if (!renameEditor) {
        return false;
      }

      this.previewSectionRenameEditor = null;

      const trigger = this.teardownPreviewSectionRenameEditor(renameEditor);

      if (focusTrigger) {
        this.focusElement(trigger, {
          preventScroll: true,
          skipTouchIosForButtons: true,
        });
      }

      return true;
    },

    /** Write the picked name back over the fence's opening line. */
    savePreviewSectionRenameEditor(this: any) {
      const renameEditor = this.previewSectionRenameEditor;

      if (!renameEditor) {
        return false;
      }

      if (!renameEditor.form?.isConnected) {
        this.previewSectionRenameEditor = null;
        return false;
      }

      const nextPartName = this.refreshSectionNamePicker(renameEditor.picker);

      if (!nextPartName) {
        return false;
      }

      const renameEdit = buildSectionRenameEdit(
        this.getCurrentValue(),
        renameEditor.headerLineNumber,
        renameEditor.partName,
        nextPartName,
      );

      // The document moved under the open form and that line is no longer this
      // section. Close rather than rename something else.
      if (!renameEdit) {
        this.closePreviewSectionRenameEditor({ focusTrigger: true });
        return false;
      }

      const previewScrollTop =
        refs.preview instanceof HTMLElement ? refs.preview.scrollTop : 0;

      // Dropped before the write: applying it re-renders the panel
      // synchronously, which takes this form's DOM with it.
      this.previewSectionRenameEditor = null;

      const applied = replaceDocumentLineRange(
        renameEdit.startLineNumber,
        renameEdit.endLineNumber,
        renameEdit.nextLines,
      );

      if (!applied) {
        this.previewSectionRenameEditor = renameEditor;
        return false;
      }

      // The write re-renders the panel, which usually takes this form with it
      // — but the incremental render paths patch only part of the panel, so the
      // teardown runs unconditionally rather than relying on that.
      const trigger = this.teardownPreviewSectionRenameEditor(
        renameEditor,
        nextPartName,
      );

      // A re-render resets the panel's scroll and blurs whatever was focused.
      // Both are put back so renaming a verse does not throw the reader to the
      // top of a long song.
      if (refs.preview instanceof HTMLElement) {
        refs.preview.scrollTop = previewScrollTop;
      }

      this.focusElement(trigger, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });

      return true;
    },

    handlePreviewSectionRenameSubmit(this: any, event) {
      event.preventDefault();
      this.savePreviewSectionRenameEditor();
    },

    handlePreviewSectionRenameKeyDown(this: any, event) {
      if (event.key !== 'Escape') {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      this.closePreviewSectionRenameEditor({ focusTrigger: true });
    },

    isPreviewSectionRenameElement(this: any, element) {
      if (!(element instanceof Element)) {
        return false;
      }

      return Boolean(element.closest('.ol-preview-fence__rename-editor'));
    },
  });
}

export {
  applyPreviewControllerSectionNamingMethods,
  buildRemovedStructureLine,
  buildRenamedFenceHeaderLine,
  buildRenamedStructureLine,
  buildSectionDeleteEdit,
  buildSectionInsertion,
  buildSectionRenameEdit,
  collectDeclaredSectionPartNames,
  countStructureStepsForPart,
  describeSectionDeletion,
  findConfigStructureFieldLine,
  getNextFreeSectionIndexText,
  getPrecedingSectionPartName,
  getSectionTypeOptions,
};
