import type { Editor } from './Editor.ts';
import { defaultLoadMonacoResources } from './internal/monaco-boot.ts';
import { OpenLyricComponent } from './internal/OpenLyricComponent.ts';
import type { OpenLyricPreviewComponent } from './internal/OpenLyricPreviewComponent.ts';
import { ensureDashboardShellStylesInjected } from './internal/shell-styles.ts';
import { isOpenLyricTheme } from './internal/theme.ts';
import type {
  OpenLyricComponentOptions,
  OpenLyricSurface,
  OpenLyricTheme,
} from './internal/types.ts';
import { installDashboardShellMarkup } from '../html/install-dashboard-shell-markup.ts';
import {
  linkFragmentIds,
  OPEN_LYRIC_SCOPE_CLASS,
} from '../html/markup-fragments.ts';
import { registerBuiltInEditorPlugins } from '../../plugins/default-plugins.ts';
import { OpenLyricEditorApplication } from '../../plugins/OpenLyric/OpenLyricEditorApplication.ts';
import { shouldRegisterBuiltInOpenLyricPlugin } from '../scripts/page-config.ts';
import {
  getCurrentValue,
  markDirty,
  refreshElementRefs,
  refs,
  state,
} from '../scripts/shared.ts';

/** A draft the `loadValue` hook may return (a bare string works too). */
export interface OpenLyricDashboardDraft {
  content: string;
  fileName?: string;
  sharedDocumentDate?: string;
}

/** Extra document metadata handed to the `onValueChange`/`saveValue` hooks. */
export interface OpenLyricDashboardDraftContext {
  fileName: string;
  sharedDocumentDate: string;
}

export type OpenLyricDashboardLoadValue = () =>
  | Promise<OpenLyricDashboardDraft | string | null>
  | OpenLyricDashboardDraft
  | string
  | null;

export type OpenLyricDashboardOnValueChange = (
  value: string,
  context: OpenLyricDashboardDraftContext,
) => void | Promise<void>;

export type OpenLyricDashboardSaveValue = (
  value: string,
  context: OpenLyricDashboardDraftContext,
) => void | Promise<void>;

/** Options for {@link OpenLyricDashboard.reset}. */
export interface OpenLyricDashboardResetOptions {
  /**
   * Ask the user to confirm before discarding, exactly as the topbar Reset
   * button does. Off by default: a programmatic reset is the host's own
   * command, not a stray click, so it has already decided.
   */
  confirmFirst?: boolean;
}

export interface OpenLyricDashboardOptions extends OpenLyricComponentOptions {
  /**
   * Show web-only chrome (`gif` info disclosure, share-link menu entry,
   * topbar theme toggle).
   */
  isWeb?: boolean;
  /** Injectable persistence backend — replaces the localStorage drafts. */
  loadValue?: OpenLyricDashboardLoadValue;
  onValueChange?: OpenLyricDashboardOnValueChange;
  /** Explicit user save (Ctrl/Cmd+S, Save) — replaces the disk download. */
  saveValue?: OpenLyricDashboardSaveValue;
}

/**
 * The topbar row that hosts the numbered host slots, and the class every slot
 * element carries. Both live in `html/dashboard-shell.html`; the row is
 * created on demand for a host that inlined a shell without one.
 */
const SLOT_HOST_CLASS = 'ol-db-header-slots';
const SLOT_CLASS = 'ol-db-header-slot';

/** The shell panels the dashboard exposes as `is…Opened` accessors. */
type DashboardPanelKey = 'editor' | 'preview' | 'openLyric';

/**
 * The field a panel reports its visibility under — the same name in `state` as
 * in `getEffectivePanelVisibility()`.
 */
type PanelVisibilityKey =
  'editorVisible' | 'previewVisible' | 'openLyricVisible';

/**
 * Panel key → the two `ShellLayoutController` members that own it: the setter
 * (each carries its own "never leave all three hidden" rescue rule, then
 * reconciles and persists the whole shell) and the field its effective
 * visibility comes back under. One table so the three accessor pairs delegate
 * through one helper instead of three copies of it.
 */
const PANEL_CONTROLLER_MEMBERS: Record<
  DashboardPanelKey,
  { setter: string; visibleKey: PanelVisibilityKey }
> = {
  editor: { setter: 'setEditorVisible', visibleKey: 'editorVisible' },
  preview: { setter: 'setPreviewVisible', visibleKey: 'previewVisible' },
  openLyric: { setter: 'setOpenLyricVisible', visibleKey: 'openLyricVisible' },
};

/** The shared document, coerced — the app's own state is untyped JS. */
function currentDocumentValue(): string {
  return String(getCurrentValue() ?? '');
}

/** The app's live theme, narrowed to the values the component contract has. */
function resolveAppTheme(): OpenLyricTheme {
  return isOpenLyricTheme(state.theme) ? state.theme : 'light';
}

/** At most one dashboard may wrap the page-level application at a time. */
let activeWrappedDashboard: OpenLyricDashboard | null = null;

function registerActiveDashboard(dashboard: OpenLyricDashboard): void {
  activeWrappedDashboard = dashboard;
}

/**
 * The dashboard currently wrapping the page application, if any.
 *
 * This is the sanctioned way to reach a running dashboard from code that did
 * not compose it (debugging, tests, late-loading integrations) — the page
 * entry publishes nothing to `globalThis`. Module scope, not global scope:
 * the caller must import this module to see it.
 */
export function getActiveOpenLyricDashboard(): OpenLyricDashboard | null {
  return activeWrappedDashboard;
}

/**
 * `OpenLyricDashboard` — the shell component (`gdb`) from the redesign doc,
 * in its **wrap phase**: it drives the existing composition root
 * (`OpenLyricEditorApplication`) through the standalone component contract
 * (options bag, `mount()` → `ready`, unified `on()` events, `theme`,
 * `loadValue`/`onValueChange`/`saveValue` injection, `isWeb` chrome gating).
 *
 * The page entries (`editor/main-open-lyric.ts`, `editor/main-editor.ts`)
 * are the canonical consumers — the live app boots through this class, so
 * the pages themselves are the integration examples.
 *
 * Wrap-phase constraints (all documented in the components README):
 * - The shell markup must be inside `container` before boot: the dashboard
 *   installs it from `html/dashboard-shell.html` when absent, and otherwise
 *   adopts whatever shell the host inlined, rather than building panels from
 *   the standalone components.
 * - Single instance: the wrapped application uses page-global state.
 * - `unmount()` is unsupported (the app has no teardown yet); `destroy()`
 *   detaches the dashboard facade — bridges, hooks, markers — and leaves the
 *   underlying app running.
 */
export class OpenLyricDashboard extends OpenLyricComponent {
  /**
   * Install the shell markup this component owns — the shell root: the
   * topbar, the panel host with its three panel mounts, and every app-level
   * dialog — from `html/dashboard-shell.html`, then refresh the app's
   * captured element refs.
   *
   * The counterpart to `Editor.installShellMarkup()` and friends, and the
   * one that must run FIRST: their `data-ol-mount` placeholders live inside
   * this fragment. It targets a `<template data-ol-mount="dashboardShell">`
   * placeholder when the page has one — which is all any app page ships —
   * otherwise appends to `container`; either way it is skipped when the shell
   * root already exists, so a host with a shell of its own is untouched.
   *
   * `mount()` calls this too, so a host that composes nothing but a
   * dashboard needs no separate call.
   *
   * `includeRawTextImport` opts the page into the Parse-from-Raw-Text action
   * and its dialog — the same per-page opt-in shape as
   * `OpenLyricMarkdownManager.installShellMarkup({ includeDocxExport })`. The
   * full shells pass it; `main-editor.ts` leaves it off.
   */
  static installShellMarkup(
    options: {
      container?: HTMLElement | null;
      includeRawTextImport?: boolean;
    } = {},
  ): void {
    installDashboardShellMarkup(options);
    refreshElementRefs();
  }

  /**
   * Link the stylesheets the dashboard shell owns — the page-level theme
   * tokens and loading splash (`theme.scss`), the shell chrome
   * (`shell.scss`), the app-level dialogs (`dialogs.scss`), and the
   * narrow-viewport overrides (`responsive.scss`) — into `document.head`,
   * the CSS counterpart of {@link installShellMarkup}.
   *
   * The page entries call one `installShellStyle()` per composed surface
   * class, this one first, so the HTML pages ship no
   * `<link rel="stylesheet">` at all. The sheets are shared with the other
   * surfaces' statics: each link is injected once, keyed by element id, and
   * always in canonical cascade order (see `internal/shell-styles.ts`).
   * The preview render sheet is not here — it comes with
   * `OpenLyric.installShellStyle()` / `OpenLyricMarkdownManager.installShellStyle()`,
   * exactly as those classes own their panels' markup.
   */
  static installShellStyle(): void {
    ensureDashboardShellStylesInjected();
  }

  readonly surface: OpenLyricSurface = 'dashboard';

  /** Injectable persistence hooks; may also be passed as options. */
  loadValue: OpenLyricDashboardLoadValue | null = null;
  onValueChange: OpenLyricDashboardOnValueChange | null = null;
  /**
   * The **explicit save command** — Ctrl/Cmd+S over the app, either topbar
   * Save button (the overflow menu's and the document-actions group's), or
   * Save in the editor tools menu. Assign it and the app stops downloading a
   * `.md` file and hands the document to this hook instead; leave it unset
   * and the built-in save-to-disk stays exactly as it is.
   *
   * Distinct from {@link onValueChange}, which is the *draft* path and fires
   * on every edit. This one fires only when the user asked to save. The
   * signature is identical, so a host that wants both can assign the same
   * function to each. "Download" (the menu entry that prompts for a file
   * name) is a separate intent and keeps writing a file either way.
   */
  saveValue: OpenLyricDashboardSaveValue | null = null;

  private openLyricRef: OpenLyricPreviewComponent | null = null;
  private openLyricMarkdownManagerRef: OpenLyricPreviewComponent | null = null;
  private editorRef: Editor | null = null;
  private isWebValue = true;
  /**
   * Panel visibility the host asked for before the app booted, keyed by panel.
   * `layoutController.loadPreferences()` runs inside `app.initialize()` and
   * would overwrite anything applied earlier, so these wait for it — see
   * {@link applyPendingPanelVisibility}.
   */
  private readonly pendingPanelVisibility: Partial<
    Record<DashboardPanelKey, boolean>
  > = {};
  /** True once that drain has run: panel writes go straight through after it. */
  private isApplicationBooted = false;
  private readonly explicitTheme: OpenLyricTheme | null;
  private applicationInstance: any = null;
  private lastValueText = '';
  private destroying = false;
  /** Undo functions for every patch the mount installed, LIFO. */
  private readonly patchRestorers: Array<() => void> = [];
  /** Topbar slots this dashboard created (see {@link getSlot}), to remove on teardown. */
  private readonly ownedSlots: HTMLDivElement[] = [];

  constructor(options: OpenLyricDashboardOptions = {}) {
    super(options);
    // Only an explicitly passed theme overrides the app's own preference
    // resolution (stored preference → system theme) after boot.
    this.explicitTheme = isOpenLyricTheme(options.theme) ? options.theme : null;
    this.isWebValue = options.isWeb !== false;
    if (typeof options.loadValue === 'function') {
      this.loadValue = options.loadValue;
    }
    if (typeof options.onValueChange === 'function') {
      this.onValueChange = options.onValueChange;
    }
    if (typeof options.saveValue === 'function') {
      this.saveValue = options.saveValue;
    }
  }

  /* ---------------------------- public surface --------------------------- */

  /**
   * The wrapped composition root (lazily constructed). An escape hatch for
   * hosts/tests that need app internals the component contract does not
   * cover yet; prefer the dashboard members where they exist.
   */
  get application(): any {
    if (!this.applicationInstance) {
      this.assertNotDestroyed();
      this.applicationInstance = new OpenLyricEditorApplication({
        // Monaco belongs to the editor component; this indirection keeps the
        // lookup lazy (see `loadMonacoResources`).
        loadMonacoResources: () => this.loadMonacoResources(),
      });
    }
    return this.applicationInstance;
  }

  /**
   * The owned lyric preview (`glpp`). Assign a `new OpenLyric()` before
   * `mount()`; the dashboard mounts it in adopt mode on the real
   * `#openLyricPreview` panel, and the app's full re-renders flow through it.
   */
  get openLyric(): OpenLyricPreviewComponent | null {
    return this.openLyricRef;
  }

  set openLyric(next: OpenLyricPreviewComponent | null) {
    if (this.isMounted) {
      throw new Error('Assign openLyric before mount().');
    }
    this.openLyricRef = next ?? null;
  }

  /** The owned markdown preview (`gmp`); same contract as {@link openLyric}. */
  get openLyricMarkdownManager(): OpenLyricPreviewComponent | null {
    return this.openLyricMarkdownManagerRef;
  }

  set openLyricMarkdownManager(next: OpenLyricPreviewComponent | null) {
    if (this.isMounted) {
      throw new Error('Assign openLyricMarkdownManager before mount().');
    }
    this.openLyricMarkdownManagerRef = next ?? null;
  }

  /**
   * The owned editor (`gep`) — the page's editor composition. Assign a
   * `new Editor()` with its plugins attached before `mount()`. Wrap phase:
   * the attached plugin set is the composition manifest deciding which
   * built-in shell plugins register before boot (`editor.html` composes
   * transcript; `open-lyric.html` adds the Open Lyric notation plugin), and
   * after boot the instance becomes a live facade over the
   * application's editor surface — `value` reads/writes, `focusRange`, the
   * Monaco getters, and `change` events all work against the real surface.
   */
  get editor(): Editor | null {
    return this.editorRef;
  }

  set editor(next: Editor | null) {
    if (this.isMounted) {
      throw new Error('Assign editor before mount().');
    }
    this.editorRef = next ?? null;
  }

  /**
   * A host-owned slot in the dashboard topbar, keyed by number.
   *
   * The first call for a number appends a `<div data-slot="N">` to the
   * topbar's slot row (`.ol-db-header-slots`, left of the Reset/Save pair) and
   * returns it; every later call for the same number returns that same
   * element, so a host can call it from anywhere without tracking the handle:
   *
   * ```ts
   * dashboard.getSlot(0).innerHTML = '<button class="btn btn-sm">Sync</button>';
   * ```
   *
   * The element is the host's to fill and empty — the dashboard only
   * guarantees identity, placement and DOM order (slots sort by number, not by
   * the order they were asked for). A slot already present in the host's own
   * shell markup is adopted rather than duplicated; slots this dashboard
   * created are removed again on `destroy()`.
   *
   * Requires the shell markup to be installed (i.e. after
   * `OpenLyricDashboard.installShellMarkup()` or `mount()`).
   */
  getSlot(slotNumber: number): HTMLDivElement {
    this.assertNotDestroyed();
    if (!Number.isInteger(slotNumber) || slotNumber < 0) {
      throw new Error(
        `getSlot() expects a non-negative integer slot number; got ${JSON.stringify(slotNumber)}.`,
      );
    }

    const host = this.resolveSlotHost();
    const selector = `[data-slot="${slotNumber}"]`;
    const existing = host.querySelector(selector);
    if (existing instanceof HTMLDivElement) {
      return existing;
    }

    const slot = document.createElement('div');
    slot.className = SLOT_CLASS;
    slot.dataset.slot = String(slotNumber);
    // Keep the row in slot order however the host asked for them.
    const successor = Array.from(host.children).find((child) => {
      const value = Number((child as HTMLElement).dataset?.slot);
      return Number.isInteger(value) && value > slotNumber;
    });
    host.insertBefore(slot, successor ?? null);
    this.ownedSlots.push(slot);
    return slot;
  }

  get isWeb(): boolean {
    return this.isWebValue;
  }

  set isWeb(next: boolean) {
    this.isWebValue = Boolean(next);
    if (this.isMounted) {
      this.applyWebOnlyChrome();
    }
  }

  /**
   * Whether the Monaco editor panel is showing — the topbar's editor toggle as
   * an accessor, and it behaves like one: the write goes through
   * `ShellLayoutController.setEditorVisible()`, so the shell reconciles
   * (display, toggle button state, panel sizes, resize handles), relayouts the
   * editor, and persists the new panel set exactly as a click would.
   *
   * The read side is the shell's **effective** truth rather than the value last
   * assigned, and the two can differ: hiding the last visible panel shows
   * another one instead (the app never leaves all three hidden), and a panel
   * this page shell has no element for reads `false` however it was set.
   *
   * Assigning before the app has booted is buffered and applied right after —
   * the stored panel preference is read during `mount()` and would otherwise
   * overwrite it — and reads back the buffered request until then.
   */
  get isEditorOpened(): boolean {
    return this.panelOpened('editor');
  }

  set isEditorOpened(next: boolean) {
    this.setPanelOpened('editor', next);
  }

  /**
   * Whether the markdown preview panel is showing; same contract as
   * {@link isEditorOpened}.
   */
  get isMarkdownPreviewOpened(): boolean {
    return this.panelOpened('preview');
  }

  set isMarkdownPreviewOpened(next: boolean) {
    this.setPanelOpened('preview', next);
  }

  /**
   * Whether the Open Lyric preview panel is showing; same contract as
   * {@link isEditorOpened}, plus one more gate: the panel belongs to the
   * notation plugin, so while that plugin is off the panel stays hidden and
   * this reads `false` whatever was assigned — which is why the topbar toggle
   * offers to enable the plugin there rather than showing the panel.
   */
  get isLyricPreviewOpened(): boolean {
    return this.panelOpened('openLyric');
  }

  set isLyricPreviewOpened(next: boolean) {
    this.setPanelOpened('openLyric', next);
  }

  /** The current document markdown (empty until mounted). */
  get value(): string {
    return this.isMounted ? currentDocumentValue() : '';
  }

  /**
   * Issue the **explicit save command** — the one Ctrl/Cmd+S, both topbar Save
   * buttons and the editor tools menu's Save all reach,
   * `DocumentController.saveCurrentDocument()`. With {@link saveValue} assigned
   * that lands on the host hook (the dashboard shadows the method for the
   * lifetime of the mount, so this needs no separate route); without it the
   * built-in `.md` download runs, exactly as a click would.
   *
   * More permissive than those buttons in one way: `syncEditorDirtyState()`
   * disables them while the document is clean and this stays available — a
   * host driving saves from its own chrome decides for itself whether a clean
   * document is worth writing. A no-op before the app has booted.
   */
  save(): void {
    this.assertNotDestroyed();
    if (!this.isApplicationBooted) {
      return;
    }
    this.applicationInstance?.documentController?.saveCurrentDocument?.();
  }

  /**
   * Reset — the topbar's Reset button and the counterpart of {@link save}: drop
   * the edits made since the last save and put the saved text back through the
   * app's own document pipeline, so the previews, the draft
   * ({@link onValueChange}) and the dirty flag all follow. A no-op when there
   * is nothing unsaved, and before the app has booted.
   *
   * The button confirms first, because the text it drops is the one thing
   * browser storage will not bring back. This does not: the caller is the
   * host's own chrome, which either already asked or knows it need not. Pass
   * `{ confirmFirst: true }` for the button's full behavior, prompt included.
   */
  reset({ confirmFirst = false }: OpenLyricDashboardResetOptions = {}): void {
    this.assertNotDestroyed();
    if (!this.isApplicationBooted) {
      return;
    }
    this.applicationInstance?.documentController?.discardUnsavedChanges?.({
      confirmFirst,
    });
  }

  /** The previews this dashboard owns, in mount order. */
  private get ownedPreviews(): OpenLyricPreviewComponent[] {
    return [this.openLyricMarkdownManagerRef, this.openLyricRef].filter(
      (preview): preview is OpenLyricPreviewComponent => Boolean(preview),
    );
  }

  /* ------------------------------ lifecycle ------------------------------ */

  protected override async handleMount(container: HTMLElement): Promise<void> {
    if (activeWrappedDashboard && activeWrappedDashboard !== this) {
      throw new Error(
        'Only one OpenLyricDashboard may wrap the application at a time.',
      );
    }

    // Build the shell the component owns when nothing has installed it yet.
    // A no-op for the app pages, whose entries call the static themselves
    // before installing the panels that mount inside it; this is the safety
    // net for a host that composes nothing but a dashboard. Refs are
    // refreshed only on an actual install, so mounting onto an existing shell
    // keeps the refs already resolved.
    if (installDashboardShellMarkup({ container })) {
      refreshElementRefs();
    }

    // Every fragment is now in place (the shell above, the panels from the
    // page entry's per-surface installs), so the cross-fragment pointers can
    // be resolved: mint a unique id per pointed-at element and rewrite the
    // `for` / `aria-controls` / `aria-labelledby` attributes onto it. Must
    // precede boot — the app reads and toggles these relationships.
    linkFragmentIds(container);

    const shellRoot = refs.app;
    if (
      !(shellRoot instanceof HTMLElement) ||
      !(container === shellRoot || container.contains(shellRoot))
    ) {
      throw new Error(
        'OpenLyricDashboard (wrap phase) requires the editor shell markup ' +
          '(#app) inside its container before mount().',
      );
    }

    // The style scope for everything the shell owns (styles/_scopes.scss). The
    // page markup carries it — the shell stays `display: none` until
    // `.app-ready`, which only works if the scope already matches — so this is
    // just the safety net for a host that builds its own `#app`.
    shellRoot.classList.add(OPEN_LYRIC_SCOPE_CLASS.dashboard);

    registerActiveDashboard(this);
    // The owned editor's plugin set decides which built-in shell plugins
    // register — this must precede boot, which consumes the registry.
    this.registerBuiltInPluginsFromComposition();
    const app = this.application;

    // Mount the owned previews on the real panels (adopt mode: the panel
    // element becomes the render root, so DOM shape, CSS, exporters and the
    // incremental render paths are untouched) and hand them to the
    // PreviewController so full re-renders flow through the components.
    const markdownManager = await this.mountOwnedPreview(
      this.openLyricMarkdownManagerRef,
      refs.preview,
    );
    const openLyric = await this.mountOwnedPreview(
      this.openLyricRef,
      refs.openLyricPreview,
    );
    if (markdownManager || openLyric) {
      app.previewController?.attachPreviewComponents?.({
        markdownManager,
        openLyric,
      });
      this.patchRestorers.push(() => {
        app.previewController?.attachPreviewComponents?.(null);
        for (const preview of this.ownedPreviews) {
          preview.destroy();
        }
      });
    }

    // Persistence hooks replace the localStorage draft backend, so they must
    // be in place before the app restores the initial document.
    await this.installDraftPersistenceHooks(app);
    // Before `bindEvents()` (inside `initialize()`) wires the Save button, so
    // the very first Ctrl/Cmd+S already reaches the host.
    this.installSaveCommandHook(app);
    this.applyWebOnlyChrome();
    // Teardown restores the chrome the host hid, whatever `isWeb` is by then.
    this.patchRestorers.push(() => this.applyWebOnlyChrome(false));

    await app.initialize();

    // The stored panel preference is in; whatever the host asked for before
    // boot displaces it now, and only now — `loadPreferences()` would have
    // overwritten an earlier write.
    this.applyPendingPanelVisibility();

    this.installThemeBridge(app);
    this.installChangeBridge(app);
    this.attachOwnedEditorFacade(app);
    this.lastValueText = currentDocumentValue();

    if (this.explicitTheme && state.theme !== this.explicitTheme) {
      app.themeController?.setTheme(this.explicitTheme);
    }
    // Adopt whatever theme the app resolved (preference/system/explicit).
    this.theme = resolveAppTheme();
    // The setter above only fans out when the value *changes*, and the owned
    // previews mounted before it ran, so push the resolved theme down here too.
    this.syncOwnedPreviewThemes(this.theme);
  }

  override unmount(): void {
    if (this.isMounted && !this.destroying) {
      throw new Error(
        'OpenLyricDashboard (wrap phase) cannot unmount; the wrapped ' +
          'application has no teardown. Call destroy() to detach the facade.',
      );
    }
    super.unmount();
  }

  override destroy(): void {
    this.destroying = true;
    try {
      super.destroy();
    } finally {
      this.destroying = false;
    }
  }

  protected override handleUnmount(): void {
    // Slots the host asked for are the dashboard's own DOM: take them back out
    // so teardown leaves the shell as it was found (a slot the host inlined in
    // its markup was adopted, never recorded here, and stays).
    for (const slot of this.ownedSlots.splice(0)) {
      slot.remove();
    }
    while (this.patchRestorers.length) {
      const restore = this.patchRestorers.pop();
      try {
        restore?.();
      } catch (error) {
        console.error('Open Lyric dashboard cleanup step failed.', error);
      }
    }
    if (activeWrappedDashboard === this) {
      activeWrappedDashboard = null;
    }
  }

  protected override handleReload(): void {
    const app = this.applicationInstance;
    app?.previewController?.renderPanels?.(currentDocumentValue());
    app?.layoutController?.updateShellPanels?.();
  }

  /** Host-driven theme → app (`ThemeController` persists it like the UI). */
  protected override handleThemeChange(theme: OpenLyricTheme): void {
    // Runs whether or not we are mounted, so an owned preview that was themed
    // before boot still follows a later `dashboard.theme = …`.
    this.syncOwnedPreviewThemes(theme);
    if (!this.isMounted || !this.applicationInstance) {
      return;
    }
    if (resolveAppTheme() !== theme) {
      this.applicationInstance.themeController?.setTheme(theme);
    }
  }

  /**
   * Push the dashboard's theme onto the previews it owns. They are adopt-mode
   * embeds, so their `[data-ol-theme]` marker sits on the real panel and is
   * what themes the rendered song view / fence cards
   * (`plugins/OpenLyric/preview/styles.scss` keys its dark variants off the
   * page attribute **or** that marker). Without this the panels keep the theme
   * they were constructed with while the app switches around them.
   */
  private syncOwnedPreviewThemes(theme: OpenLyricTheme): void {
    for (const preview of this.ownedPreviews) {
      if (preview.isDestroyed || preview.theme === theme) {
        continue;
      }
      preview.theme = theme;
    }
  }

  /**
   * Mount an owned preview component on a real panel container in adopt
   * mode. Skipped silently when the page has no such panel (editor-only
   * shell) or no component was assigned.
   */
  private async mountOwnedPreview(
    component: OpenLyricPreviewComponent | null,
    container: unknown,
  ): Promise<OpenLyricPreviewComponent | null> {
    if (!component || !(container instanceof HTMLElement)) {
      return null;
    }
    component.adoptContainer = true;
    component.container = container;
    await component.mount();
    return component;
  }

  /* ------------------------------- bridges -------------------------------- */

  /**
   * Shadow a **prototype** method on a live app object for the lifetime of
   * the mount, and queue its undo.
   *
   * This is how the wrap phase drives the running application: it intercepts
   * the app's own methods rather than forking them. Every target here is a
   * class instance whose methods sit on the prototype, so the shadow is an
   * own property and `delete` uncovers the original exactly.
   */
  private shadowMethod(
    target: any,
    name: string,
    replacement: (...args: any[]) => unknown,
  ): void {
    target[name] = replacement;
    this.patchRestorers.push(() => {
      delete target[name];
    });
  }

  /**
   * Swap an **own** member — a callback slot, or a method the target carries
   * itself — putting the previous value back on teardown.
   *
   * The counterpart of {@link shadowMethod}, for targets where `delete` would
   * remove the member outright instead of revealing an original underneath.
   */
  private swapMember(
    target: any,
    name: string,
    replacement: (...args: any[]) => unknown,
  ): void {
    const original = target[name];
    target[name] = replacement;
    this.patchRestorers.push(() => {
      target[name] = original;
    });
  }

  /**
   * Wrap phase: the owned editor's attached plugins are the page's
   * composition manifest. The one built-in the dashboard still registers is
   * the Open Lyric notation plugin (its runtime enable/disable preference
   * still applies inside the registrar) — the notation IS the core, so its
   * data lives in this bundle. Other plugins (transcript, any language
   * plugin) publish their own registry data from their component plugins'
   * `install()`, i.e. at `addPlugin()` time in the page entry, before this
   * runs — plugins that self-register need no entry here. Without an owned editor the notation
   * plugin follows the page shell mode.
   */
  private registerBuiltInPluginsFromComposition(): void {
    const editor = this.editorRef;
    registerBuiltInEditorPlugins({
      includeOpenLyricPlugin: editor
        ? editor.hasPlugin('open-lyric')
        : shouldRegisterBuiltInOpenLyricPlugin(),
    });
  }

  /**
   * Load the Monaco runtime for the wrapped application — through the owned
   * `Editor`'s loader, because Monaco is the editor component's concern:
   * a page overrides it with `new Editor({ loadMonacoResources })` and the
   * app it boots picks up the same loader, whether the editor mounts its own
   * surface (standalone) or facades the app's (here).
   *
   * Resolved per call rather than at construction: `editor` is assigned after
   * the dashboard is built, and the application only loads Monaco during
   * `mount()`. A dashboard with no editor assigned falls back to the shared
   * lazy chunk.
   */
  private loadMonacoResources() {
    const loadResources =
      this.editorRef?.monacoLoader ?? defaultLoadMonacoResources;
    return loadResources();
  }

  /**
   * Bridge the owned editor to the application's live surface (see
   * `Editor.attachSharedSurface`). Every accessor is live, so the app's
   * Monaco ⇄ simple-textarea swaps stay transparent; writes route through
   * the app's own document pipeline (previews, draft save, dirty marker).
   */
  private attachOwnedEditorFacade(app: any): void {
    const editor = this.editorRef;
    if (!editor) {
      return;
    }
    editor.attachSharedSurface({
      getValue: currentDocumentValue,
      setValue: (next: string) =>
        app.documentController?.applyDocumentContent?.({
          content: next,
          fileName: state.fileName,
          saveDraft: true,
        }),
      focusRange: (line: number, column: number) =>
        app.previewController?.jumpToEditorFence?.(line, column),
      focus: () => (state.editor as { focus?: () => void } | null)?.focus?.(),
      getMonaco: () => (globalThis as { monaco?: unknown }).monaco ?? null,
      getMonacoEditor: () => state.editor ?? null,
    });
    this.patchRestorers.push(() => {
      this.editorRef?.destroy();
    });
  }

  /**
   * Replace the app's draft backend with the host's
   * `loadValue`/`onValueChange`. `loadValue` is resolved once, up front,
   * because the app reads the draft synchronously during boot;
   * `onValueChange` runs synchronously up to its first await, which keeps the
   * beforeunload save path intact.
   */
  private async installDraftPersistenceHooks(app: any): Promise<void> {
    const preferences = app.preferences;
    if (!preferences) {
      return;
    }

    // `swapMember`, not `shadowMethod`: a host may pass a plain object as its
    // preferences backend, where `delete` would remove the method outright.
    if (typeof this.loadValue === 'function') {
      const injectedDraft = this.normalizeDraft(await this.loadValue());
      this.swapMember(preferences, 'loadDraft', () => injectedDraft);
    }

    if (typeof this.onValueChange === 'function') {
      this.swapMember(
        preferences,
        'saveDraft',
        (
          content: unknown,
          fileName: unknown,
          { sharedDocumentDate = '' }: { sharedDocumentDate?: string } = {},
        ) => {
          this.runHook(
            'onValueChange',
            this.onValueChange?.(String(content ?? ''), {
              fileName: String(fileName ?? ''),
              sharedDocumentDate: String(sharedDocumentDate ?? ''),
            }),
          );
        },
      );
    }
  }

  /**
   * Report a host hook's rejection without letting it escape into the app.
   * Both persistence hooks may be async and neither is awaited — the app's
   * own call sites are synchronous (the draft save runs on the beforeunload
   * path), so a failure is logged, never thrown.
   */
  private runHook(name: string, result: void | Promise<void>): void {
    void Promise.resolve(result).catch((error) => {
      console.error(`Open Lyric dashboard ${name} hook failed.`, error);
    });
  }

  /**
   * Route the app's **explicit save command** into the host's `saveValue`.
   *
   * Every way a user can issue it — the topbar overflow menu's Save, the
   * document-actions Save beside it, the editor tools menu's Save, and the
   * window-level Ctrl/Cmd+S handler, which clicks the first of those — lands
   * on `DocumentController.saveCurrentDocument()`, so shadowing that one
   * prototype method covers the whole command without touching the
   * keystroke. The default it displaces is the `.md` download; the separate
   * Download entry (which prompts for a file name) is left alone, and so is
   * the draft path — {@link installDraftPersistenceHooks} owns that.
   */
  private installSaveCommandHook(app: any): void {
    if (typeof this.saveValue !== 'function') {
      return;
    }
    const documentController = app.documentController;
    if (!documentController) {
      return;
    }

    this.shadowMethod(documentController, 'saveCurrentDocument', () => {
      const saveResult = this.saveValue?.(currentDocumentValue(), {
        fileName: String(state.fileName ?? ''),
        sharedDocumentDate: String(state.sharedDocumentDate ?? ''),
      });
      // Cleared synchronously, exactly as the built-in save does it: the flag
      // means "the user asked to save this document", not "the backend
      // acknowledged" — and an edit made while an async hook is still in
      // flight has to be free to set it again.
      markDirty(false);
      this.runHook('saveValue', saveResult);
    });
  }

  /**
   * Document value → dashboard `change` events (one-way mirror). Two entry
   * points cover every path: the editor edit pipeline
   * (`handleEditorContentChange`: typing in Monaco or the simple textarea)
   * and programmatic loads (`applyDocumentContent`: open file, reset
   * example, share import — which bypass the edit pipeline when no editor
   * surface is live).
   */
  private installChangeBridge(app: any): void {
    const emitIfValueChanged = () => {
      const newValue = currentDocumentValue();
      const oldValue = this.lastValueText;
      if (newValue === oldValue) {
        return;
      }
      this.lastValueText = newValue;
      // The owned editor facade mirrors the same shared document.
      this.editorRef?.notifySharedSurfaceValueChange();
      this.pluginHost.handleValueChange(oldValue, newValue);
      this.emitter.emit('change', { oldValue, newValue });
    };

    /** Run the app's own method, then report whatever it left behind. */
    const emitAfter = (target: any, name: string) => {
      const original = target[name].bind(target);
      this.shadowMethod(target, name, (...args: unknown[]) => {
        original(...args);
        emitIfValueChanged();
      });
    };

    emitAfter(app, 'handleEditorContentChange');
    if (app.documentController?.applyDocumentContent) {
      emitAfter(app.documentController, 'applyDocumentContent');
    }
  }

  /** App-driven theme changes (UI toggle, system) → dashboard events. */
  private installThemeBridge(app: any): void {
    const themeController = app.themeController;
    if (!themeController) {
      return;
    }
    // A constructor-assigned callback slot, not a prototype method, so this
    // has to restore by assignment — see `swapMember`.
    const originalOnThemeApplied = themeController.onThemeApplied;
    this.swapMember(themeController, 'onThemeApplied', (appliedTheme) => {
      if (typeof originalOnThemeApplied === 'function') {
        originalOnThemeApplied(appliedTheme);
      }
      // The base setter no-ops when unchanged, so this cannot loop.
      this.theme = resolveAppTheme();
    });
  }

  /* ------------------------------ internals ------------------------------ */

  /**
   * The topbar row the numbered slots live in.
   *
   * `html/dashboard-shell.html` ships it, so on every app page this is a
   * lookup; a host that inlined a shell of its own without one gets it created
   * at the head of the document-actions group, ahead of Reset/Save.
   */
  private resolveSlotHost(): HTMLElement {
    const root = this.container ?? refs.app;
    if (!(root instanceof HTMLElement)) {
      throw new Error(
        'getSlot() requires the dashboard shell markup; install it (or ' +
          'mount()) first.',
      );
    }

    const existing = root.querySelector(`.${SLOT_HOST_CLASS}`);
    if (existing instanceof HTMLElement) {
      return existing;
    }

    const documentActions = root.querySelector('.topbar-document-actions');
    if (!(documentActions instanceof HTMLElement)) {
      throw new Error(
        'getSlot() found no topbar to host slots; the dashboard shell markup ' +
          `must provide a .${SLOT_HOST_CLASS} row or a .topbar-document-actions group.`,
      );
    }
    const host = document.createElement('div');
    host.className = SLOT_HOST_CLASS;
    documentActions.prepend(host);
    return host;
  }

  /**
   * Show or hide the topbar chrome only a web host wants: the info
   * disclosure, the share-link entry, and the theme toggle — a native host
   * owns the OS/app theme, so the toggle goes with the rest.
   *
   * Resolved from `refs` on each call rather than captured, so teardown acts
   * on whatever the page has by then.
   */
  private applyWebOnlyChrome(hidden = !this.isWebValue): void {
    for (const element of [
      refs.topbarMeta,
      refs.shareLinkBtn,
      refs.themeToggleBtn,
    ]) {
      if (element instanceof HTMLElement) {
        element.hidden = hidden;
      }
    }
  }

  /**
   * Which panels the shell is actually showing, clamped exactly as the app
   * clamps them: `getEffectivePanelVisibility()` zeroes a panel this page shell
   * has no element for, gates the Open Lyric panel on the notation plugin, and
   * force-shows a fallback rather than let all three hide. Before boot there is
   * no controller worth asking, so the raw `state` seed
   * (`DEFAULT_PANEL_VISIBILITY` for this page shell) stands in.
   *
   * Read off `applicationInstance`, never `application`: a getter must not be
   * the thing that constructs the composition root.
   */
  private panelVisibility(): Record<PanelVisibilityKey, boolean> {
    const source =
      this.applicationInstance?.layoutController?.getEffectivePanelVisibility?.() ??
      state;
    return {
      editorVisible: Boolean(source.editorVisible),
      previewVisible: Boolean(source.previewVisible),
      openLyricVisible: Boolean(source.openLyricVisible),
    };
  }

  /** One panel's read side: the buffered request until boot, the shell after. */
  private panelOpened(key: DashboardPanelKey): boolean {
    const pending = this.pendingPanelVisibility[key];
    if (!this.isApplicationBooted && typeof pending === 'boolean') {
      return pending;
    }
    return this.panelVisibility()[PANEL_CONTROLLER_MEMBERS[key].visibleKey];
  }

  /** One panel's write side: the controller owns the rules, we only ask. */
  private setPanelOpened(key: DashboardPanelKey, next: boolean): void {
    this.assertNotDestroyed();
    const isOpened = Boolean(next);
    if (!this.isApplicationBooted) {
      this.pendingPanelVisibility[key] = isOpened;
      return;
    }
    const layoutController = this.applicationInstance?.layoutController;
    layoutController?.[PANEL_CONTROLLER_MEMBERS[key].setter]?.(isOpened);
  }

  /**
   * Apply the panel visibility the host asked for before boot.
   *
   * Opens go first, then hides — deliberately. Each controller setter carries
   * its own "never leave all three hidden" rescue, so hiding two panels before
   * showing the third trips that rescue and forces a panel the host asked to
   * hide back on. Three reconciles instead of one is the price of letting the
   * app's own rules decide, and each is cheap (style writes plus a coalesced
   * relayout frame).
   */
  private applyPendingPanelVisibility(): void {
    // From here the accessors talk to the live controller; the buffer's
    // entries stay behind this flag, unreachable.
    this.isApplicationBooted = true;
    const pending = Object.entries(this.pendingPanelVisibility) as Array<
      [DashboardPanelKey, boolean]
    >;
    for (const [key, isOpened] of [
      ...pending.filter(([, isNextOpened]) => isNextOpened),
      ...pending.filter(([, isNextOpened]) => !isNextOpened),
    ]) {
      this.setPanelOpened(key, isOpened);
    }
  }

  private normalizeDraft(
    input: OpenLyricDashboardDraft | string | null | undefined,
  ): {
    content: string;
    fileName: string;
    sharedDocumentDate: string;
    updatedAt: number;
  } | null {
    // A bare string is the same draft with everything else defaulted.
    const draft = typeof input === 'string' ? { content: input } : input;
    if (
      !draft ||
      typeof draft !== 'object' ||
      typeof draft.content !== 'string'
    ) {
      return null;
    }
    return {
      content: draft.content,
      fileName:
        typeof draft.fileName === 'string' && draft.fileName.trim()
          ? draft.fileName
          : 'untitled.md',
      sharedDocumentDate:
        typeof draft.sharedDocumentDate === 'string'
          ? draft.sharedDocumentDate
          : '',
      updatedAt: Date.now(),
    };
  }
}
