import {
  canRedoDocumentEdit,
  canUndoDocumentEdit,
  redoDocumentEdit,
  refs,
  setStatus,
  undoDocumentEdit,
} from '../../../../editor/scripts/shared.ts';

/**
 * Undo / Redo on the markdown preview panel.
 *
 * The editor panel's toolbar already has both, but a reader who works only in
 * the preview never sees that toolbar — and the in-preview gestures (delete a
 * section, rename one, save a verse) are exactly the ones they will want to
 * take back. These buttons sit in the panel's own floating tool row and walk
 * the **document's** history through `undoDocumentEdit`/`redoDocumentEdit`
 * (`editor/scripts/shared.ts`): Monaco's model history where Monaco is live —
 * the same stack the toolbar and Ctrl+Z in the text panel walk — and the
 * snapshot pairs the in-preview writes record everywhere else. An undo is a
 * text edit like any other, so the panel re-renders from the restored text.
 *
 * Markdown panel only: the controls are markup in `#previewPanel`, and the
 * keyboard shortcut is bound on that panel, so the lyric/presentation panel
 * grows neither.
 */

const PREVIEW_HISTORY_OPEN_EDITOR_MESSAGE =
  'Save or cancel the open edit before using Undo or Redo.';

function isTextEntryTarget(target) {
  if (!(target instanceof Element)) {
    return false;
  }

  return Boolean(
    target.closest(
      'input, textarea, select, [contenteditable=""], [contenteditable="true"]',
    ),
  );
}

/**
 * Which history command a keydown asks for, if any — Ctrl/Cmd+Z undo,
 * Ctrl/Cmd+Shift+Z or Ctrl+Y redo, matching the text panel's bindings.
 */
function getPreviewHistoryShortcutCommand(event) {
  if (!event || event.altKey || !(event.ctrlKey || event.metaKey)) {
    return null;
  }

  const key = String(event.key || '').toLowerCase();

  if (key === 'z') {
    return event.shiftKey ? 'redo' : 'undo';
  }

  if (key === 'y' && event.ctrlKey && !event.metaKey && !event.shiftKey) {
    return 'redo';
  }

  return null;
}

function applyPreviewControllerHistoryMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    /**
     * Whether an in-preview editor holds a draft right now. An undo re-renders
     * the panel, and a re-render drops whatever form was open in it — so
     * undoing while a verse is half-typed would silently throw the typing
     * away. The buttons stand down until the form is saved or cancelled.
     */
    hasOpenPreviewEditor(this: any) {
      return [
        this.previewSectionEditor,
        this.previewConfigTextEditor,
        this.previewSectionRenameEditor,
      ].some((editor) => Boolean(editor?.form?.isConnected));
    },

    syncPreviewHistoryControls(this: any) {
      const group = refs.markdownPreviewHistory;

      if (!(group instanceof HTMLElement)) {
        return;
      }

      // Same gate as the section pencils: a panel with no document behind it
      // (a read-only embed) has nothing to undo.
      const available = Boolean(this.canEditPreviewSections?.());
      group.hidden = !available;

      if (!available) {
        return;
      }

      const editorOpen = this.hasOpenPreviewEditor();
      const focusedButton = [
        refs.markdownPreviewUndoBtn,
        refs.markdownPreviewRedoBtn,
      ].find((button) => button && button === document.activeElement);

      [
        [refs.markdownPreviewUndoBtn, 'Undo', canUndoDocumentEdit()],
        [refs.markdownPreviewRedoBtn, 'Redo', canRedoDocumentEdit()],
      ].forEach(([button, label, possible]) => {
        if (!(button instanceof HTMLButtonElement)) {
          return;
        }

        button.disabled = editorOpen || !possible;
        const title = editorOpen
          ? `${label} (save or cancel the open edit first)`
          : possible
            ? label
            : `Nothing to ${String(label).toLowerCase()}`;
        button.title = title;
      });

      // Undoing the last step disables the Undo button the reader just
      // pressed, and a disabled button drops focus to <body> — a keyboard user
      // would have to find the panel again. Hand focus to the other history
      // button when it can take it (only ever a button that already had
      // focus, so the touch-iOS rule about auto-focusing is not in play).
      if (
        focusedButton instanceof HTMLButtonElement &&
        focusedButton.disabled
      ) {
        const sibling =
          focusedButton === refs.markdownPreviewUndoBtn
            ? refs.markdownPreviewRedoBtn
            : refs.markdownPreviewUndoBtn;

        if (sibling instanceof HTMLButtonElement && !sibling.disabled) {
          sibling.focus({ preventScroll: true });
        }
      }
    },

    runPreviewHistoryCommand(this: any, command) {
      if (!this.canEditPreviewSections?.()) {
        return false;
      }

      if (this.hasOpenPreviewEditor()) {
        setStatus(PREVIEW_HISTORY_OPEN_EDITOR_MESSAGE);
        this.syncPreviewHistoryControls();
        return false;
      }

      const focusedBefore = document.activeElement;
      const applied =
        command === 'redo' ? redoDocumentEdit() : undoDocumentEdit();

      // The simple textarea's history-aware write has to focus the textarea
      // to record itself; the reader pressed a button in the preview, so hand
      // focus back to where it was.
      if (
        focusedBefore instanceof HTMLElement &&
        focusedBefore !== document.activeElement &&
        focusedBefore.isConnected &&
        refs.previewPanel?.contains?.(focusedBefore)
      ) {
        focusedBefore.focus({ preventScroll: true });
      }

      // The document change re-renders the panel and re-syncs these through
      // `renderPreview`; syncing here too covers a command that changed
      // nothing and a surface whose change event arrives later.
      this.syncPreviewHistoryControls();
      return applied;
    },

    handlePreviewHistoryClick(this: any, event) {
      const button =
        event?.currentTarget instanceof HTMLButtonElement
          ? event.currentTarget
          : null;

      if (!button || button.disabled) {
        return;
      }

      event.preventDefault?.();
      this.runPreviewHistoryCommand(
        button === refs.markdownPreviewRedoBtn ? 'redo' : 'undo',
      );
    },

    /**
     * Ctrl/Cmd+Z inside the markdown panel. Text entries keep their own native
     * undo — the section textarea and the Config inputs are drafts, and
     * Ctrl+Z there should take back typing, not a saved edit.
     */
    handlePreviewHistoryKeydown(this: any, event) {
      const command = getPreviewHistoryShortcutCommand(event);

      if (
        !command ||
        event.defaultPrevented ||
        isTextEntryTarget(event.target)
      ) {
        return;
      }

      if (!this.canEditPreviewSections?.()) {
        return;
      }

      event.preventDefault();
      this.runPreviewHistoryCommand(command);
    },

    /**
     * Opening an in-preview editor moves focus into it and closing one moves
     * focus back out, but neither re-renders the panel — so focus changes are
     * the cue to re-check whether the buttons should stand down. Deferred a
     * task, because an editor can focus its field before it records itself
     * as open.
     */
    handlePreviewHistoryFocusChange(this: any) {
      clearTimeout(this.previewHistorySyncTimer);
      this.previewHistorySyncTimer = setTimeout(() => {
        this.previewHistorySyncTimer = 0;
        this.syncPreviewHistoryControls();
      }, 0);
    },

    bindPreviewHistoryEvents(this: any) {
      if (this.previewHistoryEventsBound) {
        return;
      }

      this.previewHistoryEventsBound = true;
      this.handlePreviewHistoryClick =
        this.handlePreviewHistoryClick.bind(this);
      this.handlePreviewHistoryKeydown =
        this.handlePreviewHistoryKeydown.bind(this);
      this.handlePreviewHistoryFocusChange =
        this.handlePreviewHistoryFocusChange.bind(this);

      refs.markdownPreviewUndoBtn?.addEventListener(
        'click',
        this.handlePreviewHistoryClick,
      );
      refs.markdownPreviewRedoBtn?.addEventListener(
        'click',
        this.handlePreviewHistoryClick,
      );

      const panel = refs.previewPanel || refs.preview;
      panel?.addEventListener('keydown', this.handlePreviewHistoryKeydown);
      refs.preview?.addEventListener(
        'focusin',
        this.handlePreviewHistoryFocusChange,
      );
      refs.preview?.addEventListener(
        'focusout',
        this.handlePreviewHistoryFocusChange,
      );

      this.syncPreviewHistoryControls();
    },
  });
}

export {
  applyPreviewControllerHistoryMethods,
  getPreviewHistoryShortcutCommand,
  PREVIEW_HISTORY_OPEN_EDITOR_MESSAGE,
};
