import { getDefaultDraftExample } from '../../default-draft-example.ts';
import { refs, setStatus, state } from '../../shared.ts';
import { loadDraftExamplesModule } from './constants.ts';

const RESET_EXAMPLE_OPTION_CLASS = 'reset-example-dialog__option';
const SELECTED_RESET_EXAMPLE_OPTION_CLASS =
  'reset-example-dialog__option--selected';
const SELECTED_RESET_EXAMPLE_OPTION_SELECTOR = `.${SELECTED_RESET_EXAMPLE_OPTION_CLASS}`;

function applyDocumentControllerResetExampleMethods(DocumentControllerClass) {
  Object.assign(DocumentControllerClass.prototype, {
    createResetExampleGroup(this: any, title, examples, selectedExampleId) {
      const section = document.createElement('section');
      const heading = document.createElement('p');
      const divider = document.createElement('hr');
      const options = document.createElement('div');

      section.className = 'reset-example-dialog__section';

      heading.className = 'reset-example-dialog__section-title';
      heading.textContent = title;

      divider.className = 'reset-example-dialog__section-divider';

      options.className = 'reset-example-dialog__section-options';
      options.append(
        ...examples.map((example) => {
          return this.createResetExampleOption(
            example,
            example.id === selectedExampleId,
          );
        }),
      );

      section.append(heading, divider, options);
      return section;
    },

    groupDraftExamples(this: any, draftExamples) {
      const groupedExamples = [];
      const groupsByTitle = new Map();

      draftExamples.forEach((example) => {
        const groupTitle =
          typeof example?.groupTitle === 'string' && example.groupTitle.trim()
            ? example.groupTitle.trim()
            : 'Other .md Examples';
        let group = groupsByTitle.get(groupTitle);

        if (!group) {
          group = {
            examples: [],
            title: groupTitle,
          };
          groupsByTitle.set(groupTitle, group);
          groupedExamples.push(group);
        }

        group.examples.push(example);
      });

      return groupedExamples;
    },

    /**
     * One card, and nothing behind it: the example's id rides on the element
     * as `data-example-id`, and picking it only moves a class
     * ({@link selectResetExampleOption}). Load reads the marked card back at
     * the moment it runs, so a click has no work to do and nothing to fail at.
     *
     * A button rather than a label around a hidden radio — the selection is no
     * longer a form value. `type="button"` is load-bearing: the dialog is a
     * `<form method="dialog">`, where a bare button would submit and close it.
     */
    createResetExampleOption(this: any, example, isSelected) {
      const option = document.createElement('button');
      const card = document.createElement('span');
      const title = document.createElement('span');
      const description = document.createElement('span');
      const fileName = document.createElement('span');

      option.type = 'button';
      option.className = RESET_EXAMPLE_OPTION_CLASS;
      option.dataset.exampleId = example.id;
      // The list is a radiogroup, so its options still answer as radios do.
      option.setAttribute('role', 'radio');
      this.setResetExampleOptionSelected(option, isSelected);

      card.className = 'reset-example-dialog__card';

      title.className = 'reset-example-dialog__option-title';
      title.textContent = example.title;

      description.className = 'reset-example-dialog__option-description';
      description.textContent = example.description;

      fileName.className = 'reset-example-dialog__option-file';
      fileName.textContent = example.fileName;

      card.append(title, description, fileName);
      option.append(card);
      return option;
    },

    setResetExampleOptionSelected(this: any, option, isSelected) {
      option.classList.toggle(
        SELECTED_RESET_EXAMPLE_OPTION_CLASS,
        Boolean(isSelected),
      );
      option.setAttribute('aria-checked', String(Boolean(isSelected)));
    },

    /** Move the mark to one card. The whole of what choosing an example does. */
    selectResetExampleOption(this: any, option) {
      const options =
        refs.resetExampleList?.querySelectorAll(
          `.${RESET_EXAMPLE_OPTION_CLASS}`,
        ) || [];

      for (const candidate of options) {
        this.setResetExampleOptionSelected(candidate, candidate === option);
      }
    },

    handleResetExampleOptionClick(this: any, event) {
      const option = event?.target?.closest?.(`.${RESET_EXAMPLE_OPTION_CLASS}`);

      if (!option || !refs.resetExampleList?.contains(option)) {
        return;
      }

      this.selectResetExampleOption(option);
    },

    async getDraftExamples(this: any) {
      const module = await loadDraftExamplesModule();
      return Array.isArray(module.getDraftExamples?.())
        ? module.getDraftExamples()
        : Array.isArray(module.DRAFT_EXAMPLES)
          ? module.DRAFT_EXAMPLES
          : [];
    },

    async resolveDraftExampleById(this: any, exampleId) {
      try {
        const module = await loadDraftExamplesModule();
        return (
          module.getDraftExampleById?.(exampleId) || getDefaultDraftExample()
        );
      } catch (error) {
        console.error('Failed to resolve draft example.', error);
        return getDefaultDraftExample();
      }
    },

    setResetExampleDialogMessage(this: any, message) {
      if (refs.resetExampleList) {
        refs.resetExampleList.textContent = message;
      }

      if (refs.loadSelectedExampleBtn) {
        refs.loadSelectedExampleBtn.disabled = true;
      }
    },

    async renderResetExampleOptions(
      this: any,
      selectedExampleId = this.selectedResetExampleId,
    ) {
      if (!refs.resetExampleList) {
        return;
      }

      const draftExamples = await this.getDraftExamples();
      const groupedExamples = this.groupDraftExamples(draftExamples);

      refs.resetExampleList.replaceChildren(
        ...groupedExamples.map((group) => {
          return this.createResetExampleGroup(
            group.title,
            group.examples,
            selectedExampleId,
          );
        }),
      );

      // The list always shows one card marked, so Load always has one to find
      // — the example this dialog last loaded, or the first one offered.
      const options = refs.resetExampleList.querySelectorAll(
        `.${RESET_EXAMPLE_OPTION_CLASS}`,
      );

      if (options.length && !this.getSelectedResetExampleId()) {
        this.selectResetExampleOption(options[0]);
      }

      this.updateResetExampleLoadButton();
    },

    getSelectedResetExampleId(this: any) {
      return (
        refs.resetExampleList
          ?.querySelector(SELECTED_RESET_EXAMPLE_OPTION_SELECTOR)
          ?.getAttribute('data-example-id') || ''
      );
    },

    updateResetExampleLoadButton(this: any) {
      if (refs.loadSelectedExampleBtn) {
        refs.loadSelectedExampleBtn.disabled =
          !this.getSelectedResetExampleId();
      }
    },

    async openResetExampleDialog(this: any) {
      if (!refs.resetExampleDialog) {
        this.resetDocument();
        return;
      }

      if (!refs.resetExampleDialog.open) {
        refs.resetExampleDialog.showModal();
      }

      this.setResetExampleDialogMessage('Loading examples...');

      try {
        await this.renderResetExampleOptions(this.selectedResetExampleId);
      } catch (error) {
        console.error('Failed to load reset examples.', error);
        this.setResetExampleDialogMessage('Unable to load examples.');
        setStatus('Failed to load draft examples');
      }
    },

    handleResetExampleDialogClose(this: any) {
      state.editor?.focus();
    },

    loadBlankResetExample(this: any) {
      refs.resetExampleDialog?.close('blank');
      this.applyDocumentContent({
        content: '',
        fileName: 'untitled.md',
        saveDraft: true,
        dirty: true,
      });
    },

    async loadSelectedResetExample(this: any) {
      const selectedExample = await this.resolveDraftExampleById(
        this.getSelectedResetExampleId(),
      );

      this.selectedResetExampleId = selectedExample.id;
      refs.resetExampleDialog?.close(selectedExample.id);
      this.loadDraftExample(selectedExample);
    },
  });
}

export { applyDocumentControllerResetExampleMethods };
