import {
  normalizeConfigFieldName,
  readDocumentLineRange,
  refs,
  replaceDocumentLineRange,
} from '../../../../editor/scripts/shared.ts';

/**
 * In-preview editing of the free-text `Config` fields — Title, Subtitle,
 * Description, Artist, Copyright, Theme, Genre and Style.
 *
 * `Key`, `Time`, `Tempo`, `Locales`, `Structure`, `Attachments` and the
 * strumming patterns all have a picker of their own already. These eight have
 * nothing to pick from: the reader types them. So the affordance is the value
 * itself — click it, or the pencil beside it, which is what a keyboard reaches
 * — and the rendered value is replaced in place by a text input holding the
 * field's *source* value. Save writes that one line back through
 * `replaceDocumentLineRange` and the panel re-renders from the new document
 * text; the preview never keeps a DOM mutation of its own, so both panels,
 * Monaco and the undo stack stay in step.
 *
 * Two things make the write safe against markup a re-render has left behind:
 * only a line number travels on the control, and the line is re-read from the
 * document and re-checked for this field's name before anything is replaced.
 * The reader's text is also only ever written *after* the `- Field:` prefix the
 * document already had, so an in-preview edit cannot invent a field, close the
 * fence, or split one line into two.
 *
 * Markdown panel only. The lyric/presentation panel shares these delegated
 * listeners, so every lookup here is scoped to `refs.preview`.
 */

/** `- Title:   Amazing Grace` → prefix, field name, separator, value. */
const CONFIG_FIELD_LINE_RE = /^(\s*-\s*([^:]+):)([ \t]*)(.*)$/;

/**
 * What a reader types has to stay one line of a `Config` field.
 *
 * Newlines are the only characters that could turn one field into two — a
 * pasted multi-line value is the realistic way in — so they collapse to
 * spaces; the surrounding whitespace goes because the source line's own
 * separator supplies it.
 */
function normalizeConfigTextValue(value) {
  return String(value ?? '')
    .replace(/[\r\n\u2028\u2029]+/g, ' ')
    .trim();
}

/** The line as it should read once `nextValue` is in it, or `null`. */
function buildConfigTextFieldLine(sourceLine, fieldName, nextValue) {
  const fieldMatch = String(sourceLine ?? '').match(CONFIG_FIELD_LINE_RE);

  if (!fieldMatch) {
    return null;
  }

  if (normalizeConfigFieldName(fieldMatch[2].trim()) !== fieldName) {
    return null;
  }

  const normalizedValue = normalizeConfigTextValue(nextValue);
  // A field the Add Config menu just inserted is a bare `- Artist:` with
  // nothing after the colon, so the first value written into it brings its own
  // space; clearing a field takes the separator away again rather than leaving
  // trailing whitespace behind.
  const separatorText = normalizedValue ? fieldMatch[3] || ' ' : '';

  return `${fieldMatch[1]}${separatorText}${normalizedValue}`;
}

/** The field's current value as the document holds it, or `null`. */
function readConfigTextFieldValue(sourceLine, fieldName) {
  const fieldMatch = String(sourceLine ?? '').match(CONFIG_FIELD_LINE_RE);

  if (!fieldMatch) {
    return null;
  }

  if (normalizeConfigFieldName(fieldMatch[2].trim()) !== fieldName) {
    return null;
  }

  return fieldMatch[4].replace(/\s+$/, '');
}

function applyPreviewControllerConfigTextEditingMethods(
  PreviewControllerClass,
) {
  Object.assign(PreviewControllerClass.prototype, {
    /**
     * A full or incremental re-render replaces the markup the open field editor
     * lived in. Nothing is recoverable at that point, so drop the reference
     * rather than leave `Save` pointing at a detached input.
     */
    syncPreviewConfigTextEditorState(this: any) {
      const fieldEditor = this.previewConfigTextEditor;

      if (!fieldEditor) {
        return;
      }

      if (!fieldEditor.form?.isConnected) {
        this.previewConfigTextEditor = null;
      }
    },

    /** The pencil for one field, looked up after a re-render replaced it. */
    getPreviewConfigTextEditorTrigger(this: any, fieldName) {
      if (!fieldName || !(refs.preview instanceof HTMLElement)) {
        return null;
      }

      return (
        Array.from(
          refs.preview.querySelectorAll(
            '[data-preview-action="edit-config-text-field"]',
          ),
        ).find((element) => {
          return (
            normalizeConfigFieldName(
              element.getAttribute('data-config-field') || '',
            ) === fieldName
          );
        }) || null
      );
    },

    buildPreviewConfigTextEditorForm(this: any, { label, value }) {
      const form = document.createElement('form');
      const input = document.createElement('input');
      const actions = document.createElement('span');
      const saveButton = document.createElement('button');
      const cancelButton = document.createElement('button');

      form.className = 'ol-preview-config__text-editor';
      form.setAttribute('data-preview-config-text-editor', 'true');
      form.noValidate = true;

      input.className = 'ol-preview-config__text-editor-input';
      input.setAttribute('data-preview-config-text-editor-input', 'true');
      input.type = 'text';
      input.setAttribute('aria-label', label);
      input.value = value;

      actions.className = 'ol-preview-config__text-editor-actions';

      saveButton.className =
        'ol-preview-config__text-editor-button ol-preview-config__text-editor-button--save';
      saveButton.type = 'submit';
      saveButton.setAttribute('data-preview-action', 'save-config-text-field');
      saveButton.textContent = 'Save';

      cancelButton.className = 'ol-preview-config__text-editor-button';
      cancelButton.type = 'button';
      cancelButton.setAttribute(
        'data-preview-action',
        'cancel-config-text-field',
      );
      cancelButton.textContent = 'Cancel';

      actions.append(saveButton, cancelButton);
      form.append(input, actions);

      return { form, input };
    },

    /**
     * Open the in-place editor for one free-text field.
     *
     * The seed comes from the document, never from the rendered value: the
     * rendered value is escaped, inline-rendered output, while the input has to
     * hold the notation the reader is about to change.
     */
    openPreviewConfigTextEditor(this: any, trigger) {
      if (!(trigger instanceof HTMLElement)) {
        return false;
      }

      if (!(refs.preview instanceof HTMLElement)) {
        return false;
      }

      if (!refs.preview.contains(trigger) || !this.canEditPreviewSections()) {
        return false;
      }

      const container = trigger.closest('.ol-preview-config__text-value');
      const display = container?.querySelector(
        '.ol-preview-config__text-display',
      );

      if (
        !(container instanceof HTMLElement) ||
        !(display instanceof HTMLElement)
      ) {
        return false;
      }

      const fieldName = normalizeConfigFieldName(
        trigger.getAttribute('data-config-field') || '',
      );
      const lineNumber = Number(
        trigger.getAttribute('data-preview-config-line'),
      );

      if (!fieldName || !Number.isInteger(lineNumber) || lineNumber < 1) {
        return false;
      }

      const sourceLines = readDocumentLineRange(lineNumber, lineNumber);
      const currentValue = sourceLines?.length
        ? readConfigTextFieldValue(sourceLines[0], fieldName)
        : null;

      // The line the control points at no longer declares this field, so the
      // markup is stale. Opening an editor over it would write the reader's
      // text into whatever moved there instead.
      if (currentValue === null) {
        return false;
      }

      this.closePreviewConfigTextEditor({ focusTrigger: false });

      const fieldLabel =
        trigger.getAttribute('data-config-field-label') || fieldName;
      const { form, input } = this.buildPreviewConfigTextEditorForm({
        label: fieldLabel,
        value: currentValue,
      });

      display.hidden = true;
      trigger.hidden = true;
      container.append(form);
      container.dataset.olConfigTextEditorOpen = 'true';
      trigger.setAttribute('aria-expanded', 'true');

      this.previewConfigTextEditor = {
        container,
        display,
        fieldLabel,
        fieldName,
        form,
        input,
        lineNumber,
      };

      form.addEventListener('submit', this.handlePreviewConfigTextEditorSubmit);
      form.addEventListener(
        'keydown',
        this.handlePreviewConfigTextEditorKeyDown,
      );

      // A text input is the sanctioned auto-focus case on touch iOS/iPadOS —
      // the rule there is about buttons and menuitems swallowing the next tap.
      this.focusElement(input, { preventScroll: true });
      input.setSelectionRange(input.value.length, input.value.length);

      return true;
    },

    /**
     * Take the editor back out of the row, restoring the rendered value.
     *
     * Idempotent, and safe on markup a re-render has already detached — which
     * is how `savePreviewConfigTextEditor` can run it either side of the write
     * without caring whether the panel re-rendered in between.
     */
    teardownPreviewConfigTextEditor(this: any, fieldEditor) {
      if (!fieldEditor) {
        return null;
      }

      const { container, display, fieldName, form } = fieldEditor;

      form?.removeEventListener(
        'submit',
        this.handlePreviewConfigTextEditorSubmit,
      );
      form?.removeEventListener(
        'keydown',
        this.handlePreviewConfigTextEditorKeyDown,
      );
      form?.remove();

      if (display instanceof HTMLElement) {
        display.hidden = false;
      }

      if (container instanceof HTMLElement) {
        delete container.dataset.olConfigTextEditorOpen;
      }

      // After a re-render the row is new markup, so the pencil to hand focus
      // back to is looked up by field name, not held onto.
      const trigger =
        this.getPreviewConfigTextEditorTrigger(fieldName) ||
        container?.querySelector?.(
          '[data-preview-action="edit-config-text-field"]',
        ) ||
        null;

      if (trigger instanceof HTMLElement) {
        trigger.hidden = false;
        trigger.setAttribute('aria-expanded', 'false');
      }

      return trigger;
    },

    closePreviewConfigTextEditor(this: any, { focusTrigger = true } = {}) {
      const fieldEditor = this.previewConfigTextEditor;

      if (!fieldEditor) {
        return false;
      }

      this.previewConfigTextEditor = null;

      const trigger = this.teardownPreviewConfigTextEditor(fieldEditor);

      if (focusTrigger) {
        this.focusElement(trigger, {
          preventScroll: true,
          skipTouchIosForButtons: true,
        });
      }

      return true;
    },

    /** Write the input back over the field's own source line. */
    savePreviewConfigTextEditor(this: any) {
      const fieldEditor = this.previewConfigTextEditor;

      if (!fieldEditor) {
        return false;
      }

      if (!fieldEditor.form?.isConnected) {
        this.previewConfigTextEditor = null;
        return false;
      }

      const { fieldName, input, lineNumber } = fieldEditor;
      const sourceLines = readDocumentLineRange(lineNumber, lineNumber);

      if (!sourceLines?.length) {
        return false;
      }

      const nextLine = buildConfigTextFieldLine(
        sourceLines[0],
        fieldName,
        input?.value,
      );

      // The document moved under the open editor and that line is no longer
      // this field. Close rather than overwrite something else.
      if (nextLine === null) {
        this.closePreviewConfigTextEditor({ focusTrigger: true });
        return false;
      }

      if (nextLine === sourceLines[0]) {
        this.closePreviewConfigTextEditor({ focusTrigger: true });
        return true;
      }

      const previewScrollTop =
        refs.preview instanceof HTMLElement ? refs.preview.scrollTop : 0;

      // Dropped before the write: applying it re-renders the panel
      // synchronously, which takes this form's DOM with it.
      this.previewConfigTextEditor = null;

      const applied = replaceDocumentLineRange(lineNumber, lineNumber, [
        nextLine,
      ]);

      if (!applied) {
        this.previewConfigTextEditor = fieldEditor;
        return false;
      }

      // The write re-renders the panel, which usually takes this form with it —
      // but the incremental render paths patch only part of the panel, so the
      // teardown runs unconditionally rather than relying on that.
      const trigger = this.teardownPreviewConfigTextEditor(fieldEditor);

      // A re-render resets the panel's scroll and blurs whatever was focused.
      // Both are put back so renaming a song does not throw the reader to the
      // top of the document.
      if (refs.preview instanceof HTMLElement) {
        refs.preview.scrollTop = previewScrollTop;
      }

      this.focusElement(trigger, {
        preventScroll: true,
        skipTouchIosForButtons: true,
      });

      return true;
    },

    handlePreviewConfigTextEditorSubmit(this: any, event) {
      event.preventDefault();
      this.savePreviewConfigTextEditor();
    },

    handlePreviewConfigTextEditorKeyDown(this: any, event) {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        this.closePreviewConfigTextEditor({ focusTrigger: true });
      }
    },

    isPreviewConfigTextEditorElement(this: any, element) {
      if (!(element instanceof Element)) {
        return false;
      }

      return Boolean(element.closest('.ol-preview-config__text-editor'));
    },

    /**
     * The value itself is a click target too, so the affordance a reader finds
     * first is the one they were already looking at. Clicks that land on the
     * inline renderer's own controls — a chord button, a link — belong to those
     * controls and are left alone.
     */
    getPreviewConfigTextEditorTriggerForDisplay(this: any, element) {
      if (!(element instanceof Element)) {
        return null;
      }

      const display = element.closest('.ol-preview-config__text-display');

      if (!display || !refs.preview?.contains(display)) {
        return null;
      }

      if (element.closest('a, button, [data-preview-action]')) {
        return null;
      }

      return (
        display.parentElement?.querySelector(
          '[data-preview-action="edit-config-text-field"]',
        ) || null
      );
    },
  });
}

export {
  applyPreviewControllerConfigTextEditingMethods,
  buildConfigTextFieldLine,
  normalizeConfigTextValue,
  readConfigTextFieldValue,
};
